function requiredElement<T extends Element>(selector: string): T {
  const element = document.querySelector<T>(selector);
  if (!element) throw new Error(`必須の画面要素がありません: ${selector}`);
  return element;
}
const app = requiredElement<HTMLElement>('#app'), modalRoot = requiredElement<HTMLElement>('#modal-root');
function animationProgress(element: HTMLElement | null, loops: boolean): number | null {
  const animation = element?.getAnimations()[0];
  const currentTime = animation?.currentTime;
  const duration = animation?.effect?.getComputedTiming().duration;
  if (typeof currentTime !== 'number' || typeof duration !== 'number' || duration <= 0) return null;

  const progress = currentTime / duration;
  return loops ? ((progress % 1) + 1) % 1 : Math.min(1, Math.max(0, progress));
}
function restoreAnimationProgress(element: HTMLElement | null, progress: number | null): void {
  if (progress === null) return;
  const animation = element?.getAnimations()[0];
  const duration = animation?.effect?.getComputedTiming().duration;
  if (animation && typeof duration === 'number' && duration > 0) {
    animation.currentTime = Math.min(1, Math.max(0, progress)) * duration;
  }
}
function animationElapsedMs(element: HTMLElement | null): number | null {
  const currentTime = element?.getAnimations()[0]?.currentTime;
  return typeof currentTime === 'number' ? currentTime : null;
}
function restoreAnimationElapsedMs(element: HTMLElement | null, elapsedMs: number | null): void {
  if (elapsedMs === null) return;
  const animation = element?.getAnimations()[0];
  const duration = animation?.effect?.getComputedTiming().duration;
  if (animation && typeof duration === 'number' && duration > 0) {
    animation.currentTime = Math.min(Math.max(0, elapsedMs), duration);
  }
}
function syncTurnProgressDom(): void {
  if (turnCycleStartedAt !== null) {
    turnProgress = Math.max(0, Math.min(1, (performance.now() - turnCycleStartedAt) / turnCycleDurationMs));
  }
  const percentage = turnProgress * 100;
  document.querySelectorAll<HTMLElement>('.turn-progress-fill').forEach(fill => {
    fill.style.width = `${percentage}%`;
    fill.parentElement?.setAttribute('aria-valuenow', String(Math.round(percentage)));
  });
  document.querySelectorAll<HTMLElement>('.countdown-meter-fill').forEach(fill => {
    const remaining = Math.max(0, Number(fill.dataset.remaining) - turnProgress);
    const max = Math.max(1, Number(fill.dataset.max));
    fill.style.width = `${Math.max(0, Math.min(100, remaining / max * 100))}%`;
    fill.parentElement?.setAttribute('aria-valuenow', String(Math.ceil(remaining)));
  });
}
function animateTurnProgress(): void {
  turnProgressFrame = null;
  syncTurnProgressDom();
  if (turnCycleStartedAt !== null && turnProgress < 1) turnProgressFrame = requestAnimationFrame(animateTurnProgress);
  else turnCycleStartedAt = null;
}
function startTurnProgress(duration: number): void {
  if (turnProgressFrame !== null) cancelAnimationFrame(turnProgressFrame);
  turnProgressFrame = null;
  turnProgress = 0;
  turnCycleDurationMs = Math.max(1, duration);
  turnCycleStartedAt = performance.now();
  syncTurnProgressDom();
  turnProgressFrame = requestAnimationFrame(animateTurnProgress);
}
function stopTurnProgress(): void {
  syncTurnProgressDom();
  turnCycleStartedAt = null;
  if (turnProgressFrame !== null) cancelAnimationFrame(turnProgressFrame);
  turnProgressFrame = null;
  syncTurnProgressDom();
}
function preserveNewsTickerProgress(): void {
  const flowProgress = animationProgress(app.querySelector<HTMLElement>('.news-ticker-track'), true);
  if (flowProgress !== null) newsTickerProgress = flowProgress;

  const casualtyTrack = app.querySelector<HTMLElement>('.news-casualty-track');
  if (!casualtyTrack) return;

  const ids = casualtyTrack.dataset.broadcastIds || casualtyTrack.dataset.casualtyIds || '';
  if (casualtyTickerIds !== ids) {
    casualtyTickerIds = ids;
    casualtyTickerProgress = null;
    casualtyTickerElapsedMs = null;
  }
  const progress = animationProgress(casualtyTrack, false);
  if (progress !== null) casualtyTickerProgress = progress;
  const elapsedMs = animationElapsedMs(casualtyTrack);
  if (elapsedMs !== null) casualtyTickerElapsedMs = elapsedMs;
}
