function navBadge(id: ViewId): string {
  if (id === 'maps') {
    const offers = state.dungeons.reduce((n, d) => n + (d.owned ? d.offers.length : 0), 0);
    return offers > 0 ? `<small class="nav-alert">${offers}</small>` : '';
  }
  if (id === 'hq') {
    return investmentQuote(state, 'hq', '', '').ok ? '<small class="nav-alert">▲</small>' : '';
  }
  if (id === 'intel') {
    const count = state.rumors.filter(r => r.type === 'discovery' && state.dungeons.some(d => d.id === r.targetId && d.phase === 'rumor')).length;
    return count > 0 ? `<small>${count}</small>` : '';
  }
  if (id === 'events') {
    const active = state.events.filter(e => e.state === 'active' && !e.contributed && canReceiveKingdomSupport(e.type)).length;
    return active > 0 ? `<small class="nav-alert">${active}</small>` : '';
  }
  return '';
}

