function pauseAutoTurn(): void {
  if (turnTimer !== null) clearTimeout(turnTimer);
  turnTimer = null;
  stopTurnProgress();
}

function scheduleAutoTurn(): void {
  if (turnTimer || autoTurnBlocked() || document.hidden) return;
  const duration = Math.ceil((onboardingFocus() ? Math.ceil(TURN_INTERVAL_MS / 3) : TURN_INTERVAL_MS) / (ui.timeSpeed ?? 1));
  startTurnProgress(duration);
  turnTimer = setTimeout(() => {
    turnTimer = null;
    turnProgress = 1;
    turnCycleStartedAt = null;
    if (turnProgressFrame !== null) cancelAnimationFrame(turnProgressFrame);
    turnProgressFrame = null;
    syncTurnProgressDom();
    tick();
  }, duration);
}

function animateHudCash(targetValue: number): void {
  cashTarget = Math.round(targetValue);
  const display = app.querySelector('#hud-cash-value');
  if (!display) return;
  if (displayedCash === null) displayedCash = cashTarget;
  display.innerHTML = money(displayedCash ?? 0);
  if (cashAnimationTimer || displayedCash === cashTarget) return;
  cashAnimationTimer = setInterval(() => {
    displayedCash = moneyStep(displayedCash ?? 0, cashTarget ?? 0);
    const current = app.querySelector('#hud-cash-value');
    if (current) current.innerHTML = money(displayedCash ?? 0);
    if (displayedCash === cashTarget) {
      if (cashAnimationTimer !== null) clearInterval(cashAnimationTimer);
      cashAnimationTimer = null;
    }
  }, 20);
}

function animateHudBaseCash(baseId: string | null, targetValue: number | null): void {
  const display = app.querySelector('#hud-base-cash-value');
  if (!display || targetValue === null || !baseId) {
    if (baseCashAnimationTimer !== null) clearInterval(baseCashAnimationTimer);
    baseCashAnimationTimer = null;
    displayedBaseCash = null;
    lastAnimatedBaseId = null;
    return;
  }
  baseCashTarget = Math.round(targetValue);
  if (displayedBaseCash === null || lastAnimatedBaseId !== baseId) {
    displayedBaseCash = baseCashTarget;
    lastAnimatedBaseId = baseId;
  }
  display.innerHTML = money(displayedBaseCash ?? 0);
  if (baseCashAnimationTimer || displayedBaseCash === baseCashTarget) return;
  baseCashAnimationTimer = setInterval(() => {
    displayedBaseCash = moneyStep(displayedBaseCash ?? 0, baseCashTarget ?? 0);
    const current = app.querySelector('#hud-base-cash-value');
    if (current) current.innerHTML = money(displayedBaseCash ?? 0);
    if (displayedBaseCash === baseCashTarget) {
      if (baseCashAnimationTimer !== null) clearInterval(baseCashAnimationTimer);
      baseCashAnimationTimer = null;
    }
  }, 20);
}

function wagonPositionWithinLane(wagon: HTMLElement, position: number): number {
  const laneWidth = wagon.parentElement?.clientWidth ?? 0;
  if (!laneWidth) return position;
  const edge = Math.min(laneWidth / 2, wagon.offsetWidth / 2 + 4);
  const min = edge / laneWidth * 100, max = 100 - min;
  return Math.max(min, Math.min(max, position));
}

function animateWagonPositions(previous: ReadonlyMap<string, number>): void {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  for (const wagon of app.querySelectorAll<HTMLElement>('.supply-wagon:not([data-mini])')) {
    const id = wagon.dataset.wagonId;
    const previousPosition = id ? previous.get(id) : undefined;
    const from = previousPosition === undefined ? undefined : wagonPositionWithinLane(wagon, previousPosition);
    const rawTo = Number.parseFloat(wagon.style.getPropertyValue('--supply-position'));
    const to = Number.isFinite(rawTo) ? wagonPositionWithinLane(wagon, rawTo) : rawTo;
    if (from === undefined || !Number.isFinite(to) || from === to) continue;
    wagon.animate([{ left: `${from}%` }, { left: `${to}%` }], { duration: 420, easing: 'ease-out' });
  }
}

function animateMiniWagonPositions(previous: ReadonlyMap<string, { x: number; y: number }>): void {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  for (const wagon of app.querySelectorAll<HTMLElement>('.supply-wagon[data-mini]')) {
    const id = wagon.dataset.wagonId;
    const prev = id ? previous.get(id) : undefined;
    const rawToX = Number.parseFloat(wagon.style.getPropertyValue('--mini-cell-x'));
    const rawToY = Number.parseFloat(wagon.style.getPropertyValue('--mini-cell-y'));
    if (!prev || !Number.isFinite(rawToX) || !Number.isFinite(rawToY)) continue;
    if (prev.x === rawToX && prev.y === rawToY) continue;
    const fromLeft = `calc((${prev.x} + .5) * 25%)`;
    const fromTop = `calc((${prev.y} + .5) * 25%)`;
    const toLeft = `calc((${rawToX} + .5) * 25%)`;
    const toTop = `calc((${rawToY} + .5) * 25%)`;
    wagon.animate([{ left: fromLeft, top: fromTop }, { left: toLeft, top: toTop }], { duration: 420, easing: 'ease-out' });
  }
}

