function dismissToast(): void {
  const el = document.getElementById('toast');
  if (!el) return;
  el.className = '';
  document.body.classList.remove('toast-active');
  clearTimeout(toastTimer);
  toastTimer = undefined;
}

function toast(text: string, error = false, image?: { src: string; alt: string }): void {
  const el = document.getElementById('toast');
  if (!el) return;
  const messageElement = document.createElement('span');
  messageElement.className = 'toast-message';
  messageElement.textContent = text;

  const closeButton = document.createElement('button');
  closeButton.type = 'button';
  closeButton.className = 'toast-close-btn';
  closeButton.dataset.action = 'dismiss-toast';
  const lang = state?.lang || ui?.lang || 'ja';
  closeButton.setAttribute('aria-label', t('close_btn', lang));
  closeButton.textContent = '✕';
  closeButton.addEventListener('click', e => {
    e.stopPropagation();
    dismissToast();
  });

  if (image) {
    const imageElement = document.createElement('img');
    imageElement.src = image.src;
    imageElement.alt = image.alt;
    el.replaceChildren(imageElement, messageElement, closeButton);
  } else {
    el.replaceChildren(messageElement, closeButton);
  }
  el.className = `visible ${error ? 'error' : ''} ${image ? 'with-image' : ''}`.trim();
  document.body.classList.add('toast-active');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(dismissToast, 6500);
}

function persistUI(): void {
  if (!autosaveEnabled) return;
  try {
    saveLocalUI({
      view: ui.view,
      base: ui.base,
      intelAdBase: ui.intelAdBase,
      intelAdDungeon: ui.intelAdDungeon,
      dungeon: ui.dungeon,
      region: ui.region,
      selectedDungeon: ui.selectedDungeon,
      baseTab: ui.baseTab,
      disclosures: ui.disclosures || {},
      newsExpanded: ui.newsExpanded,
      myPageWidgets: ui.myPageWidgets ? [...ui.myPageWidgets] : undefined,
    });
  } catch {}
}

function persist(manual = false): void {
  if (!autosaveEnabled && !manual) return;
  try {
    saveLocal(state);
    persistUI();
    lastSave = `${turnLabel(state.turn, ui.lang)} ${ui.lang === 'en' ? 'Saved' : '保存済み'}`;
    autosaveEnabled = true;
    if (manual) toast(state.lang === 'en' ? 'Game saved.' : 'ゲームを保存しました。');
  } catch (error) {
    autosaveEnabled = false;
    console.error('Failed to save to browser storage:', error);
    toast(state.lang === 'en' ? 'Cannot save to browser storage. Please export your save data from Settings.' : 'ブラウザへ保存できません。「設定・記録」からセーブを書き出してください。', true);
  }
}

