function availableName(names: readonly string[], start: number, usedNames: ReadonlySet<string>): string {
  for (let offset = 0; offset < names.length; offset++) {
    const name = names[(start + offset) % names.length];
    if (!usedNames.has(name)) return name;
  }
  const name = names[start];
  let generation = 2;
  while (usedNames.has(`${name}・第${generation}隊`)) generation++;
  return `${name}・第${generation}隊`;
}

// Callers supply their existing random draws so naming never shifts simulation randomness.
export function adventurerName(roll: number, usedNames: ReadonlySet<string> = new Set()): string {
  return availableName(ADVENTURER_NAMES, Math.floor(roll * ADVENTURER_NAMES.length), usedNames);
}

export function partyName(styleRoll: number, nameRoll: number, usedNames: ReadonlySet<string> = new Set()): string {
  const style = Math.floor(styleRoll * PARTY_NAME_STYLES.length);
  const start = PARTY_NAME_STYLES.slice(0, style).reduce((total, names) => total + names.length, 0)
    + Math.floor(nameRoll * PARTY_NAME_STYLES[style].length);
  return availableName(PARTY_NAMES, start, usedNames);
}

export function localizedAdventurerName(name: string, lang: Language = 'ja'): string {
  if (lang !== 'en') return name;
  const [given, family] = name.split('・');
  const givenIndex = GIVEN_NAMES.indexOf(given as typeof GIVEN_NAMES[number]);
  if (givenIndex < 0) return name;
  const localizedGiven = GIVEN_NAMES_EN[givenIndex];
  if (family === undefined) return localizedGiven;
  const familyIndex = FAMILY_NAMES.indexOf(family as typeof FAMILY_NAMES[number]);
  return familyIndex < 0 ? name : `${localizedGiven} ${FAMILY_NAMES_EN[familyIndex]}`;
}

export function localizedPartyName(name: string, lang: Language = 'ja'): string {
  if (lang !== 'en') return name;
  const numbered = name.match(/^(.*)・第(\d+)隊$/);
  const baseName = (numbered?.[1] ?? name).replace(/\s+\d+$/, '');
  const translated = (() => {
    const prefixIndex = PARTY_PREFIXES.findIndex(prefix => baseName.startsWith(prefix));
    if (prefixIndex >= 0) {
      const emblemIndex = PARTY_EMBLEMS.indexOf(baseName.slice(PARTY_PREFIXES[prefixIndex].length) as typeof PARTY_EMBLEMS[number]);
      if (emblemIndex >= 0) return `${PARTY_PREFIXES_EN[prefixIndex]} ${PARTY_EMBLEMS_EN[emblemIndex]}`;
    }
    for (let placeIndex = 0; placeIndex < PARTY_PLACES.length; placeIndex++) {
      const placePrefix = `${PARTY_PLACES[placeIndex]}の`;
      if (!baseName.startsWith(placePrefix)) continue;
      const companyIndex = PARTY_COMPANIES.indexOf(baseName.slice(placePrefix.length) as typeof PARTY_COMPANIES[number]);
      if (companyIndex >= 0) return `${PARTY_COMPANIES_EN[companyIndex]} of ${PARTY_PLACES_EN[placeIndex]}`;
    }
    const separator = baseName.indexOf('と');
    if (separator > 0) {
      const firstIndex = PARTY_SYMBOLS.indexOf(baseName.slice(0, separator) as typeof PARTY_SYMBOLS[number]);
      const secondIndex = PARTY_SYMBOLS.indexOf(baseName.slice(separator + 1) as typeof PARTY_SYMBOLS[number]);
      if (firstIndex >= 0 && secondIndex >= 0) return `${PARTY_SYMBOLS_EN[firstIndex]} & ${PARTY_SYMBOLS_EN[secondIndex]}`;
    }
    return baseName;
  })();
  return numbered ? `${translated} Company #${numbered[2]}` : translated;
}

const LEGACY_MEMBER_NAMES = new Set(['リオ', 'エルナ', 'ノア', 'ミラ', 'カイ', 'セラ', 'ルカ', 'フィン']);
const LEGACY_PARTY_NAME = /^(?:暁の|銀の|風読みの|青い|名もなき|月下の|旅する|遠い)(?:灯火|梟|羅針盤|剣|渡り鳥|六花|星|足跡) (\d+)$/;

function identityRoll(seed: number, id: number, salt: number): number {
  let value = (seed ^ Math.imul(id, 0x9e3779b1) ^ salt) >>> 0;
  value = Math.imul(value ^ (value >>> 16), 0x21f0aaad);
  value = Math.imul(value ^ (value >>> 15), 0x735a2d97);
  return ((value ^ (value >>> 15)) >>> 0) / 4294967296;
}

export function upgradeLegacyNames(state: GameState): void {
  const usedPartyNames = new Set(state.parties.map(party => party.name));
  const renamedParties = new Map<string, string>();
  for (const party of state.parties) {
    const legacy = LEGACY_PARTY_NAME.exec(party.name);
    if (legacy && party.id === `p${legacy[1]}`) {
      const oldName = party.name;
      party.name = partyName(identityRoll(state.initialSeed, Number(legacy[1]), 1), identityRoll(state.initialSeed, Number(legacy[1]), 2), usedPartyNames);
      usedPartyNames.add(party.name);
      renamedParties.set(oldName, party.name);
    }
    const usedMemberNames = new Set(party.members.map(member => member.name));
    for (const member of party.members) {
      if (!LEGACY_MEMBER_NAMES.has(member.name)) continue;
      member.name = adventurerName(identityRoll(state.initialSeed, member.id, 3), usedMemberNames);
      usedMemberNames.add(member.name);
    }
  }
  for (const base of state.bases) for (const feedback of base.tradeFeedback) {
    feedback.partyName = renamedParties.get(feedback.partyName) ?? feedback.partyName;
  }
  const result = state.recruitment.lastResult;
  if (result) result.partyName = renamedParties.get(result.partyName) ?? result.partyName;
}
