import { BALANCE, GOODS, HQ_UPGRADE_CONFIG } from './config.ts';
import { price, standardSellPrice } from './economy.ts';
import { checkHqUpgradeReady, facilityUpgradeCost, isTaxExempt, taxEstimate, turnsUntilTax } from './selectors.ts';
import type { AccountCategory, FacilityKey, GameState, GoodsKey } from './model.ts';

export interface PriceTrendPoint {
  day: number;
  turn: number;
  buy: number;
  sell: number;
}

export interface GoodsTrend {
  good: GoodsKey;
  name: string;
  count: number;
  revenue: number;
  cost: number;
  profit: number;
  prices: PriceTrendPoint[];
}

export interface FacilityRecord {
  facility: FacilityKey;
  name: string;
  level: number;
  users: number;
  revenue: number;
}

export interface DaySnapshot {
  day: number;
  turn: number;
  revenue: number;
  profit: number;
  visitors: number;
  prices: Record<GoodsKey, { buy: number; sell: number }>;
  baseReputations: Array<{ id: string; name: string; popularity: number }>;
  dungeonReputations: Array<{ id: string; name: string; recognition: number; popularity: number }>;
}

export interface CasualtySummary {
  deaths: number;
  injuries: number;
  wipes: number;
  logs: Array<{ turn: number; day: number; partyName: string; text: string; type: 'death' | 'injury' | 'wipe' }>;
}

export type OpportunityLossCategory = 'stockout' | 'price' | 'capacity' | 'other';

export interface OpportunityLossFeedback {
  turn: number;
  day: number;
  partyName: string;
  item: string;
  reason: string;
  category: OpportunityLossCategory;
}

export interface OpportunityLossSummary {
  total: number;
  stockoutCount: number;
  priceRefusalCount: number;
  capacityCount: number;
  otherCount: number;
  byItem: Record<string, number>;
  feedbacks: OpportunityLossFeedback[];
}

export interface WeeklyKingdomEvent {
  id: string;
  type: string;
  title: string;
  text: string;
  startTurn: number;
  duration: number;
  statusText: string;
}

export interface HqUpgradeCondition {
  key: string;
  label: string;
  current: number | string;
  required: number | string;
  satisfied: boolean;
  progressPercent: number;
}

export interface ShopFacilityStatus {
  baseId: string;
  baseName: string;
  currentLevel: number;
  maxLevel: number;
  nextCost: number;
  canUpgrade: boolean;
}

export interface HqUpgradeStatus {
  currentLevel: number;
  targetLevel: number;
  targetTitle: string;
  cost: number;
  cashHave: number;
  canUpgrade: boolean;
  conditions: HqUpgradeCondition[];
  unlocks: string;
  maxLevelReached: boolean;
  shopFacilities: ShopFacilityStatus[];
}

export interface WeeklyTaxInfo {
  turn: number;
  taxRate: number;
  isExempt: boolean;
  exemptionTurnsRemaining: number;
  periodProfit: number;
  lastTaxAmount: number;
  lastPaidAmount: number;
  taxArrears: number;
  totalPaidTax: number;
  nextTaxDueTurn: number;
  nextTaxEstimate: number;
  trustGainOrLoss: number;
  statusText: string;
}

export interface WeeklyReport {
  week: number;
  startTurn: number;
  endTurn: number;
  startDay: number;
  endDay: number;
  createdAt: number;

  // 1. 総売り上げ
  totalRevenue: number;
  totalExpenses: number;
  netProfit: number;
  revenueByCategory: Record<AccountCategory, number>;
  expensesByCategory: Record<AccountCategory, number>;

  // 2. 仕入れ値・販売値の推移 & 5. 各売り上げアイテム数
  goodsTrends: Record<GoodsKey, GoodsTrend>;

  // 3. 来訪PT数
  totalVisitors: number;
  visitorsByBase: Record<string, { baseName: string; visitors: number }>;

  // 4. 知名度・評判の推移
  dailySnapshots: DaySnapshot[];

  // 6. 店舗・宿屋の実績
  facilities: FacilityRecord[];

  // 7. 冒険者の死亡・負傷・全滅数
  casualties: CasualtySummary;

  // 8. 機会損失数と内訳
  opportunityLoss: OpportunityLossSummary;

  // 9. 王国で発生したイベント
  kingdomEvents: WeeklyKingdomEvent[];

  // 10. 次の商店LVアップの条件
  hqUpgrade: HqUpgradeStatus;

  // 11. 税金の項目
  tax: WeeklyTaxInfo;
}

export interface WeeklyDataBuffer {
  week: number;
  startTurn: number;
  revenueByCategory: Record<AccountCategory, number>;
  expensesByCategory: Record<AccountCategory, number>;
  goodsSales: Record<GoodsKey, { count: number; revenue: number; cost: number }>;
  facilityMetrics: Record<FacilityKey, { users: number; revenue: number }>;
  dailySnapshots: DaySnapshot[];
  casualties: CasualtySummary;
  opportunityLossFeedbacks: OpportunityLossFeedback[];
  visitorsByBase: Record<string, number>;
}

const GOODS_KEYS = Object.keys(GOODS) as GoodsKey[];
const ACCOUNT_CATEGORIES: AccountCategory[] = [
  'goods', 'services', 'maps', 'materials', 'highway', 'upkeep', 'spoilage', 'raids', 'advertising', 'repair', 'other',
];
const FACILITY_NAMES: Record<FacilityKey, string> = {
  shop: '道具屋（店舗）',
  inn: '宿屋',
  warehouse: '倉庫',
  stable: '馬車施設',
  defense: '傭兵',
  tavern: '酒場',
  smith: '鍛冶屋',
  hospital: '治療所（病院）',
};

export function createWeeklyDataBuffer(week: number, startTurn: number): WeeklyDataBuffer {
  return {
    week,
    startTurn,
    revenueByCategory: Object.fromEntries(ACCOUNT_CATEGORIES.map(k => [k, 0])) as Record<AccountCategory, number>,
    expensesByCategory: Object.fromEntries(ACCOUNT_CATEGORIES.map(k => [k, 0])) as Record<AccountCategory, number>,
    goodsSales: Object.fromEntries(GOODS_KEYS.map(k => [k, { count: 0, revenue: 0, cost: 0 }])) as Record<GoodsKey, { count: number; revenue: number; cost: number }>,
    facilityMetrics: Object.fromEntries(Object.keys(FACILITY_NAMES).map(k => [k as FacilityKey, { users: 0, revenue: 0 }])) as Record<FacilityKey, { users: number; revenue: number }>,
    dailySnapshots: [],
    casualties: { deaths: 0, injuries: 0, wipes: 0, logs: [] },
    opportunityLossFeedbacks: [],
    visitorsByBase: {},
  };
}

export function recordWeeklyCasualty(
  s: GameState,
  type: 'death' | 'injury' | 'wipe',
  text: string,
  partyName = '',
): void {
  s.currentWeekBuffer ??= createWeeklyDataBuffer(Math.max(1, Math.ceil(s.turn / 35)), s.turn);
  const buf = s.currentWeekBuffer;
  if (type === 'death') buf.casualties.deaths++;
  else if (type === 'injury') buf.casualties.injuries++;
  else if (type === 'wipe') buf.casualties.wipes++;

  const day = Math.max(1, Math.ceil(s.turn / 5));
  buf.casualties.logs.unshift({
    turn: s.turn,
    day,
    partyName,
    text,
    type,
  });
  if (buf.casualties.logs.length > 50) buf.casualties.logs.length = 50;
}

export function recordWeeklyOpportunityLoss(
  s: GameState,
  partyName: string,
  item: string,
  reason: string,
): void {
  s.currentWeekBuffer ??= createWeeklyDataBuffer(Math.max(1, Math.ceil(s.turn / 35)), s.turn);
  const buf = s.currentWeekBuffer;
  let category: OpportunityLossCategory = 'other';
  if (reason.includes('在庫切れ') || reason.includes('欠品')) category = 'stockout';
  else if (reason.includes('高くて') || reason.includes('買い控え')) category = 'price';
  else if (reason.includes('所持金不足')) category = 'price';
  else if (reason.includes('満床') || reason.includes('満室') || reason.includes('定員')) category = 'capacity';

  const day = Math.max(1, Math.ceil(s.turn / 5));
  buf.opportunityLossFeedbacks.unshift({
    turn: s.turn,
    day,
    partyName,
    item,
    reason,
    category,
  });
  if (buf.opportunityLossFeedbacks.length > 100) buf.opportunityLossFeedbacks.length = 100;
}

export function recordDailySnapshotToBuffer(s: GameState): void {
  s.currentWeekBuffer ??= createWeeklyDataBuffer(Math.max(1, Math.ceil(s.turn / 35)), s.turn);
  const buf = s.currentWeekBuffer;
  const day = Math.max(1, Math.ceil(s.turn / 5));

  // 当日の売上・利益・来訪数（前線拠点合計）
  let dayRevenue = 0;
  let dayProfit = 0;
  let dayVisitors = 0;
  for (const b of s.bases) {
    if (b.abandoned) continue;
    dayRevenue += b.todayRevenue || b.lastRevenue || 0;
    dayProfit += b.todayProfit || b.lastProfit || 0;
    dayVisitors += b.visitors || b.lastVisitors || 0;

    buf.visitorsByBase[b.id] = (buf.visitorsByBase[b.id] || 0) + (b.visitors || b.lastVisitors || 0);

    // 施設メトリクスと商品販売の累積
    if (b.metrics) {
      for (const [key, metric] of Object.entries(b.metrics)) {
        const fk = key as FacilityKey;
        if (!buf.facilityMetrics[fk]) buf.facilityMetrics[fk] = { users: 0, revenue: 0 };
        buf.facilityMetrics[fk].users += metric.users || metric.lastUsers || 0;
        buf.facilityMetrics[fk].revenue += metric.revenue || metric.lastRevenue || 0;
      }
    }
  }

  // 商品価格
  const prices: Record<GoodsKey, { buy: number; sell: number }> = {} as any;
  for (const g of GOODS_KEYS) {
    prices[g] = {
      buy: price(s, g, 'buy'),
      sell: standardSellPrice(s, g),
    };
  }

  // 評判と認知度（他ダンジョン・他商店は除外し、プレイヤーの拠点・自営迷宮のみ集計）
  const playerBases = s.bases.filter(b => !b.abandoned);
  const baseReputations = playerBases.map(b => ({
    id: b.id,
    name: b.name,
    popularity: b.popularity,
  }));

  const playerDungeonIds = new Set(
    s.dungeons.filter(d => d.owned || playerBases.some(b => b.dungeonId === d.id)).map(d => d.id),
  );

  const dungeonReputations = s.dungeons
    .filter(d => playerDungeonIds.has(d.id) && !['rumor', 'closed'].includes(d.phase))
    .map(d => ({
      id: d.id,
      name: d.name,
      recognition: d.recognition,
      popularity: d.popularity,
    }));

  buf.dailySnapshots.push({
    day,
    turn: s.turn,
    revenue: dayRevenue,
    profit: dayProfit,
    visitors: dayVisitors,
    prices,
    baseReputations,
    dungeonReputations,
  });

  // 日次スナップショットは最大7日分（1週間分）保持
  if (buf.dailySnapshots.length > 7) {
    buf.dailySnapshots = buf.dailySnapshots.slice(-7);
  }
}

export function evaluateHqUpgrade(s: GameState): HqUpgradeStatus {
  const currentLevel = s.hq.level;
  const targetLevel = currentLevel + 1;
  const req = HQ_UPGRADE_CONFIG[targetLevel];
  const isMax = targetLevel > 5 || !req;

  const activeBases = s.bases.filter(b => !b.abandoned);
  const maxFloor = Math.max(0, ...s.dungeons.map(d => d.knownFloor));
  const maxMaps = Math.max(0, ...s.dungeons.map(d => d.maps.length));
  const hasCoreLv2 = activeBases.some(b => b.facilities.inn >= 2 || b.facilities.shop >= 2 || b.facilities.warehouse >= 2 || b.facilities.tavern >= 2);
  const maxOutpostFacilitySum = Math.max(0, ...activeBases.map(b => Object.values(b.facilities).reduce((a, c) => a + c, 0)));
  const totalAllFacilitySum = activeBases.reduce((acc, b) => acc + Object.values(b.facilities).reduce((a, c) => a + c, 0), 0);

  const conditions: HqUpgradeCondition[] = [];
  let canUpgrade = false;

  if (isMax) {
    canUpgrade = false;
  } else {
    // 1. 必要資金
    conditions.push({
      key: 'cash',
      label: '本店資金',
      current: `${Math.floor(s.hq.cash).toLocaleString()} G`,
      required: `${req.cost.toLocaleString()} G`,
      satisfied: s.hq.cash >= req.cost,
      progressPercent: Math.min(100, Math.round((s.hq.cash / req.cost) * 100)),
    });

    // 2. 国評価
    if (req.minTrust) {
      conditions.push({
        key: 'trust',
        label: '国評価（信用度）',
        current: Math.floor(s.hq.trust),
        required: req.minTrust,
        satisfied: s.hq.trust >= req.minTrust,
        progressPercent: Math.min(100, Math.round((s.hq.trust / req.minTrust) * 100)),
      });
    }

    // 3. 基本施設LV2
    if (req.minCoreFacilityLevel) {
      conditions.push({
        key: 'coreFacility',
        label: '基本施設いずれかLV2以上',
        current: hasCoreLv2 ? '達成' : '未達',
        required: 'LV2以上',
        satisfied: hasCoreLv2,
        progressPercent: hasCoreLv2 ? 100 : 50,
      });
    }

    // 4. 地図購入
    if (req.minMaps) {
      conditions.push({
        key: 'maps',
        label: '迷宮地図の所持数',
        current: `${maxMaps} 枚`,
        required: `${req.minMaps} 枚以上`,
        satisfied: maxMaps >= req.minMaps,
        progressPercent: Math.min(100, Math.round((maxMaps / req.minMaps) * 100)),
      });
    }

    // 5. 商館の施設合計LV
    if (req.minTotalFacilityLevel) {
      conditions.push({
        key: 'totalFacility',
        label: '商館施設合計LV',
        current: `最大 LV ${maxOutpostFacilitySum}`,
        required: `LV ${req.minTotalFacilityLevel} 以上`,
        satisfied: maxOutpostFacilitySum >= req.minTotalFacilityLevel,
        progressPercent: Math.min(100, Math.round((maxOutpostFacilitySum / req.minTotalFacilityLevel) * 100)),
      });
    }

    // 6. 商館運営数
    if (req.minBases) {
      conditions.push({
        key: 'bases',
        label: '運営商館数',
        current: `${activeBases.length} 箇所`,
        required: `${req.minBases} 箇所以上`,
        satisfied: activeBases.length >= req.minBases,
        progressPercent: Math.min(100, Math.round((activeBases.length / req.minBases) * 100)),
      });
    }

    // 7. 迷宮到達階層
    if (req.minFloor) {
      conditions.push({
        key: 'floor',
        label: '迷宮到達階層',
        current: `最高 ${maxFloor} 階`,
        required: `${req.minFloor} 階以上`,
        satisfied: maxFloor >= req.minFloor,
        progressPercent: Math.min(100, Math.round((maxFloor / req.minFloor) * 100)),
      });
    }

    // 8. 商会全体施設合計LV
    if (req.minTotalAllFacilities) {
      conditions.push({
        key: 'allFacilities',
        label: '全拠点施設合計LV',
        current: `合計 LV ${totalAllFacilitySum}`,
        required: `LV ${req.minTotalAllFacilities} 以上`,
        satisfied: totalAllFacilitySum >= req.minTotalAllFacilities,
        progressPercent: Math.min(100, Math.round((totalAllFacilitySum / req.minTotalAllFacilities) * 100)),
      });
    }

    const readyCheck = checkHqUpgradeReady(s, targetLevel, s.lang || 'ja');
    canUpgrade = readyCheck.ok;
  }

  // 各商館の道具屋（店舗）の状況も取得
  const shopFacilities: ShopFacilityStatus[] = activeBases.map(b => {
    const curLv = b.facilities.shop || 0;
    const maxLv = Math.min(5, currentLevel + 1);
    const nextCost = facilityUpgradeCost(b, 'shop');
    return {
      baseId: b.id,
      baseName: b.name,
      currentLevel: curLv,
      maxLevel: maxLv,
      nextCost,
      canUpgrade: curLv < maxLv && b.cash >= nextCost,
    };
  });

  return {
    currentLevel,
    targetLevel: isMax ? currentLevel : targetLevel,
    targetTitle: isMax ? '最高峰商会（最大LV）' : req?.title || `本店 LV${targetLevel}`,
    cost: req?.cost || 0,
    cashHave: Math.floor(s.hq.cash),
    canUpgrade,
    conditions,
    unlocks: req?.unlocks || 'すべての本店機能が解禁されています',
    maxLevelReached: isMax,
    shopFacilities,
  };
}

export function evaluateWeeklyTax(s: GameState): WeeklyTaxInfo {
  const isExempt = isTaxExempt(s);
  const exemptionLimit = BALANCE.taxExemptionTurns ?? 50;
  const exemptionTurnsRemaining = Math.max(0, exemptionLimit - s.turn);
  const taxRate = BALANCE.taxRate;

  const lastHistory = s.finance.history[0];
  const lastTaxAmount = lastHistory?.tax ?? 0;
  const lastPaidAmount = lastHistory?.paid ?? 0;
  const periodProfit = lastHistory?.profit ?? s.finance.periodProfit;
  const taxArrears = s.finance.taxArrears;
  const totalPaidTax = s.finance.paidTax;
  const nextTaxDueTurn = s.finance.taxDue;
  const nextTaxEstimate = taxEstimate(s);

  let trustGainOrLoss = 0;
  let statusText = '';
  if (isExempt) {
    statusText = `創業特例により免税中（残り${Math.ceil(exemptionTurnsRemaining / 5)}日 / ${exemptionTurnsRemaining}T）`;
  } else if (lastHistory && lastHistory.turn >= s.turn - 35) {
    if (lastHistory.tax === 0) {
      statusText = '今期税額なし（利益なし）';
    } else if (lastHistory.paid >= lastHistory.tax) {
      trustGainOrLoss = Number(Math.min(3.5, Math.sqrt(lastHistory.paid) / 18 + 0.5).toFixed(1));
      statusText = `今期全額納付済（${lastHistory.paid.toLocaleString()} G・国信用 +${trustGainOrLoss}）`;
    } else {
      const unpaid = lastHistory.tax - lastHistory.paid;
      trustGainOrLoss = -Number(Math.min(10, Math.max(2, Math.sqrt(unpaid) / 10 + (lastHistory.paid === 0 ? 2 : 0.5))).toFixed(1));
      statusText = `一部未納あり（納付 ${lastHistory.paid.toLocaleString()} G / 未納 ${unpaid.toLocaleString()} G・国信用 ${trustGainOrLoss}）`;
    }
  } else {
    statusText = `次回納税まで残り${turnsUntilTax(s)}ターン（見込: ${nextTaxEstimate.toLocaleString()} G）`;
  }

  return {
    turn: s.turn,
    taxRate,
    isExempt,
    exemptionTurnsRemaining,
    periodProfit,
    lastTaxAmount,
    lastPaidAmount,
    taxArrears,
    totalPaidTax,
    nextTaxDueTurn,
    nextTaxEstimate,
    trustGainOrLoss,
    statusText,
  };
}

export function generateWeeklyReport(s: GameState): WeeklyReport {
  const week = Math.max(1, Math.floor(s.turn / 35));
  const endTurn = s.turn;
  const startTurn = Math.max(0, endTurn - 35);
  const endDay = Math.max(1, Math.ceil(endTurn / 5));
  const startDay = Math.max(1, endDay - 6);

  s.currentWeekBuffer ??= createWeeklyDataBuffer(week, startTurn);
  const buf = s.currentWeekBuffer;

  // 1. 売上と費用の集計（前線拠点のアカウント情報やバッファから収集）
  let totalRevenue = 0;
  let totalExpenses = 0;
  const revenueByCategory: Record<AccountCategory, number> = { ...buf.revenueByCategory };
  const expensesByCategory: Record<AccountCategory, number> = { ...buf.expensesByCategory };

  for (const b of s.bases) {
    if (b.abandoned) continue;
    // 当日・直近のアカウント情報から加算
    for (const acc of [b.todayAccounts, b.lastAccounts, b.previousAccounts]) {
      if (acc && acc.turn > startTurn && acc.turn <= endTurn) {
        for (const cat of ACCOUNT_CATEGORIES) {
          revenueByCategory[cat] += acc.revenue?.[cat] || 0;
          expensesByCategory[cat] += acc.expenses?.[cat] || 0;
        }
      }
    }
  }

  for (const cat of ACCOUNT_CATEGORIES) {
    totalRevenue += revenueByCategory[cat];
    totalExpenses += expensesByCategory[cat];
  }

  // 財務記録からの補正（もし日次アカウントに含まれないHQ売却や税金等があれば）
  const netProfit = totalRevenue - totalExpenses;

  // 2. 仕入れ値・販売値の推移 & 5. 各売り上げアイテム数
  const goodsTrends: Record<GoodsKey, GoodsTrend> = {} as any;
  for (const g of GOODS_KEYS) {
    const prices: PriceTrendPoint[] = buf.dailySnapshots.map(snap => ({
      day: snap.day,
      turn: snap.turn,
      buy: snap.prices[g]?.buy || price(s, g, 'buy'),
      sell: snap.prices[g]?.sell || standardSellPrice(s, g),
    }));

    // もし日次スナップショットが足りない場合、現在の値で補完
    if (prices.length === 0) {
      prices.push({
        day: endDay,
        turn: endTurn,
        buy: price(s, g, 'buy'),
        sell: standardSellPrice(s, g),
      });
    }

    let count = buf.goodsSales[g]?.count || 0;
    let revenue = buf.goodsSales[g]?.revenue || 0;
    let cost = buf.goodsSales[g]?.cost || 0;

    // 各拠点の todayAccounts / lastAccounts からも商品販売数を合算
    for (const b of s.bases) {
      for (const acc of [b.todayAccounts, b.lastAccounts]) {
        if (acc && acc.turn > startTurn && acc.turn <= endTurn && acc.goods?.[g]) {
          count += acc.goods[g].count || 0;
          revenue += acc.goods[g].revenue || 0;
          cost += acc.goods[g].cost || 0;
        }
      }
    }

    goodsTrends[g] = {
      good: g,
      name: GOODS[g].name,
      count,
      revenue,
      cost,
      profit: revenue - cost,
      prices,
    };
  }

  // 3. 来訪PT数
  const visitorsByBase: Record<string, { baseName: string; visitors: number }> = {};
  let totalVisitors = 0;
  for (const b of s.bases) {
    if (b.abandoned) continue;
    const baseVis = (buf.visitorsByBase[b.id] || 0) + (b.visitors || 0) + (b.lastVisitors || 0);
    visitorsByBase[b.id] = {
      baseName: b.name,
      visitors: baseVis,
    };
    totalVisitors += baseVis;
  }

  // 6. 店舗・宿屋の実績
  const facilities: FacilityRecord[] = [];
  for (const [key, name] of Object.entries(FACILITY_NAMES)) {
    const fk = key as FacilityKey;
    let users = buf.facilityMetrics[fk]?.users || 0;
    let rev = buf.facilityMetrics[fk]?.revenue || 0;
    let maxLv = 0;
    for (const b of s.bases) {
      if (b.abandoned) continue;
      maxLv = Math.max(maxLv, b.facilities[fk] || 0);
      if (b.metrics?.[fk]) {
        users += (b.metrics[fk].users || 0) + (b.metrics[fk].lastUsers || 0);
        rev += (b.metrics[fk].revenue || 0) + (b.metrics[fk].lastRevenue || 0);
      }
    }
    facilities.push({
      facility: fk,
      name,
      level: maxLv,
      users,
      revenue: rev,
    });
  }

  // 7. 冒険者の死亡・負傷・全滅数
  const casualties: CasualtySummary = {
    deaths: buf.casualties.deaths,
    injuries: buf.casualties.injuries,
    wipes: buf.casualties.wipes,
    logs: [...buf.casualties.logs],
  };

  // 8. 機会損失数と内訳
  const byItem: Record<string, number> = {};
  let stockoutCount = 0;
  let priceRefusalCount = 0;
  let capacityCount = 0;
  let otherCount = 0;

  // 各拠点のtradeFeedbackからも最新分をマージ
  const mergedFeedbacks = [...buf.opportunityLossFeedbacks];
  for (const b of s.bases) {
    for (const fb of b.tradeFeedback || []) {
      if (fb.turn > startTurn && fb.turn <= endTurn) {
        if (!mergedFeedbacks.some(f => f.turn === fb.turn && f.partyName === fb.partyName && f.item === fb.item)) {
          let category: OpportunityLossCategory = 'other';
          if (fb.reason.includes('在庫切れ') || fb.reason.includes('欠品')) category = 'stockout';
          else if (fb.reason.includes('高くて') || fb.reason.includes('買い控え') || fb.reason.includes('所持金不足')) category = 'price';
          else if (fb.reason.includes('満床') || fb.reason.includes('満室') || fb.reason.includes('定員')) category = 'capacity';

          mergedFeedbacks.push({
            turn: fb.turn,
            day: Math.max(1, Math.ceil(fb.turn / 5)),
            partyName: fb.partyName,
            item: fb.item,
            reason: fb.reason,
            category,
          });
        }
      }
    }
  }

  for (const fb of mergedFeedbacks) {
    byItem[fb.item] = (byItem[fb.item] || 0) + 1;
    if (fb.category === 'stockout') stockoutCount++;
    else if (fb.category === 'price') priceRefusalCount++;
    else if (fb.category === 'capacity') capacityCount++;
    else otherCount++;
  }

  const opportunityLoss: OpportunityLossSummary = {
    total: mergedFeedbacks.length,
    stockoutCount,
    priceRefusalCount,
    capacityCount,
    otherCount,
    byItem,
    feedbacks: mergedFeedbacks.slice(0, 30),
  };

  // 9. 王国で発生したイベント
  const kingdomEvents: WeeklyKingdomEvent[] = s.events
    .filter(e => (e.start + e.duration >= startTurn) && (e.start <= endTurn))
    .map(e => ({
      id: e.id,
      type: e.type,
      title: e.title,
      text: e.text,
      startTurn: e.start,
      duration: e.duration,
      statusText: e.state === 'active' ? '進行中' : '終了済み',
    }));

  // 10. 次の商店LVアップの条件
  const hqUpgrade = evaluateHqUpgrade(s);

  // 11. 税金の項目
  const tax = evaluateWeeklyTax(s);

  const report: WeeklyReport = {
    week,
    startTurn,
    endTurn,
    startDay,
    endDay,
    createdAt: Math.floor(Date.now() / 1000),
    totalRevenue,
    totalExpenses,
    netProfit,
    revenueByCategory,
    expensesByCategory,
    goodsTrends,
    totalVisitors,
    visitorsByBase,
    dailySnapshots: buf.dailySnapshots,
    facilities,
    casualties,
    opportunityLoss,
    kingdomEvents,
    hqUpgrade,
    tax,
  };

  return report;
}
