import type { Dungeon, GameState, Party } from './model.ts';

export const DEFAULT_DUNGEON_IMPRESSION = 50;

const clampImpression = (value: number): number => Math.max(0, Math.min(100, value));

export function awarePartyCount(s: GameState, dungeonId: string): number {
  return s.parties.reduce((count, party) => count + (party.knownDungeons?.includes(dungeonId) ? 1 : 0), 0);
}

export function partyDungeonImpression(party: Party, dungeonId: string): number {
  return party.dungeonImpressions?.[dungeonId] ?? DEFAULT_DUNGEON_IMPRESSION;
}

export function communityDungeonImpression(s: GameState, dungeon: Dungeon): number {
  return awarePartyCount(s, dungeon.id) > 0 ? dungeon.popularity : DEFAULT_DUNGEON_IMPRESSION;
}

export function refreshDungeonMetrics(s: GameState, dungeon: Dungeon): void {
  const aware = s.parties.filter(party => party.knownDungeons?.includes(dungeon.id));
  dungeon.recognition = s.parties.length
    ? Math.round((aware.length / s.parties.length) * 1000) / 10
    : 0;
  if (typeof dungeon.popularity !== 'number' || !Number.isFinite(dungeon.popularity)) {
    dungeon.popularity = aware.length
      ? Math.round(aware.reduce((sum, party) => sum + partyDungeonImpression(party, dungeon.id), 0) / aware.length)
      : 0;
  }
  dungeon.popularity = clampImpression(dungeon.popularity);
}

export function refreshAllDungeonMetrics(s: GameState): void {
  for (const dungeon of s.dungeons) refreshDungeonMetrics(s, dungeon);
}

export function makePartyAware(s: GameState, party: Party, dungeon: Dungeon, impression = communityDungeonImpression(s, dungeon)): boolean {
  party.knownDungeons ||= [];
  party.dungeonImpressions ||= {};
  const isNew = !party.knownDungeons.includes(dungeon.id);
  if (isNew) party.knownDungeons.push(dungeon.id);
  if (typeof party.dungeonImpressions[dungeon.id] !== 'number') {
    // Give new awareness the exact current mean so adding a party alone cannot skew popularity.
    party.dungeonImpressions[dungeon.id] = clampImpression(impression);
  }
  const awareCount = awarePartyCount(s, dungeon.id);
  if (awareCount === 1) {
    dungeon.popularity = clampImpression(party.dungeonImpressions[dungeon.id]);
  }
  refreshDungeonMetrics(s, dungeon);
  return isNew;
}

export function changePartyDungeonImpression(s: GameState, party: Party, dungeon: Dungeon, delta: number): void {
  party.knownDungeons ||= [];
  party.dungeonImpressions ||= {};
  if (!party.knownDungeons.includes(dungeon.id)) makePartyAware(s, party, dungeon);
  party.dungeonImpressions[dungeon.id] = clampImpression(partyDungeonImpression(party, dungeon.id) + delta);
  if (delta !== 0) {
    dungeon.popularity = clampImpression(dungeon.popularity + (delta > 0 ? 1 : -1));
  }
  refreshDungeonMetrics(s, dungeon);
}

function stablePartyOrder(dungeonId: string, partyId: string): number {
  let hash = 2166136261;
  for (const char of `${dungeonId}:${partyId}`) {
    hash ^= char.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

export function seedDungeonAwarenessFromMetrics(s: GameState, dungeon: Dungeon): void {
  const legacyRecognition = Math.max(0, Math.min(100, Number(dungeon.recognition) || 0));
  const legacyImpression = clampImpression(Number(dungeon.popularity) || 0);
  for (const party of s.parties) {
    party.knownDungeons ||= [];
    party.dungeonImpressions ||= {};
    if (party.currentDungeonId === dungeon.id || party.lastDungeonId === dungeon.id) {
      if (!party.knownDungeons.includes(dungeon.id)) party.knownDungeons.push(dungeon.id);
    }
    if (party.knownDungeons.includes(dungeon.id) && typeof party.dungeonImpressions[dungeon.id] !== 'number') {
      party.dungeonImpressions[dungeon.id] = legacyImpression;
    }
  }

  if (!['rumor', 'surveying'].includes(dungeon.phase)) {
    const targetCount = Math.max(
      awarePartyCount(s, dungeon.id),
      Math.round(s.parties.length * legacyRecognition / 100),
    );
    const candidates = s.parties
      .filter(party => !party.knownDungeons.includes(dungeon.id))
      .sort((a, b) => stablePartyOrder(dungeon.id, a.id) - stablePartyOrder(dungeon.id, b.id));
    for (const party of candidates.slice(0, Math.max(0, targetCount - awarePartyCount(s, dungeon.id)))) {
      party.knownDungeons.push(dungeon.id);
      party.dungeonImpressions[dungeon.id] = legacyImpression;
    }
  }
  refreshDungeonMetrics(s, dungeon);
}

export function seedAllDungeonAwarenessFromMetrics(s: GameState): void {
  for (const dungeon of s.dungeons) seedDungeonAwarenessFromMetrics(s, dungeon);
  refreshAllDungeonMetrics(s);
}

export function setDungeonAwarenessProfile(s: GameState, dungeon: Dungeon, recognitionPercent: number, impression: number): void {
  for (const party of s.parties) {
    party.knownDungeons = party.knownDungeons.filter(id => id !== dungeon.id);
    party.dungeonImpressions ||= {};
    delete party.dungeonImpressions[dungeon.id];
  }
  const targetCount = Math.round(s.parties.length * Math.max(0, Math.min(100, recognitionPercent)) / 100);
  const candidates = [...s.parties].sort((a, b) => stablePartyOrder(dungeon.id, a.id) - stablePartyOrder(dungeon.id, b.id));
  for (const party of candidates.slice(0, targetCount)) {
    party.knownDungeons.push(dungeon.id);
    party.dungeonImpressions[dungeon.id] = clampImpression(impression);
  }
  dungeon.popularity = clampImpression(impression);
  refreshDungeonMetrics(s, dungeon);
}

export function setAwarePartyImpressions(s: GameState, dungeon: Dungeon, impression: number): void {
  const value = clampImpression(impression);
  for (const party of s.parties) {
    if (party.knownDungeons.includes(dungeon.id)) party.dungeonImpressions[dungeon.id] = value;
  }
  dungeon.popularity = value;
  refreshDungeonMetrics(s, dungeon);
}
