export const MONSTERS: Monster[] = SEEDS.map((seed, index) => {
  const localIndex = index % 20;
  const difficulty = Math.floor(index / 20) + 1;
  const level = (difficulty - 1) * 8 + 1 + Math.floor(localIndex * 8 / 20);
  const grade: MonsterGrade = localIndex === 19 ? 'boss' : localIndex % 7 === 5 ? 'elite' : 'normal';
  const rarity = localIndex === 19 ? 'epic' : localIndex % 7 === 5 ? 'rare' : localIndex % 4 === 2 ? 'uncommon' : 'common';
  const profile = ROLE_PROFILES[seed.role];
  const multiplier = GRADE_MULTIPLIERS[grade];
  const id = `monster-${String(index + 1).padStart(3, '0')}`;
  const drop: MonsterDrop = {
    id: `drop-${String(index + 1).padStart(3, '0')}`,
    name: seed.drop,
    rarity,
    chance: RARITY_CHANCE[rarity] + (rarity === 'common' ? (localIndex % 3) * 0.04 : 0),
    minimumQuantity: 1,
    maximumQuantity: grade === 'boss' ? 1 : difficulty < 3 ? 2 : 1,
    value: Math.round((4 + difficulty * 4 + level * 1.7) * RARITY_PRICE[rarity]),
    description: `${seed.family}の特徴を宿す固有素材。`,
  };
  const rareDrop: MonsterDrop | undefined = grade === 'normal' ? undefined : {
    id: `drop-${String(index + 1).padStart(3, '0')}-rare`,
    name: `${seed.name}の希少素材`,
    rarity: grade === 'boss' ? 'epic' : 'rare',
    isRare: true,
    chance: grade === 'boss' ? 0.12 : 0.08,
    minimumQuantity: 1,
    maximumQuantity: 1,
    value: Math.round(drop.value * 3),
    description: `${seed.family}の強個体から稀に採れる希少な固有素材。`,
  };
  return {
    id,
    name: seed.name,
    family: seed.family,
    role: seed.role,
    difficulty,
    level,
    grade,
    poisonChance: seed.poisonChance,
    stats: {
      hp: Math.round((28 + level * 16) * profile.hp * multiplier.hp),
      mp: Math.round((6 + level * 5) * profile.mp * (grade === 'boss' ? 1.8 : grade === 'elite' ? 1.25 : 1)),
      attack: Math.round((6 + level * 3.2) * profile.attack * multiplier.attack),
      defense: Math.round((3 + level * 2.2) * profile.defense * multiplier.defense),
      magicAttack: Math.round((4 + level * 2.8) * profile.magicAttack * multiplier.magic),
      magicDefense: Math.round((3 + level * 2.0) * profile.magicDefense * multiplier.magic),
      speed: Math.round((5 + level * 1.8) * profile.speed * multiplier.speed),
    },
    experience: Math.round((6 + level * level * 0.65) * profile.experience * multiplier.experience),
    gold: Math.round((4 + level * 2.6) * profile.gold * multiplier.gold),
    drops: rareDrop ? [drop, rareDrop] : [drop],
  };
});

