const MONSTER_DROPS_BY_NAME = new Map<string, MonsterDrop>();
for (const monster of MONSTERS) {
  for (const drop of monster.drops) MONSTER_DROPS_BY_NAME.set(drop.name, drop);
}
for (const monster of LUCKY_MONSTERS) {
  if (monster.drop) MONSTER_DROPS_BY_NAME.set(monster.drop.name, monster.drop);
}

export function getMonsterDrop(name: string): MonsterDrop | undefined {
  return MONSTER_DROPS_BY_NAME.get(name);
}

export function getMonstersForDifficulty(difficulty: number): Monster[] {
  const level = Math.max(1, Math.min(5, Math.round(difficulty) || 1));
  return MONSTERS.filter(monster => monster.difficulty === level);
}

export function monsterRoleLabel(role: MonsterRole, lang: Language = 'ja'): string {
  if (lang === 'en') {
    return {
      balanced: 'Balanced',
      brute: 'Heavy Attacker',
      swift: 'Fast Attacker',
      caster: 'Magic Attacker',
      guardian: 'Defensive',
      mystic: 'Magic & Resilient',
      predator: 'Charger',
      support: 'Support',
    }[role];
  }
  return {
    balanced: '標準型',
    brute: '重攻撃型',
    swift: '高速型',
    caster: '魔法攻撃型',
    guardian: '防御型',
    mystic: '魔法・耐性型',
    predator: '突撃型',
    support: '支援型',
  }[role];
}

export function monsterGradeLabel(grade: MonsterGrade, lang: Language = 'ja'): string {
  if (lang === 'en') {
    return { normal: 'Normal', elite: 'Elite', boss: 'Boss' }[grade];
  }
  return { normal: '通常', elite: '強敵', boss: '主', }[grade];
}

export function dropRarityLabel(rarity: DropRarity, lang: Language = 'ja'): string {
  if (lang === 'en') {
    return { common: 'Normal', uncommon: 'Fine', rare: 'Rare', epic: 'Legendary' }[rarity];
  }
  return { common: '通常', uncommon: '上質', rare: '希少', epic: '伝説' }[rarity];
}
