import type { GameViewId } from '../game/model.ts';

// Generated artwork is local to the project; Vite fingerprints each asset for caching.
export const iconUrls = {
  'world': new URL('../assets/icons/world.webp', import.meta.url).href,
  'region': new URL('../assets/icons/region.webp', import.meta.url).href,
  'base': new URL('../assets/icons/base.webp', import.meta.url).href,
  'dungeon': new URL('../assets/icons/dungeon.webp', import.meta.url).href,
  'maps': new URL('../assets/icons/maps.webp', import.meta.url).href,
  'hq': new URL('../assets/icons/hq.webp', import.meta.url).href,
  'logistics': new URL('../assets/icons/logistics.webp', import.meta.url).href,
  'tax': new URL('../assets/icons/tax.webp', import.meta.url).href,
  'intel': new URL('../assets/icons/intel.webp', import.meta.url).href,
  'events': new URL('../assets/icons/events.webp', import.meta.url).href,
  'parties': new URL('../assets/icons/parties.webp', import.meta.url).href,
  'adventurer-watch': new URL('../assets/icons/adventurer-watch.webp', import.meta.url).href,
  'ogre-battle': new URL('../assets/icons/events.webp', import.meta.url).href,
  'save': new URL('../assets/icons/save.webp', import.meta.url).href,
  'settings': new URL('../assets/icons/settings.webp', import.meta.url).href,
  'debug': new URL('../assets/icons/debug.webp', import.meta.url).href,
  'menu': new URL('../assets/icons/menu.webp', import.meta.url).href,
  'close': new URL('../assets/icons/close.webp', import.meta.url).href,
  'coin': new URL('../assets/icons/coin.webp', import.meta.url).href,
  'wagon-modified': new URL('../assets/icons/wagon-modified.webp', import.meta.url).href,
  'brand': new URL('../assets/icons/brand.webp', import.meta.url).href,
  'wagon': new URL('../assets/icons/wagon.webp', import.meta.url).href,
} satisfies Record<GameViewId | 'save' | 'settings' | 'debug' | 'menu' | 'close' | 'coin' | 'wagon' | 'wagon-modified' | 'brand', string>;

export type GameIconName = keyof typeof iconUrls;

// Icons are decorative. The surrounding button or marker owns its accessible label.
export function gameIcon(name: GameIconName, className = ''): string {
  return `<img class="game-icon${className ? ` ${className}` : ''}" src="${iconUrls[name]}" width="128" height="128" alt="" aria-hidden="true" draggable="false" decoding="async">`;
}

