function debtDeadlineMeter(s: GameState, lang: Language): string {
  const remaining = Math.max(0, s.hq.debtDue - s.turn);
  const label = s.hq.debtOverdue
    ? (lang === 'en' ? 'Loan overdue' : '借入金の返済期限超過')
    : (lang === 'en' ? `Repayment due in ${remaining} turns` : `返済期限まで残り${remaining}ターン`);
  return countdownMeter(remaining, Math.max(BALANCE.debtDue, remaining), label, s.hq.debtOverdue ? 'overdue' : '');
}

function cashOverview(s: GameState, lang: Language = 'ja'): string {
  const isEn = lang === 'en';
  const bases = s.bases.reduce((sum, b) => sum + b.cash, 0);
  const transit = s.wagons.reduce((sum, wagon) => sum + wagon.cargo.cash, 0);
  const title = isEn ? 'Trading House Cash Overview' : '商会全体の資金の所在';
  const desc = isEn
    ? 'Moving funds does not increase or decrease total trading house cash. Borrowing, repayments, facility investments, and operating profits are tracked separately. Unsold materials and warehouse stock are not included in total cash.'
    : '資金の移動では商会全体の現金は増減しません。借入・返済・設備投資と営業利益は別に確認してください。未換金の素材と在庫は現金合計に含みません。';
  return disclosure('hq-cash', title, `<div class="stats-grid compact">${stat(isEn ? 'Headquarters' : '本店', money(s.hq.cash))}${stat(isEn ? 'Outposts Total' : '商館の合計', money(bases))}${stat(isEn ? 'In Transit' : '輸送中の現金', money(transit))}${stat(isEn ? 'Total Cash' : '現金合計', money(s.hq.cash + bases + transit))}</div><p class="subtle">${desc}</p>`, isEn ? `Total Cash ${money(s.hq.cash + bases + transit)}` : `現金合計 ${money(s.hq.cash + bases + transit)}`);
}

