export function logisticsView(s: GameState, ui: UIState): string {
  const lang: Language = ui?.lang || s.lang || 'ja';
  const isEn = lang === 'en';
  const b = s.bases.find(b => b.id === ui.base && !b.abandoned) || s.bases.find(b => !b.abandoned);
  const activeBases = s.bases.filter(x => !x.abandoned);
  const targetOptions = activeBases.map(base => {
    const dungeon = s.dungeons.find(d => d.id === base.dungeonId);
    return `<option value="${esc(base.id)}" ${base.id === b?.id ? 'selected' : ''}>${esc(dungeon ? localizedDungeonName(dungeon.name, lang) : localizedBaseName(base.name, lang))}</option>`;
  }).join('');
  const targetSelect = b
    ? field(isEn ? 'Destination dungeon' : '配備先ダンジョン', `<select id="logistics-dungeon-select" aria-label="${isEn ? 'Destination dungeon' : '配備先ダンジョン'}">${targetOptions}</select>`)
    : '';
  const expressWagonUsedToday = s.lastExpressWagonDay === Math.floor(s.turn / 5);
  const expressWagonLabel = isEn
    ? expressWagonUsedToday ? 'Express Wagon (used today)' : 'Express Wagon (100 G · 1/day)'
    : expressWagonUsedToday ? '臨時便（本日利用済み）' : '臨時便（100G・1日1回）';
  return `<div class="view-heading"><div><div class="eyebrow">AUTOMATED LOGISTICS</div><h1>${isEn ? 'Wagons & Logistics' : '馬車と物流'}</h1></div>${b ? `<div class="view-heading-actions">${targetSelect}${btn(expressWagonLabel, 'game-action', { kind: 'charterWagon', id: b.id }, 'primary', expressWagonUsedToday || s.hq.cash < BALANCE.expressWagonFee)}${investButton(isEn ? 'Deploy Wagon' : '馬車を増配', 'wagon', b.id, '', 'primary')}</div>` : ''}</div><div class="stats-grid">${stat(isEn ? 'Active Wagons' : '稼働馬車', `${s.wagons.filter(w => w.status !== 'idle').length} <small>/ ${s.wagons.length} ${isEn ? 'wagons' : '台'}</small>`)}${stat(isEn ? 'Total Trips' : '累計往復', `${s.wagons.reduce((n, w) => n + w.trips, 0)} <small>${isEn ? 'trips' : '便'}</small>`)}${stat(isEn ? 'Cash in Transit' : '輸送中の現金', money(s.wagons.reduce((n, w) => n + w.cargo.cash, 0)), isEn ? 'Loaded on wagons' : '馬車に積載中')}${stat(isEn ? 'Cargo Lost to Raids' : '被害による積荷損失', `${s.wagons.reduce((n, w) => n + w.lost, 0)} <small>${isEn ? 'items' : '個'}</small>`)}</div>
    <section class="panel"><div class="panel-heading"><h2>${isEn ? 'Fleet Status' : '運行状況'}</h2></div><div class="wagon-list">${s.wagons.map(w => {
      const base = s.bases.find(b => b.id === w.baseId), load = cargoLoad(w), currentCell = wagonRegionCell(s, w), routeDungeon = s.dungeons.find(d => d.id === base?.dungeonId), routeArea = s.areas.find(a => a.id === routeDungeon?.areaId), coordinate = currentCell === null ? '' : `${String.fromCharCode(65 + Math.floor(currentCell / 4))}${currentCell % 4 + 1}`;
      const cargo = (Object.entries(GOODS) as Array<[GoodsKey, typeof GOODS[GoodsKey]]>).filter(([k]) => w.cargo[k]).map(([k, g]) => `${isEn ? goodName(k, 'en') : g.name} ${w.cargo[k]}`);
      if (w.cargo.cash) cargo.push(isEn ? `Cash ${num(w.cargo.cash)} G` : `現金 ${num(w.cargo.cash)} G`);
      if (w.cargo.materials) {
        const bd = w.cargo.materialBreakdown;
        const bdParts = bd ? Object.entries(bd).filter(([, c]) => c > 0).map(([n, c]) => `${n}×${c}(${isEn ? 'unit ' : '単価 '}${materialSellPrice(n, s.prices.material)} G)`).join(', ') : '';
        cargo.push(bdParts ? `${isEn ? 'Materials' : '素材'} ${w.cargo.materials} (${bdParts})` : `${isEn ? 'Materials' : '素材'} ${w.cargo.materials}`);
      }
      if (w.cargo.passengers) cargo.push(isEn ? `Passengers: ${w.cargo.passengers}` : `旅客 ${w.cargo.passengers}人`);
      if (w.cargo.bodies.length) cargo.push(isEn ? `Remains: ${w.cargo.bodies.length}` : `遺体 ${w.cargo.bodies.length}`);
      const cargoSummaryText = cargo.join(' / ') || (isEn ? 'No cargo' : '積荷なし');
      const wagonName = wagonDisplayName(s, w, lang);
      const cargoTooltip = isEn ? `${wagonName}: Cargo (${load}/${w.capacity}) - ${cargo.join(', ') || 'No cargo'}` : `${wagonName}: 積み荷 (${load}/${w.capacity}) - ${cargo.join('、') || '積荷なし'}`;
      const statusBadgeLabel = w.location === 'kingdom' && w.status === 'loading' && w.eta > 1
        ? (isEn ? 'Staging' : '時間差待機')
        : ({
            traveling: isEn ? 'In Transit' : '運行中',
            loading: isEn ? 'Loading' : '積み込み',
            unloading: isEn ? 'Unloading' : '積み下ろし',
            delayed: isEn ? 'Delayed / Ambushed' : '被害・遅延',
            idle: isEn ? 'HQ Idle' : '王国待機'
          })[w.status];
      const routeStatusText = w.status === 'idle'
        ? (isEn ? 'Awaiting assignment' : '配備待ち')
        : (isEn ? `To ${w.destination === 'base' ? 'Outpost' : 'Kingdom'} · in ${w.eta} turns ${w.location === 'road' ? 'arrival' : (w.eta > 1 ? 'departure (staggered)' : 'departure')}` : `${w.destination === 'base' ? '商館' : '王国'}へ · ${w.eta}ターン後 ${w.location === 'road' ? '到着' : (w.eta > 1 ? '出発（時間差運行）' : '出発')}`);
      return `<article class="wagon-card" title="${esc(cargoTooltip)}" data-tooltip="${esc(cargoTooltip)}"><div class="wagon-id"><span class="wagon-emblem" title="${esc(cargoTooltip)}" data-tooltip="${esc(cargoTooltip)}">⇄</span><div><h3>${esc(wagonName)}</h3>${w.capacity > BALANCE.wagonCapacity ? badge(isEn ? 'Modified' : '改造済み', 'gold') : ''}${w.chartered ? badge(isEn ? 'Protected Express' : '臨時便・襲撃なし', 'gold') : ''}${badge(statusBadgeLabel, w.status === 'delayed' ? 'red' : w.status === 'idle' ? '' : 'green')}</div></div><div class="wagon-route"><div><strong>${isEn ? 'Kingdom HQ' : '王国本店'}</strong><span class="route-line ${w.destination === 'kingdom' ? 'reverse' : ''}"><i style="left:${w.location === 'kingdom' ? 0 : w.location === 'base' ? 100 : w.destination === 'base' ? (1 - w.eta / w.totalEta) * 100 : w.eta / w.totalEta * 100}%">◆</i></span><strong>${esc(base ? localizedBaseName(base.name, lang) : "—")}</strong></div><p>${routeStatusText}${coordinate ? (isEn ? ` · Location: ${localizedDirectionName(routeArea?.direction ?? '', lang)} ${coordinate}` : ` · 現在地 ${localizedDirectionName(routeArea?.direction ?? '', lang)} ${coordinate}`) : ''}</p></div><div class="wagon-load" title="${esc(cargoTooltip)}" data-tooltip="${esc(cargoTooltip)}"><span>${isEn ? `Cargo ${load} / ${w.capacity}` : `積載 ${load} / ${w.capacity}`}</span>${bar(load, w.capacity)}<small>${cargoSummaryText}</small></div><div>${w.status === 'idle' && b ? btn(isEn ? 'Assign to Selected Outpost' : '選択中の拠点へ配備', 'assign-wagon', { wagon: w.id, id: b.id }, 'text-btn') : ''}</div></article>`;
    }).join('')}</div></section>
    ${b ? `<div class="two-column">${disclosure(`supply-${b.id}`, isEn ? 'Automatic Supply Policy' : '自動補給方針', `${activeBases.length > 1 ? `<div class="tab-row">${activeBases.map(x => nav(esc(localizedBaseName(x.name, lang)), 'logistics', x.id, `chip ${x.id === b.id ? 'active' : ''}`)).join('')}</div>` : ''}<form id="supply-form" data-id="${b.id}">${field(isEn ? 'Target Cash to Retain at Outpost (G)' : '拠点に残す現金の目標（G）', `<input name="cash" type="number" min="0" max="50000" value="${b.cashTarget}" required>`)}${field(isEn ? 'Inventory Restock Target' : '在庫の補給目標', `<select name="target">${[.25, .5, .75, 1].map(n => `<option value="${n}" ${b.stockTarget === n ? 'selected' : ''}>${isEn ? `${n * 100}% of capacity` : `容量の${n * 100}%`}</option>`).join('')}</select>`)}${field(isEn ? 'Loading Priority' : '積載優先度', `<select name="priority">${[['balanced', isEn ? 'Balanced' : '標準'], ['food', isEn ? 'Prioritize Food' : '食材を優先'], ['potion', isEn ? 'Prioritize Potions' : 'ポーションを優先']].map(([k, n]) => `<option value="${k}" ${b.priority === k ? 'selected' : ''}>${n}</option>`).join('')}</select>`)}<button class="btn primary" type="submit">${isEn ? 'Save Supply Policy' : '補給方針を保存'}</button></form>`)}${disclosure(`transport-${b.id}`, isEn ? 'Expand Transport Capacity' : '輸送力を増やす', `<dl class="facts"><div><dt>${isEn ? 'Paved Road Tiles' : '舗装した道路区画'}</dt><dd>${s.roads.find(r => r.id === b.roadConnection)?.cells.length ?? 0} ${isEn ? 'tiles' : '区画'}</dd></div><div><dt>${isEn ? 'One-Way Travel Time' : '片道の移動'}</dt><dd>${wagonTravelTime(s, b)} ${isEn ? 'turns' : 'ターン'}</dd></div><div><dt>${isEn ? 'Round-Trip Estimate' : '往復の目安'}</dt><dd>${wagonTravelTime(s, b) * 2 + (b.facilities.stable >= 3 ? 2 : 3)} ${isEn ? 'turns' : 'ターン'}</dd></div>${s.wagons.filter(w => w.baseId === b.id && w.status !== 'idle').length >= 2 ? `<div><dt>${isEn ? 'Departure Interval' : '定期運行間隔'}</dt><dd>${isEn ? `Departs approx every ${wagonStaggerInterval(s, b)} turns` : `約 ${wagonStaggerInterval(s, b)} ターンごとに出発`}</dd></div>` : ''}${s.wagons.filter(w => w.baseId === b.id).map(w => `<div><dt>${esc(wagonDisplayName(s, w, lang))}</dt><dd>${investButton(isEn ? 'Upgrade to Large Wagon' : '大型馬車へ改装', 'wagonCapacity', w.id, '', 'text-btn')}</dd></div>`).join('')}</dl><div class="actions">${nav(isEn ? 'Pave Roads on Region Map →' : '地域マップで道を強化 →', 'region', s.dungeons.find(d => d.id === b.dungeonId)?.areaId)}${investButton(isEn ? 'Upgrade Stables' : '馬車施設を増強', 'facility', b.id, 'stable')}</div>`)}</div>` : ''}`;
}

export function taxView(s: GameState, ui?: UIState): string {
  const lang: Language = ui?.lang || s.lang || 'ja';
  const isEn = lang === 'en';
  const next = nextTrust(s);
  const exempt = isTaxExempt(s);
  const currentDay = Math.floor(s.turn / 5);
  const donatedToOrphanageToday = s.hq.lastOrphanageDonationDay === currentDay;
  const canAffordOrphanageDonation = s.hq.cash >= 1000;
  const orphanageDonationLabel = donatedToOrphanageToday
    ? (isEn ? 'Donation completed today' : '本日寄付済み')
    : !canAffordOrphanageDonation
      ? (isEn ? 'Not enough HQ cash' : '本店現金不足')
      : (isEn ? 'Donate 1,000 G' : '1,000 Gを寄付する');
  const orphanageDonationPanel = `<div class="orphanage-donation" style="margin-top:16px;padding:14px;border-radius:8px;background:var(--surface-2);"><h3 style="margin:0 0 6px;">${isEn ? 'Orphanage donation' : '孤児院への寄付'}</h3><p class="subtle" style="margin:0 0 10px;">${isEn ? 'Donate 1,000 G to raise royal trust by 2. Once per day.' : '1,000 Gを寄付すると国評価が2上昇します。寄付は1日1回までです。'}</p>${donatedToOrphanageToday ? `<p class="subtle" style="margin:0 0 10px;">${isEn ? 'You can donate again tomorrow.' : '本日の寄付は完了しています。明日また寄付できます。'}</p>` : ''}<div class="actions">${btn(orphanageDonationLabel, 'game-action', { kind: 'donateOrphanage' }, 'primary', donatedToOrphanageToday || !canAffordOrphanageDonation)}</div></div>`;
  const debtSection = disclosure('tax-debt', isEn ? 'Royal Loan (Repay / Borrow)' : '借入金の返済・追加借入（王室ローン）', `<dl class="facts"><div><dt>${isEn ? 'Debt Balance' : '借金残高'}</dt><dd>${money(s.hq.debt)}</dd></div><div><dt>${isEn ? 'Repayment Due' : '返済期日'}</dt><dd>${s.hq.debt ? countdownMeter(Math.max(0, s.hq.debtDue - s.turn), Math.max(BALANCE.debtDue, s.hq.debtDue - s.turn), s.hq.debtOverdue ? (isEn ? 'Loan overdue' : '借入金の返済期限を超過') : (isEn ? `Repayment due in ${Math.max(0, s.hq.debtDue - s.turn)} turns` : `返済期限まで残り${Math.max(0, s.hq.debtDue - s.turn)}ターン`), s.hq.debtOverdue ? 'overdue' : '') : (isEn ? 'Fully repaid' : '完済済み')}</dd></div><div><dt>${isEn ? 'Additional Borrowing Available' : '追加借入可能枠'}</dt><dd>${money(canBorrowAmount(s))} <small>（${isEn ? 'Limit ' : '上限 '}${money(debtCapacity(s))}）</small></dd></div></dl><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">${s.hq.debt ? btn(isEn ? 'Repay Loan' : '借入金を返済する', 'open-repay', {}, 'primary') : badge(isEn ? 'Loan fully repaid' : '借入金は完済しました', 'green')}${canBorrowAmount(s) > 0 ? btn(isEn ? 'Borrow Restock Funds' : '仕入資金を追加借入', 'open-repay', {}, 'secondary') : ''}</div>`, isEn ? `Balance ${money(s.hq.debt)}` : `残高 ${money(s.hq.debt)}`);
  return `<div class="view-heading"><div><div class="eyebrow">TAX & ROYAL CHARTERS</div><h1>${isEn ? 'Taxes & Royal Trust' : '税・国評価'}</h1></div>${nav(isEn ? 'To HQ' : '本店へ', 'hq')}</div>${exempt ? `<div class="notice">${isEn ? 'Founding Exemption: Taxes are waived for the first 10 days of game start. Operating profit during this period is not taxed.' : '創業特例：ゲーム開始10日は納税免除期間です。この期間の営業利益は課税対象になりません。'}</div>` : ''}<div class="stats-grid">${stat(isEn ? 'Current Operating Profit' : '今期の営業利益', money(s.finance.periodProfit), exempt ? (isEn ? 'Tax exempt' : '免税期間中') : '')}${stat(isEn ? 'Estimated Tax Due' : '次回の納税見込', money(taxEstimate(s)), exempt ? (isEn ? 'Exempt (0 G)' : '免除期間中 0 G') : '')}<div class="stat deadline-stat"><span class="label">${isEn ? 'Turns until Tax' : '納税まで'}</span>${countdownMeter(turnsUntilTax(s), taxCountdownCapacity(s), isEn ? `Tax due in ${turnsUntilTax(s)} turns` : `納税まで残り${turnsUntilTax(s)}ターン`, isTaxExempt(s) ? 'exempt' : '')}</div>${stat(isEn ? 'Cumulative Taxes Paid' : '累計納税額', money(s.finance.paidTax))}</div><div class="two-column"><section class="panel"><div class="panel-heading"><h2>${isEn ? 'Royal Trust & Charters' : '国評価と許認可'}</h2>${badge(trustLevel(s).name, 'gold')}</div><div class="trust-score"><strong>${s.hq.trust.toFixed(1)}</strong><span>${isEn ? 'Royal Trust' : '国家信用'}</span></div>${bar(s.hq.trust, next?.at || 120)}<p class="subtle">${next ? (isEn ? `${(next.at - s.hq.trust).toFixed(1)} points until "${next.name}".` : `次の「${next.name}」まで ${(next.at - s.hq.trust).toFixed(1)}。`) : (isEn ? 'Highest level of trust attained.' : '最高位の信用を獲得しています。')}</p>${orphanageDonationPanel}<details class="trust-permit-details"><summary>${isEn ? 'View all ranks' : 'すべての等級を見る'}</summary><div class="permit-list trust-permit-list">${TRUST_LEVELS.map(t => `<div class="permit ${s.hq.trust >= t.at ? 'unlocked' : ''}"><span>${s.hq.trust >= t.at ? '✓' : '◇'}</span><div><h3>${t.name}<small>${isEn ? 'Rating' : '評価'} ${t.at}</small></h3></div></div>`).join('')}</div></details></section><div>${section(isEn ? 'Current Tax Preparation' : '今期の納付準備', `<dl class="facts"><div><dt>${isEn ? 'HQ Cash' : '本店現金'}</dt><dd>${money(s.hq.cash)}</dd></div><div><dt>${isEn ? 'Est. Cash after Tax' : '納税後の本店現金見込'}</dt><dd class="${profitClass(s.hq.cash - taxEstimate(s))}">${money(s.hq.cash - taxEstimate(s))}</dd></div><div><dt>${isEn ? 'Tax Arrears' : '未納税'}</dt><dd>${money(s.finance.taxArrears)}</dd></div></dl>${s.finance.taxArrears ? `<p class="subtle" style="color:#ff7875;margin-bottom:8px;"><span class="alert-mark" aria-hidden="true">!</span>${isEn ? 'Overdue Tax Arrears: Forcibly collected daily and upon cash receipts, decreasing national trust.' : '未納税の滞納中：日次および入金時に強制徴収され、国家信用が低下します。'}</p>${btn(isEn ? 'Pay Tax Arrears' : '未納税を納付する', 'game-action', { kind: 'payArrears' }, 'primary')}` : ''}`)}${debtSection}${s.finance.history.length ? `<details class="panel tax-history-accordion" data-disclosure="tax-history"><summary class="accordion-summary panel-heading"><div><h2>${isEn ? 'Tax History' : '納税履歴'}</h2><span class="subtle">${isEn ? `Records for all ${s.finance.history.length} periods` : `全 ${s.finance.history.length} 期の記録`}</span></div><span class="accordion-chevron">${isEn ? 'Show History List ▼' : '履歴一覧を表示 ▼'}</span></summary><div class="table-scroll"><table><thead><tr><th>${isEn ? 'Period' : '納税期'}</th><th>${isEn ? 'Profit' : '利益'}</th><th>${isEn ? 'Tax / Paid' : '税額 / 納付'}</th></tr></thead><tbody>${s.finance.history.map(h => `<tr><td>${turnLabel(h.turn)}</td><td>${money(h.profit)}</td><td>${money(h.tax)} / ${money(h.paid)}</td></tr>`).join('')}</tbody></table></div></details>` : section(isEn ? 'Tax History' : '納税履歴', empty(isEn ? 'No tax records yet.' : '納税記録はありません。'))}</div></div>`;
}

export function intelView(s: GameState, ui?: UIState): string {
  const lang: Language = ui?.lang || s.lang || 'ja';
  const isEn = lang === 'en';
  const unlocked = isIntelUnlocked(s);
  const activeBases = s.bases.filter(base => !base.abandoned);
  const adBase = activeBases.find(base => base.id === ui?.intelAdBase) || activeBases[0];
  const adBaseOptions = activeBases.map(base => `<option value="${esc(base.id)}" ${base.id === adBase?.id ? 'selected' : ''}>${esc(localizedBaseName(base.name, lang))}</option>`).join('');
  const adDungeons = s.dungeons.filter(dungeon => dungeon.owned);
  const adDungeon = adDungeons.find(dungeon => dungeon.id === ui?.intelAdDungeon) || adDungeons[0];
  const adDungeonOptions = adDungeons.map(dungeon => `<option value="${esc(dungeon.id)}" ${dungeon.id === adDungeon?.id ? 'selected' : ''}>${esc(localizedDungeonName(dungeon.name, lang))}</option>`).join('');
  const outpostAdvertisingPanel = adBase ? section(isEn ? 'Outpost Advertising' : '拠点の宣伝', `${field(isEn ? 'Target outpost' : '対象拠点', `<select id="intel-ad-base-select" aria-label="${isEn ? 'Target outpost' : '対象拠点'}">${adBaseOptions}</select>`)}<div class="actions">${investButton(isEn ? 'Advertise Outpost' : '拠点を宣伝', 'baseAd', adBase.id)}</div>${adBase.adUntil > s.turn ? badge(isEn ? `Advertising · ${adBase.adUntil - s.turn} turns remaining` : `宣伝中 · 残り ${adBase.adUntil - s.turn}ターン`, 'gold') : ''}`) : '';
  const dungeonAdvertisingPanel = adDungeon ? section(isEn ? 'Dungeon Advertising' : '迷宮の宣伝', `${field(isEn ? 'Target dungeon' : '対象迷宮', `<select id="intel-ad-dungeon-select" aria-label="${isEn ? 'Target dungeon' : '対象迷宮'}">${adDungeonOptions}</select>`)}<div class="actions">${investButton(isEn ? 'Advertise Dungeon' : '迷宮を宣伝', 'dungeonAd', adDungeon.id)}</div>${adDungeon.advertisementUntil > s.turn ? badge(isEn ? `Advertising · ${adDungeon.advertisementUntil - s.turn} turns remaining` : `宣伝中 · 残り ${adDungeon.advertisementUntil - s.turn}ターン`, 'gold') : ''}`) : '';
  const advertisingPanel = outpostAdvertisingPanel || dungeonAdvertisingPanel
    ? `<div class="two-column">${outpostAdvertisingPanel}${dungeonAdvertisingPanel}</div>`
    : '';
  return `<div class="view-heading"><div><div class="eyebrow">RUMORS & INTELLIGENCE</div><h1>${isEn ? 'Rumors & Intelligence' : '噂・情報'}<span>${isEn ? 'Find opportunities' : '商機を探す'}</span></h1></div>${nav(isEn ? 'World Map' : '広域へ', 'world')}</div>${advertisingPanel}${unlocked ? `<div class="intel-grid">${s.rumors.map(r => {
    const a = s.areas.find(a => a.id === r.areaId), d = s.dungeons.find(d => d.id === r.targetId), fresh = s.turn - r.turn < 35;
    const surveyRoute = r.type === 'discovery' && d && ['rumor', 'surveying'].includes(d.phase) && isSurveyUnlocked(s)
      ? nav(d.phase === 'surveying' ? (isEn ? 'View Survey Progress →' : '調査状況を見る →') : (isEn ? 'Survey in Region →' : '地域で調査 →'), 'region', r.areaId, 'primary full')
      : '';
    return `<article class="panel intel-card"><div class="inline-info">${badge(r.type === 'discovery' ? (isEn ? 'Unexplored Region Rumor' : '未踏地域の噂') : (isEn ? 'Expedition Profit Rumor' : '遠征収支の噂'), r.type === 'discovery' ? 'gold' : '')}<span class="subtle">${isEn ? `${Math.floor((s.turn - r.turn) / 5)} days ago` : `${Math.floor((s.turn - r.turn) / 5)}日前`}</span></div><h2>${esc(a?.name ?? (isEn ? 'Kingdom' : '王国'))}</h2><p>${esc(r.text)}</p><dl class="facts"><div><dt>${isEn ? 'Source Accuracy' : '情報源の精度'}</dt><dd>${esc(r.accuracy)}</dd></div><div><dt>${isEn ? 'Freshness' : '鮮度'}</dt><dd>${fresh ? (isEn ? 'Fresh info' : '新しい情報') : (isEn ? 'Outdated info' : '古い情報')}</dd></div></dl>${r.type === 'discovery' ? surveyRoute : btn(isEn ? 'Compare on World Map →' : '広域で比較する →', 'rumor-dungeon', { id: r.targetId }, 'full')}</article>`;
  }).join('')}</div>${!s.rumors.length ? empty(isEn ? 'No rumors yet. Information arrives over time and through taverns.' : 'まだ噂はありません。時間の経過と酒場の運営で情報が届きます。') : ''}` : `<div class="intel-locked-hint"><p class="subtle">${isEn ? 'Rumors & Intelligence is locked.' : '噂・情報は未解禁です。'}</p><details class="survey-unlock-details"><summary>${isEn ? 'Unlock requirement' : '解禁条件'}</summary><span>${isEn ? 'Tavern LV1 unlocks Rumors & Intelligence.' : '噂・情報は酒場LV1で解禁'}</span></details></div>`}`;
}

export function eventsView(s: GameState, ui?: UIState): string {
  const lang: Language = ui?.lang || s.lang || 'ja';
  const isEn = lang === 'en';
  const pop = population(s), swordHolder = s.swordHolder, holder = swordHolder && s.parties.find(p => p.id === swordHolder.partyId), memberId = swordHolder?.memberId, member = holder?.members.find(m => m.id === memberId);
  return `<div class="view-heading"><div><div class="eyebrow">KINGDOM CHRONICLE</div><h1>${isEn ? 'Kingdom Chronicle' : '王国の出来事'}<span>${isEn ? 'Events & History' : '情勢と記録'}</span></h1></div>${badge(isEn ? `${s.events.filter(e => e.state === 'active').length} Active` : `${s.events.filter(e => e.state === 'active').length} 件進行中`, 'gold')}</div><div class="stats-grid">${stat(isEn ? 'Adventurer Population' : '冒険者人口', num(pop.members), `${pop.parties} PT`)}${stat(isEn ? 'Total Fallen / Revived' : '累計死者 / 復活', `${s.stats.deaths} / ${s.stats.revivals}`)}${stat(isEn ? 'New Recruits' : '志願・新規加入', isEn ? `${s.stats.recruits} recruits` : `${s.stats.recruits} <small>人</small>`)}${stat(isEn ? 'Holy Sword Bearer' : '聖剣の担い手', member ? esc(adventurerDisplayName(member.name, lang)) : (isEn ? 'Unconfirmed' : '未確認'), member ? (isEn ? `Rank ${member.rank}` : `${member.rank}ランク`) : '')}</div><div class="event-grid">${s.events.map(e => {
    const isActiveDragon = e.type === 'dragon' && e.state === 'active';
    const isActiveFestival = e.type === 'festival' && e.state === 'active';
    const isSuccessfulWagonAmbush = e.type === 'wagon-ambush' && e.outcome === 'looted' && e.state === 'active';
    const isActiveNobleDinner = e.type === 'noble-dinner' && e.state === 'active';
    const isRefugeeEvent = e.type === 'refugees';
    const isSurveyCorpsEvent = e.type === 'survey-corps';
    const isFairyDreamEvent = e.type === 'fairy-dream';
    const isPendingRefugeeChoice = isRefugeeEvent && e.state === 'active' && e.outcome === undefined;
    const illustration = isActiveDragon
      ? `<img class="event-illustration" src="${dragonEventArt}" alt="${isEn ? 'Giant dragon assaulting royal capital' : '王都を襲う巨大なドラゴン'}" />`
      : isActiveFestival
        ? `<img class="event-illustration" src="${festivalEventArt}" alt="${isEn ? 'Festival celebration in royal plaza' : '王都の広場で開かれる祭り'}" />`
        : isSuccessfulWagonAmbush
          ? `<img class="event-illustration" src="${wagonAmbushArt}" alt="${isEn ? 'Wagon ambushed by bandits on road' : '街道で山賊に襲われる馬車'}" />`
          : isRefugeeEvent
            ? `<img class="event-illustration" src="${refugeeEventArt}" alt="${isEn ? 'Refugees arriving at a kingdom outpost' : '商館に到着した避難民'}" />`
            : isSurveyCorpsEvent
              ? `<img class="event-illustration" src="${surveyCorpsArt}" alt="${isEn ? 'Royal Survey Corps arriving at outpost' : '商館に到着した王立調査兵団'}" />`
              : isFairyDreamEvent
                ? `<img class="event-illustration" src="${fairyDreamArt}" alt="${isEn ? 'Fairy\'s Dream over sleeping adventurers' : '冒険者たちが見るフェアリーの夢'}" />`
          : '';
    const eventClass = isActiveDragon ? 'dragon-event' : isActiveFestival ? 'festival-event' : isSuccessfulWagonAmbush ? 'wagon-ambush-event' : isRefugeeEvent ? 'refugee-event' : isSurveyCorpsEvent ? 'survey-corps-event' : isFairyDreamEvent ? 'fairy-dream-event' : '';
    const remaining = Math.max(0, e.start + e.duration - s.turn);
    const remainingLabel = isRefugeeEvent
      ? e.outcome === 'accepted'
        ? (isEn ? `Sheltering · ${e.daysRemaining ?? 0} days remaining` : `避難民を受け入れ中・残り ${e.daysRemaining ?? 0} 日`)
        : ''
      : isSurveyCorpsEvent
        ? (isEn ? `Stationed · ${e.daysRemaining ?? Math.ceil(remaining / 5)} days remaining` : `宿に滞在中・残り ${e.daysRemaining ?? Math.ceil(remaining / 5)} 日`)
      : isFairyDreamEvent
        ? (isEn ? `Dream Call · ${remaining} turns left` : `夢の導き・残り ${remaining} ターン`)
      : e.type === 'festival'
        ? (isEn ? `~${Math.ceil(remaining / 5)} days left` : `残り ${Math.ceil(remaining / 5)} 日`)
        : (isEn ? `${remaining} turns left` : `残り ${remaining} ターン`);
    const supportButton = e.state === 'active' && canReceiveKingdomSupport(e.type)
      ? btn(e.type === 'bandits'
        ? e.contributed ? (isEn ? 'Requested to Guild' : 'ギルドへ依頼済み') : (isEn ? 'Emergency Guild Request · 3,000 G' : 'ギルドに緊急依頼 · 3,000 G')
        : e.contributed ? (isEn ? 'Kingdom Support Provided' : '国家支援済み') : (isEn ? 'Kingdom Aid 1,500 G · Trust +3' : '国庫支援 1,500 G · 国評価 +3'), 'game-action', { kind: 'contribute', id: e.id }, '', e.contributed)
      : '';
    const banditDefenseAdvice = e.type === 'bandits' && e.state === 'active'
      ? (isEn ? '<p class="subtle">Hint: Fortify outpost defenses and pave highway segments on the region map to reduce wagon ambushes.</p>' : '<p class="subtle">対策：拠点の防衛施設を強化し、地域マップで街道を整備すると、馬車の追いはぎ発生率を下げられます。</p>')
      : '';
    const nobleDinnerChoices = isActiveNobleDinner
      ? `<div class="event-actions">${btn(isEn ? 'Attend Dinner · 3,000 G' : '会食する · 3,000 G', 'game-action', { kind: 'nobleDinnerChoice', id: e.id, option: 'attend' }, 'primary', s.hq.cash < 3000)}${btn(isEn ? 'Decline' : '参加しない', 'game-action', { kind: 'nobleDinnerChoice', id: e.id, option: 'decline' })}</div>`
      : '';
    const refugeeChoices = isPendingRefugeeChoice
      ? `<div class="event-actions">${btn(isEn ? 'Welcome the refugees' : '避難民を受け入れる', 'game-action', { kind: 'refugeesChoice', id: e.id, option: 'accept' }, 'primary')}${btn(isEn ? 'Turn them away' : '受け入れを断る', 'game-action', { kind: 'refugeesChoice', id: e.id, option: 'decline' })}</div>`
      : '';
    return `<article class="panel event-card ${e.state === 'active' ? 'active-event' : ''} ${eventClass}">${illustration}<div class="inline-info">${badge(e.state === 'active' ? (isEn ? 'Active' : '進行中') : (isEn ? 'Ended' : '終了'), e.state === 'active' ? 'gold' : '')}<span class="subtle">${turnLabel(e.start)}</span></div><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p>${e.state === 'active' ? `${isActiveNobleDinner || (isRefugeeEvent && !remainingLabel) ? '' : `<p class="subtle">${remainingLabel}</p>`}${banditDefenseAdvice}${supportButton}${nobleDinnerChoices}${refugeeChoices}` : ''}</article>`;
  }).join('')}</div>${!s.events.length ? `<div class="notice">${isEn ? 'The kingdom is currently at peace. Guild notices, trends, shortages, and bandits will arise over time.' : '現在、王国は平穏です。ギルド指示、流行、供給不足、山賊などが時間とともに発生します。'}</div>` : ''}${s.logs.length ? `<details class="panel chronicle-logs-accordion" data-disclosure="chronicle-logs"><summary class="accordion-summary panel-heading"><div><h2>${isEn ? 'Market & Chronicle Logs' : '商況・イベントの記録'}</h2><span class="subtle">${isEn ? `Latest ${Math.min(40, s.logs.length)} events` : `最新 ${Math.min(40, s.logs.length)} 件の出来事`}</span></div><span class="accordion-chevron">${isEn ? 'Show Log List ▼' : '記録ログを表示 ▼'}</span></summary>${recentLogs(s, 40)}</details>` : section(isEn ? 'Market & Chronicle Logs' : '商況・イベントの記録', empty(isEn ? 'No chronicle logs yet.' : '商況・イベントの記録はありません。'))}`;
}
