import type { FacilityKey, GameState, GameViewId, InvestmentKind } from '../game/model.ts';

export type Language = 'ja' | 'en';
export type ViewId = GameViewId | 'my-page';

export const MY_PAGE_WIDGET_IDS = ['recruitment', 'delivery-map', 'events'] as const;
export type MyPageWidgetId = typeof MY_PAGE_WIDGET_IDS[number];
export const DEFAULT_MY_PAGE_WIDGETS: readonly MyPageWidgetId[] = MY_PAGE_WIDGET_IDS;

export function isMyPageWidgetId(value: string): value is MyPageWidgetId {
  return (MY_PAGE_WIDGET_IDS as readonly string[]).includes(value);
}

export type NewsCategory = 'casualty' | 'event' | 'legend' | 'chronicle';

export interface NewsFilterSettings {
  casualty: boolean;
  event: boolean;
  legend: boolean;
  chronicle: boolean;
}

export const DEFAULT_NEWS_FILTERS: NewsFilterSettings = {
  casualty: true,
  event: true,
  legend: true,
  chronicle: true,
};

export type ModalState =
  | { type: 'campaign' | 'settings' | 'warnings' | 'debug' | 'onboarding-story' | 'onboarding-arrival' | 'debug-onboarding-arrival' | 'news-filter' | 'repay' | 'demon-core-vision' }
  | { type: 'debug-onboarding-story'; scene: number }
  | { type: 'quote'; kind: InvestmentKind; id: string; option: string }
  | { type: 'facility'; kind: 'facility'; id: string; option: FacilityKey }
  | { type: 'party'; id: string; dungeonId?: string }
  | { type: 'open'; id: string; location: 'highway' | 'safe' | 'near' }
  | { type: 'new'; seed: number }
  | { type: 'import'; state: GameState }
  | { type: 'sales-breakdown'; id: string }
  | { type: 'adventurer-create'; baseId: string }
  | { type: 'sword-negotiation'; baseId: string }
  | { type: 'world-detail'; id: string }
  | { type: 'overview' }
  | { type: 'weekly-report'; week?: number; tab?: 'financial' | 'market' | 'adventurers' | 'kingdom'; selectedGood?: import('../game/model.ts').GoodsKey }
  | { type: 'reset-confirm'; resetType: 'all-onboarding' | 'all-standard' | 'onboarding' | 'dungeon' | 'dungeons' | 'base' | 'research' | 'finance'; targetId?: string };

export type BaseTab = 'facilities' | 'logistics' | 'operations' | 'all';

export interface UIState {
  view: ViewId;
  selectedDungeon: string;
  region: string;
  base: string;
  intelAdBase?: string;
  intelAdDungeon?: string;
  dungeon: string;
  layer: string;
  surveyCells: number[];
  partyRank: string;
  partyStatus: string;
  partyPage: number;
  modal: ModalState | null;
  navOpen: boolean;
  dialogueMinimized: boolean;
  dialogueNotice: string | null;
  lang: Language;
  debugTab: string;
  debugBase: string;
  debugDungeon: string;
  tickerSpeed?: 'slow' | 'normal';
  tickerPaused?: boolean;
  timePaused?: boolean;
  timeSpeed?: 1 | 2 | 4;
  newsFilters?: NewsFilterSettings;
  broadcastedCasualties?: string[];
  baseTab?: BaseTab;
  newsExpanded?: boolean;
  disclosures?: Record<string, boolean>;
  selectedAdventurerId?: string;
  myPageWidgets?: MyPageWidgetId[];
}

export type NavigationItem = readonly [ViewId, string, string];
