export const day = (s: GameState): number => Math.floor(s.turn / 5) + 1;
export const turnLabel = (turn: number, lang: Language = 'ja'): string => lang === 'en' ? `Day ${Math.floor(turn / 5) + 1} (${turn % 5 + 1}/5)` : `${Math.floor(turn / 5) + 1}日 ${turn % 5 + 1}/5`;
export type TimeOfDayKey = 'morning' | 'forenoon' | 'afternoon' | 'evening' | 'night';
export const TIME_OF_DAY_KEYS: readonly TimeOfDayKey[] = ['morning', 'forenoon', 'afternoon', 'evening', 'night'];
export const TIME_OF_DAY_NAMES: readonly string[] = ['早朝', '午前', '午後', '夕方', '夜間'];
export const timeOfDayIndex = (turn: number): number => turn % 5;
export const timeOfDayKey = (turn: number): TimeOfDayKey => TIME_OF_DAY_KEYS[turn % 5];
export const timeOfDayName = (turn: number, lang: Language = 'ja'): string => lang === 'en' ? timeOfDayLabel(turn, lang) : TIME_OF_DAY_NAMES[turn % 5];
export const isNightTime = (turn: number): boolean => (turn % 5) === 4;
export const isEveningTime = (turn: number): boolean => (turn % 5) === 3;
export const isDayTime = (turn: number): boolean => (turn % 5) >= 0 && (turn % 5) <= 2;
export const baseFor = (s: GameState, dungeonId: string): Base | undefined => s.bases.find(b => b.dungeonId === dungeonId && !b.abandoned);
export const dungeonFor = (s: GameState, baseId: string): Dungeon | undefined => s.dungeons.find(d => d.id === s.bases.find(b => b.id === baseId)?.dungeonId);
export const activeMembers = (p: Party): Party['members'] => p.members.filter(m => m.status !== 'dead');
export const syncPartySkillsExport = syncPartySkills;
export { syncPartySkills };
export const syncPartyHp = (p: Party): void => {
  const alive = activeMembers(p);
  p.hp = alive.length ? alive.reduce((sum, m) => sum + m.hp, 0) / alive.length : 0;
  syncPartySkills(p);
};
export const trustLevel = (s: GameState) => [...TRUST_LEVELS].reverse().find(t => s.hq.trust >= t.at) ?? TRUST_LEVELS[0];
export const nextTrust = (s: GameState) => TRUST_LEVELS.find(t => t.at > s.hq.trust);
export const isTaxExempt = (s: GameState): boolean => s.turn <= (BALANCE.taxExemptionTurns ?? 50);
export const isTutorialActive = (s: Pick<GameState, 'onboarding'>): boolean => Boolean(s.onboarding && !['complete', 'skipped'].includes(s.onboarding.status));
export const isGracePeriodActive = (s: Pick<GameState, 'onboarding' | 'turn'>): boolean =>
  isTutorialActive(s) || s.turn < 7 * TURNS_PER_DAY;
export const isSurveyUnlocked = (s: GameState): boolean => s.bases.some(b => (b.facilities?.tavern ?? 0) >= 1);
export const isIntelUnlocked = (s: GameState): boolean => s.bases.some(b => (b.facilities?.tavern ?? 0) >= 1);
export const taxExemptionRemaining = (s: GameState): number => Math.max(0, (BALANCE.taxExemptionTurns ?? 50) - s.turn);
export const nextTaxDueTurn = (s: GameState): number => {
  const exemptionEnd = BALANCE.taxExemptionTurns ?? 50;
  const period = Math.max(1, BALANCE.taxPeriod);
  let due = Math.max(0, Math.floor(s.finance.taxDue));
  while (due <= exemptionEnd) due += period;
  return due;
};
export const turnsUntilTax = (s: GameState): number => Math.max(0, nextTaxDueTurn(s) - s.turn);
export const taxCountdownCapacity = (s: GameState): number => s.finance.history.some(entry => entry.turn > (BALANCE.taxExemptionTurns ?? 50))
  ? Math.max(1, BALANCE.taxPeriod)
  : Math.max(1, nextTaxDueTurn(s));
export const taxEstimate = (s: GameState): number => Math.ceil(Math.max(0, s.finance.periodProfit) * BALANCE.taxRate);
export const stockCapacity = (base: Base, good: GoodsKey): number => good === 'food' ? 120 + base.facilities.warehouse * 100 + base.facilities.shop * 40 : good === 'potion' || good === 'magicPotion' || good === 'antidote' ? 40 + base.facilities.shop * 70 + base.facilities.warehouse * 35 : base.facilities.smith * 12 + base.facilities.warehouse * 4;
export const fullStockInventory = (base: Base): Base['inventory'] => ({
  potion: stockCapacity(base, 'potion'), magicPotion: stockCapacity(base, 'magicPotion'), antidote: stockCapacity(base, 'antidote'), food: stockCapacity(base, 'food'),
  weapon: base.facilities.smith > 0 ? stockCapacity(base, 'weapon') : 0,
  armor: base.facilities.smith > 0 ? stockCapacity(base, 'armor') : 0,
});
export const hqCapacity = (s: GameState, good: GoodsKey): number => (good === 'food' ? 700 : good === 'potion' || good === 'magicPotion' || good === 'antidote' ? 400 : 80) * s.hq.level;
export const wagonLimit = (s: GameState): number => 2 + s.hq.level * 2;
export const cashCapacity = (s: GameState): number => 50000 * s.hq.level;
export const debtCapacity = (s: GameState): number => Math.max(50000, 30000 + s.hq.level * 10000 + Math.floor(s.hq.trust * 300));
export const canBorrowAmount = (s: GameState): number => Math.max(0, debtCapacity(s) - s.hq.debt);
export const baseDungeonTravel = (b: Base): number => b.location === 'near' ? 1 : b.location === 'safe' ? 3 : 2;
export const serviceEfficiency = (b: Base): number => Math.max(0.4, 1 - b.damage / 125);
export const innHealingRate = (level: number): number => level <= 0 ? 0 : Math.min(1, 0.5 + (level - 1) * 0.1);
export const innTavernAppeal = (b: Base, levels: Partial<Pick<Base['facilities'], 'inn' | 'tavern'>> = {}): number => {
  const innLevel = levels.inn ?? b.facilities.inn;
  const tavernLevel = levels.tavern ?? b.facilities.tavern;
  return Math.round((innLevel * 2 + tavernLevel * 3) * serviceEfficiency(b) * 10) / 10;
};
export const facilityUsed = (b: Base): number => Object.values(b.facilities).reduce((a, x) => a + x, 0);
export const facilityUpgradeCost = (b: Base, type: FacilityKey): number => Math.round(FACILITIES[type].cost * (b.facilities[type] + 1) ** 1.65);
export const facilityCapacity = (b: Base, type: FacilityKey, level = b.facilities[type]): number => type === 'shop' ? stockCapacity({ ...b, facilities: { ...b.facilities, shop: level } }, 'potion') : type === 'warehouse' ? level * 180 : FACILITIES[type].capacity * level;

export function marketRecognition(s: GameState): number {
  const playerBases = s.bases.filter(b => !b.abandoned);
  const playerDungeons = s.dungeons.filter(d => d.owned || playerBases.some(b => b.dungeonId === d.id));
  if (playerDungeons.length === 0) return 0;
  return Math.max(...playerDungeons.map(d => d.recognition));
}

export function banditSpawnChance(s: GameState): number {
  const baseChance = 1 / 18;
  const recognition = Math.max(0, Math.min(100, marketRecognition(s)));
  // 知名度（0〜100）に応じて出現率が上下する
  // 知名度 0%: 0.3倍 (約 1/60 ≒ 1.67%)
  // 知名度 50%: 1.0倍 (基準値 1/18 ≒ 5.56%)
  // 知名度 100%: 1.7倍 (約 1/10.6 ≒ 9.44%)
  const factor = 0.3 + (recognition / 100) * 1.4;
  return baseChance * factor;
}

export function wagonAmbushChance(s: GameState, b: Base, defenseLevel = b.facilities.defense): number {
  if (isGracePeriodActive(s)) return 0;
  const hasBandits = s.events.some(event => event.type === 'bandits' && event.state === 'active');
  const road = s.roads.find(item => item.id === b.roadConnection);
  const roadLevel = road?.cellLevels.length
    ? road.cellLevels.reduce((sum, level) => sum + level, 0) / road.cellLevels.length
    : road?.level ?? 1;
  const securityFactor = 1 / (1 + Math.max(0, defenseLevel) * 0.2);
  const roadFactor = 1 / (1 + Math.max(0, roadLevel - 1) * 0.2);
  return (hasBandits ? 0.14 : 0.025) * securityFactor * roadFactor;
}

export function monsterRaidRisk(b: Base, d: Dungeon, defenseLevel = b.facilities.defense, s?: Pick<GameState, 'onboarding' | 'turn'>): {
  rawPressure: number;
  defensePower: number;
  remainingPressure: number;
  baseChance: number;
  chance: number;
} {
  const rawPressure = d.difficulty * (b.location === 'near' ? 8 : b.location === 'safe' ? 2 : 3);
  const defensePower = facilityCapacity(b, 'defense', Math.max(0, defenseLevel));
  const remainingPressure = Math.max(0, rawPressure - defensePower);
  const baseChance = Math.min(1, Math.max(0.12, rawPressure / 100));
  const protectedPeriod = Boolean(s && isGracePeriodActive(s));
  const chance = !protectedPeriod && d.bossState === 'alive' && rawPressure > 0 ? baseChance * remainingPressure / rawPressure : 0;
  return { rawPressure, defensePower, remainingPressure, baseChance, chance };
}

export function checkHqUpgradeReady(s: GameState, targetLevel = s.hq.level + 1, lang: Language = s.lang || 'ja'): { ok: boolean; reason: string } {
  const req = HQ_UPGRADE_CONFIG[targetLevel];
  const isEn = lang === 'en';
  if (targetLevel > 5 || !req) return { ok: false, reason: isEn ? 'Max level reached.' : '最大レベルです。' };

  const activeBases = s.bases.filter(b => !b.abandoned);
  const hasCoreLv2 = activeBases.some(b => b.facilities.inn >= 2 || b.facilities.shop >= 2 || b.facilities.warehouse >= 2 || b.facilities.tavern >= 2);
  const hasMaps = s.dungeons.some(d => d.maps.length >= (req.minMaps ?? 0));
  const maxTotalFacility = Math.max(0, ...activeBases.map(b => facilityUsed(b)));
  const totalAllFacilities = activeBases.reduce((sum, b) => sum + facilityUsed(b), 0);
  const maxFloor = Math.max(0, ...s.dungeons.map(d => d.knownFloor));

  if (req.minTrust && s.hq.trust < req.minTrust) {
    return { ok: false, reason: isEn ? `Requires Royal Trust ${req.minTrust}+. (Current: ${Math.floor(s.hq.trust)})` : `国評価 ${req.minTrust} 以上が必要です。（現在: ${Math.floor(s.hq.trust)}）` };
  }
  if (req.minCoreFacilityLevel && !hasCoreLv2) {
    return { ok: false, reason: isEn ? 'At least one basic outpost facility (Inn, Shop, Warehouse, Tavern) must be LV2+.' : '前哨商館の基本施設（宿屋・道具屋・倉庫・酒場）のいずれかをLV2以上にする必要があります。' };
  }
  if (req.minMaps && !hasMaps) {
    return { ok: false, reason: isEn ? 'Must purchase at least 1 dungeon map to begin map trading.' : '迷宮地図を1枚以上購入して地図取引を開始する必要があります。' };
  }
  if (req.minTotalFacilityLevel && maxTotalFacility < req.minTotalFacilityLevel) {
    return { ok: false, reason: isEn ? `An outpost must have total facility LV ${req.minTotalFacilityLevel}+. (Current highest: ${maxTotalFacility})` : `商館の施設合計LVが ${req.minTotalFacilityLevel} 以上必要です。（現在最大: ${maxTotalFacility}）` };
  }
  if (req.minBases && activeBases.length < req.minBases) {
    return { ok: false, reason: isEn ? `Must operate ${req.minBases}+ outposts. (Current: ${activeBases.length})` : `商館を ${req.minBases} 箇所以上運営している必要があります。（現在: ${activeBases.length}箇所）` };
  }
  if (req.minFloor && maxFloor < req.minFloor) {
    return { ok: false, reason: isEn ? `Must reach floor ${req.minFloor}+ in any dungeon. (Current highest: Floor ${maxFloor})` : `いずれかの迷宮で第${req.minFloor}階以上への到達が必要です。（現在最高: 第${maxFloor}階）` };
  }
  if (req.minTotalAllFacilities && totalAllFacilities < req.minTotalAllFacilities) {
    return { ok: false, reason: isEn ? `Total facility LV across all outposts must be ${req.minTotalAllFacilities}+. (Current: ${totalAllFacilities})` : `商会全体の施設合計LVが ${req.minTotalAllFacilities} 以上必要です。（現在: ${totalAllFacilities}）` };
  }
  if (s.hq.cash < req.cost) {
    return { ok: false, reason: isEn ? `Insufficient HQ funds. (Need: ${req.cost.toLocaleString('en-US')} G / Have: ${Math.round(s.hq.cash).toLocaleString('en-US')} G)` : `本店現金が不足しています。（必要: ${req.cost.toLocaleString('ja-JP')} G / 所持: ${Math.round(s.hq.cash).toLocaleString('ja-JP')} G）` };
  }
  return { ok: true, reason: '' };
}
type Region = GameState['areas'][number];
export const regionCellCoordinate = (cell: number): string => `${String.fromCharCode(65 + Math.floor(cell / 4))}${cell % 4 + 1}`;
export const regionCellPlace = (terrain: string, cell: number): string => cell % 4 === 1 ? '国道' : terrain;
export const dungeonCell = (d: Dungeon): number => d.secretCell ?? (d.id === 'd1' ? 13 : 5);
export const roadEntryCells = (area: Region, from: Road['from']): number[] => {
  if (from === 'highway') return [1, 5, 9, 13];
  const dx = area.x - 50, dy = area.y - 50;
  if (Math.abs(dx) >= Math.abs(dy)) return dx >= 0 ? [0, 4, 8, 12] : [3, 7, 11, 15];
  return dy < 0 ? [12, 13, 14, 15] : [0, 1, 2, 3];
};
export const regionCellNeighbors = (cell: number): number[] => {
  const row = Math.floor(cell / 4), col = cell % 4;
  return [row > 0 ? cell - 4 : -1, row < 3 ? cell + 4 : -1, col > 0 ? cell - 1 : -1, col < 3 ? cell + 1 : -1].filter(n => n >= 0);
};
export const defaultRoadCells = (area: Region, from: Road['from'], target: number): number[] => {
  const starts = roadEntryCells(area, from), parent = Array<number>(16).fill(-2), queue = [...starts];
  for (const cell of starts) parent[cell] = -1;
  while (queue.length) {
    const cell = queue.shift()!;
    if (cell === target) break;
    for (const next of regionCellNeighbors(cell)) if (parent[next] === -2) { parent[next] = cell; queue.push(next); }
  }
  if (parent[target] === -2) return [target];
  const path = []; for (let cell = target; cell >= 0; cell = parent[cell]) path.push(cell);
  return path.reverse();
};
export const roadTileCost = (area: Region, from: Road['from'], level = 1): number => Math.round(BALANCE.roadCost * area.cost * level * (from === 'kingdom' ? 1.4 : 1));
export const wagonRegionCell = (s: GameState, w: Wagon): number | null => {
  if (w.location !== 'road') return null;
  const base = s.bases.find(b => b.id === w.baseId), road = s.roads.find(r => r.id === base?.roadConnection);
  if (!road?.cells.length) return null;
  const duration = Math.max(1, w.totalEta), progress = Math.max(0, Math.min(1, (duration - w.eta) / duration));
  const traveled = Math.min(road.cells.length - 1, Math.floor(progress * road.cells.length));
  return w.destination === 'base' ? road.cells[traveled] : road.cells[road.cells.length - 1 - traveled];
};
export const wagonDisplayName = (s: GameState, w: Wagon, lang: Language = 'ja'): string => {
  const index = s.wagons.findIndex(candidate => candidate.id === w.id);
  const number = index >= 0 ? index + 1 : s.wagons.length + 1;
  return lang === 'en' ? `Wagon ${number}` : `馬車${number}`;
};
export const partyRegionCell = (s: GameState, p: Party, b?: Base): number | null => {
  if (p.location !== 'road' && !['traveling', 'homeward'].includes(p.action)) return null;
  const targetBase = b ?? s.bases.find(candidate => candidate.dungeonId === p.currentDungeonId || candidate.dungeonId === p.lastDungeonId);
  if (!targetBase) return null;
  const road = s.roads.find(r => r.id === targetBase.roadConnection);
  if (!road?.cells.length) return null;
  const d = s.dungeons.find(d => d.id === targetBase.dungeonId);
  const total = p.action === 'traveling'
    ? (d ? dungeonArrivalTime(s, d) : roadTravel(s, targetBase))
    : roadTravel(s, targetBase);
  const duration = Math.max(1, total);
  const remaining = Math.max(0, p.timer);
  const progress = Math.max(0, Math.min(1, (duration - remaining) / duration));
  const traveled = Math.min(road.cells.length - 1, Math.floor(progress * road.cells.length));
  return p.action === 'traveling' ? road.cells[traveled] : road.cells[road.cells.length - 1 - traveled];
};
export const partyRoutePosition = (s: GameState, p: Party, b?: Base): number => {
  const targetBase = b ?? s.bases.find(candidate => candidate.dungeonId === p.currentDungeonId || candidate.dungeonId === p.lastDungeonId);
  if (!targetBase) return 50;
  const d = s.dungeons.find(d => d.id === targetBase.dungeonId);
  const total = p.action === 'traveling'
    ? (d ? dungeonArrivalTime(s, d) : roadTravel(s, targetBase))
    : roadTravel(s, targetBase);
  const duration = Math.max(1, total);
  const remaining = Math.max(0, p.timer);
  const progress = Math.max(0, Math.min(1, (duration - remaining) / duration));
  const pct = p.action === 'traveling' ? progress * 100 : (1 - progress) * 100;
  return Math.round(Math.max(5, Math.min(95, pct)));
};
export const roadTravel = (s: GameState, b: Base): number => {
  const d = dungeonFor(s, b.id), road = s.roads.find(r => r.id === b.roadConnection);
  const tileTime = road?.cellLevels.length ? road.cellLevels.reduce((sum, level) => sum + 1 / (1 + (level - 1) * 0.55), 0) / road.cellLevels.length : 1 / (1 + ((road?.level ?? 1) - 1) * 0.55);
  return Math.max(1, Math.ceil((d?.distance ?? 3) * (road?.from === 'kingdom' ? .85 : 1) * tileTime));
};
export const dungeonArrivalTime = (s: GameState, d: Dungeon): number => {
  const b = baseFor(s, d.id);
  return b ? roadTravel(s, b) + baseDungeonTravel(b) : d.distance;
};
export const wagonTravelTime = (s: GameState, b: Base): number => Math.max(roadTravel(s, b), s.roads.find(r => r.id === b.roadConnection)?.cells.length ?? 0);
export const wagonCycleTime = (s: GameState, b: Base): number => {
  const outwardTime = Math.max(wagonTravelTime(s, b), roadTravel(s, b));
  const outpostStayTime = b.facilities.stable >= 3 ? 1 : 2;
  const returnTime = wagonTravelTime(s, b);
  return outwardTime + outpostStayTime + returnTime + 1;
};
export const wagonStaggerInterval = (s: GameState, b: Base): number => {
  const baseWagons = s.wagons.filter(w => w.baseId === b.id);
  if (baseWagons.length >= 3) return 0;
  const activeWagons = s.wagons.filter(w => w.baseId === b.id && w.status !== 'idle');
  const count = activeWagons.length;
  if (count <= 1) return 0;
  const cycle = wagonCycleTime(s, b);
  return Math.max(2, Math.round(cycle / count));
};
export const wagonCycleProgress = (s: GameState, w: Wagon): number => {
  const b = s.bases.find(base => base.id === w.baseId);
  if (!b) return 0;
  const outwardTime = Math.max(wagonTravelTime(s, b), roadTravel(s, b));
  const outpostStayTime = b.facilities.stable >= 3 ? 1 : 2;
  const returnTime = wagonTravelTime(s, b);
  const cycle = wagonCycleTime(s, b);

  if (w.location === 'road' && w.destination === 'base') {
    return Math.max(0, outwardTime - w.eta);
  }
  if (w.location === 'base') {
    return outwardTime + Math.max(0, outpostStayTime - w.eta);
  }
  if (w.location === 'road' && w.destination === 'kingdom') {
    return outwardTime + outpostStayTime + Math.max(0, returnTime - w.eta);
  }
  if (w.location === 'kingdom') {
    return Math.max(0, cycle - w.eta);
  }
  return 0;
};
export function wagonStaggerDelay(s: GameState, w: Wagon): number {
  const b = s.bases.find(base => base.id === w.baseId);
  if (!b) return 1;
  const activeWagons = s.wagons.filter(v => v.baseId === w.baseId && v.status !== 'idle');
  if (activeWagons.length <= 1) return 1;

  const interval = wagonStaggerInterval(s, b);
  if (interval <= 0) return 1;

  const otherWagons = activeWagons.filter(v => v.id !== w.id);

  // 1. 道中（往路）または拠点にいる先行馬車との間隔
  const outboundWagons = otherWagons.filter(v =>
    (v.location === 'road' && v.destination === 'base') || v.location === 'base'
  );
  let headDelay = 1;
  if (outboundWagons.length > 0) {
    const minProgress = Math.min(...outboundWagons.map(v => wagonCycleProgress(s, v)));
    headDelay = Math.max(1, interval - minProgress);
  }

  // 2. 王国で待機中の他の馬車たちとの調整
  const waitingPeers = otherWagons.filter(v => v.location === 'kingdom');
  if (waitingPeers.length === 0) {
    return headDelay;
  }

  // 自分より先に出発すべき待機馬車（ID順による一意なタイブレークで循環デッドロックを防止）
  const earlierPeers = waitingPeers.filter(v => v.id < w.id);
  if (earlierPeers.length > 0) {
    const maxEarlierEta = Math.max(...earlierPeers.map(v => v.eta));
    return Math.max(headDelay, maxEarlierEta + interval);
  }

  return headDelay;
}
export const cargoLoad = (w: Wagon): number => (['potion', 'magicPotion', 'antidote', 'food', 'weapon', 'armor', 'materials', 'passengers'] as const).reduce((n, k) => n + w.cargo[k], 0) + w.cargo.bodies.length;
export const wagonArrival = (s: GameState, w: Wagon): number => {
  const b = s.bases.find(b => b.id === w.baseId);
  if (!b || b.abandoned || w.status === 'idle') return Infinity;
  const travel = wagonTravelTime(s, b);
  if (w.location === 'kingdom') return w.eta + travel;
  if (w.location === 'base') return w.eta + travel * 2 + 1;
  return w.destination === 'base' ? w.eta : w.eta + 1 + travel;
};
export function wagonCargoItems(w: Wagon, lang: Language = 'ja'): string[] {
  const items: string[] = [];
  const isEn = lang === 'en';
  for (const [k, good] of Object.entries(GOODS) as Array<[GoodsKey, typeof GOODS[GoodsKey]]>) {
    if (w.cargo[k] > 0) items.push(`${isEn ? goodName(k, 'en') : good.name} ${w.cargo[k]}`);
  }
  if (w.cargo.cash > 0) items.push(isEn ? `Cash ${Math.round(w.cargo.cash).toLocaleString('en-US')} G` : `現金 ${Math.round(w.cargo.cash).toLocaleString('ja-JP')} G`);
  if (w.cargo.materials > 0) {
    const bd = w.cargo.materialBreakdown;
    const parts = bd
      ? Object.entries(bd)
          .filter(([, c]) => c > 0)
          .map(([n, c]) => {
            const price = materialSellPrice(n);
            return isEn ? `${n} ×${c} (${price} G each)` : `${n} ${c}個(単価 ${price} G)`;
          })
      : [];
    if (parts.length > 0) {
      items.push(isEn ? `Materials ${w.cargo.materials} [${parts.join(', ')}]` : `素材 ${w.cargo.materials}個 [${parts.join('、')}]`);
    } else {
      items.push(isEn ? `Materials ${w.cargo.materials}` : `素材 ${w.cargo.materials}`);
    }
  }
  if (w.cargo.passengers > 0) items.push(isEn ? `Passengers: ${w.cargo.passengers}` : `乗客 ${w.cargo.passengers}人`);
  if (w.cargo.bodies?.length > 0) items.push(isEn ? `Fallen: ${w.cargo.bodies.length}` : `遺体 ${w.cargo.bodies.length}体`);
  return items;
}
export function wagonCargoSummary(w: Wagon, lang: Language = 'ja'): string {
  const items = wagonCargoItems(w, lang);
  return items.length > 0 ? items.join(lang === 'en' ? ', ' : '、') : (lang === 'en' ? 'No cargo' : '積み荷なし');
}
export function wagonCargoDetails(w: Wagon, lang: Language = 'ja'): string {
  const load = cargoLoad(w);
  return lang === 'en' ? `Cargo (${load}/${w.capacity}): ${wagonCargoSummary(w, lang)}` : `積み荷 (${load}/${w.capacity}): ${wagonCargoSummary(w, lang)}`;
}
export function relatedParties(s: GameState, id: string): Party[] {
  if (!s.dungeons.some(d => d.id === id && d.owned)) return [];
  return s.parties.filter(p => p.currentDungeonId === id || (p.lastDungeonId === id && ['resting', 'reforming'].includes(p.action)));
}
export function dungeonSummary(s: GameState, d: Dungeon & { owned: true }): OwnedDungeonSummary;
export function dungeonSummary(s: GameState, d: Dungeon): DungeonSummary;
export function dungeonSummary(s: GameState, d: Dungeon): DungeonSummary {
  if (d.phase === 'rumor') return { id: d.id, areaId: d.areaId, phase: d.phase, phaseName: PHASES[d.phase], name: '', public: false, owned: false };
  if (d.phase === 'surveying') return { id: d.id, areaId: d.areaId, phase: d.phase, phaseName: PHASES[d.phase], name: '調査中', public: false, owned: false };
  const common = { id: d.id, name: d.name, areaId: d.areaId, phase: d.phase, phaseName: PHASES[d.phase], difficulty: d.difficulty, popularity: d.popularity, recognition: d.recognition, distance: d.distance, bossState: d.bossState };
  const monsters = getMonstersForDifficulty(d.difficulty);
  const floors = Math.max(1, d.floors);
  const discoveredMonsters = monsters.filter((_monster, index) => {
    const unlockFloor = index < 2 ? 1 : index === monsters.length - 1 ? floors : Math.max(2, Math.min(floors - 1, Math.ceil(((index + 1) / monsters.length) * floors)));
    return d.knownFloor >= unlockFloor || d.bossState === 'defeated';
  });
  const monsterMaterials = [...new Set(discoveredMonsters.flatMap(monster => monster.drops.map(drop => drop.name)))];
  if (!d.owned) {
    const rumoredMonster = monsters[Math.min(monsters.length - 1, d.difficulty >= 3 ? 1 : 0)] || monsters[0];
    const rumoredDrop = rumoredMonster?.drops[0];
    return { ...common, public: true, owned: false, rumorProfit: d.rumorProfit, rumorFloor: d.rumorFloor, materialRumor: rumoredMonster && rumoredDrop ? `${rumoredMonster.name}の「${rumoredDrop.name}」` : '魔石' };
  }
  const parties = relatedParties(s, d.id).filter(p => p.currentDungeonId === d.id);
  return { ...common, public: true, owned: true, knownFloor: d.knownFloor, active: parties.length, averageProfit: d.returns ? Math.round(d.totalProfit / d.returns) : 0, visits: d.visits, returns: d.returns, materials: monsterMaterials, progressSpeed: d.breakthroughs.filter(t => s.turn - t < 35).length, baseId: baseFor(s, d.id)?.id, deaths: d.deaths ?? 0, wipes: d.wipes ?? 0 };
}
export function warnings(s: GameState): Warning[] {
  const out: Warning[] = [];
  const push = (text: string, view: Warning['view'], id?: string, severity: Warning['severity'] = 'warning') => out.push({ text, view, id, severity });
  if (s.hq.debt > 0 && s.hq.debtDue - s.turn <= 15) push(s.hq.debtOverdue ? '借入金の返済期限を超過' : '借入金の返済期限が近づいています', 'hq');
  if ((!isTaxExempt(s) && s.finance.taxDue - s.turn <= 5) || s.finance.taxArrears) push(s.finance.taxArrears ? `未納税 ${s.finance.taxArrears.toLocaleString()} G（国家信用が低下中）` : '次の納税まで1日以内', 'tax');
  if (s.hq.cash >= cashCapacity(s)) push('本店の金庫が上限に達しています', 'hq');
  for (const b of s.bases.filter(b => !b.abandoned)) {
    if (b.damage > 0) push(`${b.name}：${b.lastDamageCause === 'monster' ? '魔物襲撃被災（修繕が必要）' : '施設損耗（修繕が必要）'}`, 'base', b.id);
    if (b.cash < 500) push(`${b.name}：買い取り現金不足`, 'base', b.id);
    const warehouseCap = b.facilities.warehouse * 180;
    if (warehouseCap > 0 && b.materials >= warehouseCap) push(`${b.name}：倉庫満杯（素材買い取り停止中）`, 'base', b.id);
  for (const k of ['potion', 'magicPotion', 'antidote', 'food'] as const) if (b.inventory[k] === 0) push(`${b.name}：${GOODS[k].name}が欠品`, 'base', b.id);
    if (!s.wagons.some(w => w.baseId === b.id)) push(`${b.name}：馬車が未配備`, 'logistics', b.id);
  }
  for (const d of s.dungeons.filter(d => d.owned)) if (d.offers.length) push(`${d.name}：階層情報 ${d.offers.length}件`, 'maps', d.id, 'info');
  if (s.demonCoreOffers?.length) {
    for (const o of s.demonCoreOffers) {
      push(`${o.partyName}：デーモンコア売却希望（5,000 G）`, 'base', o.baseId, 'info');
    }
  }
  if (s.events.some(e => e.type === 'bandits' && e.state === 'active')) push('街道に山賊が発生しています', 'events');
  if (s.wagons.some(w => w.status === 'delayed')) push('襲撃被害で馬車の到着が遅延', 'logistics');
  return out;
}
export function population(s: GameState) {
  return { parties: s.parties.length, members: s.parties.reduce((n, p) => n + activeMembers(p).length, 0), reforming: s.parties.filter(p => p.action === 'reforming').length,
    ranks: RANKS.map(rank => ({ rank, count: s.parties.filter(p => p.rank === rank).length })) };
}
