export interface DiscoveredMonsterEntry {
  monster: Monster;
  unlockFloor: number;
  discovered: boolean;
  roleLabel: string;
  gradeLabel: string;
  dropName: string;
  dropRarityLabel: string;
  dropValue: number;
  rareDropName?: string;
  rareDropRarityLabel?: string;
  rareDropValue?: number;
}

export interface DungeonEcologySummary {
  stageRank: number;
  stageTitle: string;
  stageDescription: string;
  depthPercent: number;
  mapPercent: number;
  entries: DiscoveredMonsterEntry[];
  discoveredCount: number;
  totalCount: number;
  nextUnlockFloor: number | null;
}

export function dungeonEcology(d: Dungeon, lang: Language = 'ja'): DungeonEcologySummary {
  const isEn = lang === 'en';
  const roster = getMonstersForDifficulty(d.difficulty);
  const floors = Math.max(1, d.floors);
  const entries: DiscoveredMonsterEntry[] = roster.map((monster, idx) => {
    const unlockFloor = idx < 2 ? 1 : idx === roster.length - 1 ? floors : Math.max(2, Math.min(floors - 1, Math.ceil(((idx + 1) / roster.length) * floors)));
    const discovered = d.knownFloor >= unlockFloor || d.bossState === 'defeated';
    const drop = monster.drops[0];
    const rareDrop = monster.drops.find(candidate => candidate.isRare);
    return {
      monster,
      unlockFloor,
      discovered,
      roleLabel: monsterRoleLabel(monster.role, lang),
      gradeLabel: monsterGradeLabel(monster.grade, lang),
      dropName: drop.name,
      dropRarityLabel: dropRarityLabel(drop.rarity, lang),
      dropValue: drop.value,
      ...(rareDrop ? {
        rareDropName: rareDrop.name,
        rareDropRarityLabel: dropRarityLabel(rareDrop.rarity, lang),
        rareDropValue: rareDrop.value,
      } : {}),
    };
  });
  const discoveredCount = entries.filter(e => e.discovered).length;
  const nextHidden = entries.find(e => !e.discovered);
  const depthPercent = Math.min(100, Math.round((d.knownFloor / floors) * 100));
  const mapPercent = Math.min(100, Math.round((d.maps.length / floors) * 100));

  let stageRank = 1;
  let stageTitle = isEn ? 'Surface Exploration Zone' : '表層の探索域';
  let stageDescription = isEn ? 'Ecology near the entrance has just begun to be observed.' : '入口付近の生態系が確認され始めたばかりです。';
  if (d.bossState === 'defeated') {
    stageRank = 5;
    stageTitle = isEn ? 'Fully Conquered Labyrinth' : '完全踏破された迷宮';
    stageDescription = isEn ? 'The innermost lord was defeated, and all floors and unique materials have been cataloged.' : '最深部の主が討伐され、すべての階層と固有素材が記録されました。';
  } else if (depthPercent >= 75) {
    stageRank = 4;
    stageTitle = isEn ? 'Deep Abyssal Realm' : '深層の魔境圏';
    stageDescription = isEn ? 'Reached deep zones hiding formidable foes and rare materials. The presence of the deep lord draws near.' : '強敵や希少素材が眠る深層域まで到達。最深部の主の気配が迫っています。';
  } else if (depthPercent >= 45) {
    stageRank = 3;
    stageTitle = isEn ? 'Mid-Floor Bustling Zone' : '中層の採掘盛況圏';
    stageDescription = isEn ? 'Maps mapped through mid floors; high-value materials and bountiful loot are being brought back.' : '中層まで地図が整備され、高単価な固有素材と多くの戦利品が持ち帰られています。';
  } else if (depthPercent >= 20) {
    stageRank = 2;
    stageTitle = isEn ? 'Shallow Stable Hunting Ground' : '浅層の安定狩場';
    stageDescription = isEn ? 'Shallow monster ecology is understood, and adventurers conduct stably profitable expeditions.' : '浅層の魔物生態が解明され、冒険者たちが安定した黒字遠征を行っています。';
  }

  return {
    stageRank,
    stageTitle,
    stageDescription,
    depthPercent,
    mapPercent,
    entries,
    discoveredCount,
    totalCount: entries.length,
    nextUnlockFloor: nextHidden ? nextHidden.unlockFloor : null,
  };
}

export type FloorDepthTier = 'shallow' | 'mid' | 'deep' | 'abyss';

export interface FloorDepthInfo {
  tier: FloorDepthTier;
  tierLabel: string;
  isDeep: boolean;
  isBossFloor: boolean;
  hue: number;
  color: string;
  badgeClass: string;
}

export function floorDepthInfo(floor: number, totalFloors = 20, lang: Language = 'ja'): FloorDepthInfo {
  const isEn = lang === 'en';
  const maxF = Math.max(1, totalFloors);
  const ratio = maxF <= 1 ? 1 : Math.max(0, Math.min(1, (floor - 1) / (maxF - 1)));
  const isBossFloor = floor === maxF;

  let tier: FloorDepthTier = 'shallow';
  let tierLabel = isEn ? 'Shallow' : '浅層';
  let badgeClass = 'depth-shallow';

  if (isBossFloor || ratio >= 0.85) {
    tier = 'abyss';
    tierLabel = isBossFloor ? (isEn ? 'Deepest BOSS' : '最深部 BOSS') : (isEn ? 'Abyss' : '最深層');
    badgeClass = isBossFloor ? 'depth-boss' : 'depth-abyss';
  } else if (ratio >= 0.60) {
    tier = 'deep';
    tierLabel = isEn ? 'Deep' : '深層';
    badgeClass = 'depth-deep';
  } else if (ratio >= 0.28) {
    tier = 'mid';
    tierLabel = isEn ? 'Mid' : '中層';
    badgeClass = 'depth-mid';
  } else {
    tier = 'shallow';
    tierLabel = isEn ? 'Shallow' : '浅層';
    badgeClass = 'depth-shallow';
  }

  // 1階から最深階まで階層ごとに色が滑らかに遷移するHue
  // 浅層(150度/エメラルドグリーン) -> 中層(210度/サファイアシアン) -> 深層(280度/アメジスト紫) -> 最深層(350度/クリムゾンレッド)
  const hue = Math.round(150 + ratio * 200) % 360;
  const isDeep = tier === 'deep' || tier === 'abyss';
  const lightness = isDeep ? '82%' : '76%';
  const saturation = isDeep ? '88%' : '78%';
  const color = `hsl(${hue}, ${saturation}, ${lightness})`;

  return {
    tier,
    tierLabel,
    isDeep,
    isBossFloor,
    hue,
    color,
    badgeClass,
  };
}

export type DungeonDirection = 'descending' | 'ascending';

export function partyDungeonDirection(p: Party): DungeonDirection | null {
  if (p.location !== 'dungeon') return null;
  return p.action === 'returning' ? 'ascending' : 'descending';
}

export interface PartyCasualtySummary {
  dead: number;
  injured: number;
  healthy: number;
  total: number;
  hasDead: boolean;
  hasInjured: boolean;
}

export function getPartyCasualtySummary(p: Party): PartyCasualtySummary {
  let dead = 0;
  let injured = 0;
  let healthy = 0;
  const members = p.members || [];
  for (const m of members) {
    if (m.status === 'dead') dead++;
    else if (m.status === 'injured') injured++;
    else healthy++;
  }
  return {
    dead,
    injured,
    healthy,
    total: members.length,
    hasDead: dead > 0,
    hasInjured: injured > 0,
  };
}


