import { getMemberMaxHp } from './equipment.ts';
import { activeMembers, baseFor, isEveningTime, isNightTime } from './selectors.ts';
import { log, pick } from './state.ts';
import { communityDungeonImpression, makePartyAware } from './awareness.ts';
import type { ActionResult, GameState, Party, Rank, RecruitmentTarget } from './model.ts';

export const RECRUITMENT_DELAY = 3;
export const RECRUITMENT_BONUS = 6;
export const RECRUITMENT_INTEREST_TURNS = 15;
export const RECRUITMENT_TARGETS: Record<RecruitmentTarget, { label: string; ranks: readonly Rank[] }> = {
  strong: { label: '強そう', ranks: ['A', 'S'] },
  regular: { label: '中堅', ranks: ['B', 'C'] },
  beginner: { label: 'ビギナー', ranks: ['D', 'E'] },
};

export function startRecruitment(s: GameState, dungeonId: string, target: string): ActionResult {
  if (!['complete', 'skipped'].includes(s.onboarding.status) || (s.onboarding.firstReturnStep && s.onboarding.firstReturnStep < 3)) return { ok: false, message: '最初の営業案内を終えると勧誘できます。' };
  if (!Object.prototype.hasOwnProperty.call(RECRUITMENT_TARGETS, target)) return { ok: false, message: '勧誘する冒険者の層を選んでください。' };
  const dungeon = s.dungeons.find(d => d.id === dungeonId);
  if (!dungeon?.owned || dungeon.phase !== 'operating' || dungeon.bossState !== 'alive' || !baseFor(s, dungeonId)) return { ok: false, message: '営業中で未討伐の自社ダンジョンを選んでください。' };
  if (s.recruitment.pending) return { ok: false, message: '現在の勧誘結果が出るまでお待ちください。' };
  if (s.onboarding?.firstReturnStep) s.onboarding.firstReturnStep = 0;
  s.recruitment.pending = { dungeonId, target: target as RecruitmentTarget, startedAt: s.turn, resolvesAt: s.turn + RECRUITMENT_DELAY };
  log(s, `${dungeon.name}へ${RECRUITMENT_TARGETS[target as RecruitmentTarget].label}の冒険者を勧誘中。結果は3ターン後です。`, 'market', { view: 'hq' });
  return { ok: true, message: '無料の勧誘を始めました。3ターン後に1組への働きかけの結果が届きます。' };
}

export function resolveRecruitment(s: GameState, chooseDestination: (s: GameState, p: Party) => void): void {
  const order = s.recruitment.pending;
  if (!order || s.turn < order.resolvesAt) return;
  const dungeon = s.dungeons.find(d => d.id === order.dungeonId);
  const result: NonNullable<GameState['recruitment']['lastResult']> = {
    ...order, completedAt: s.turn, partyId: null, partyName: '', outcome: 'unavailable', learned: false, message: '',
  };
  if (!dungeon?.owned || dungeon.phase !== 'operating' || dungeon.bossState !== 'alive' || !baseFor(s, dungeon.id)) {
    result.outcome = 'cancelled'; result.message = '勧誘先が営業対象ではなくなったため、勧誘を終了しました。';
  } else {
    const candidates = s.parties.filter(p => p.location === 'kingdom' && p.action === 'resting' && p.currentDungeonId === null
      && activeMembers(p).length >= 4 && activeMembers(p).every(member => member.status === 'healthy' && member.hp >= getMemberMaxHp(member))
      && RECRUITMENT_TARGETS[order.target].ranks.includes(p.rank));
    const unawareCandidates = candidates.filter(party => !party.knownDungeons.includes(dungeon.id));
    const party = pick(s, unawareCandidates.length ? unawareCandidates : candidates);
    if (!party) result.message = '王都で勧誘できる対象の冒険者が見つかりませんでした。費用はかかりません。';
    else {
      result.partyId = party.id; result.partyName = party.name;
      result.learned = makePartyAware(s, party, dungeon, communityDungeonImpression(s, dungeon));
      party.recruitmentInterest = { dungeonId: dungeon.id, expires: s.turn + RECRUITMENT_INTEREST_TURNS };
      // Night/evening departures still follow the ordinary travel schedule.
      if (isNightTime(s.turn) || isEveningTime(s.turn)) {
        result.outcome = 'contacted';
        result.message = `${party.name}に${dungeon.name}を紹介しました。訪問先は次の通常時間帯に選択されます。`;
      } else {
        chooseDestination(s, party);
        result.outcome = party.currentDungeonId === dungeon.id && party.action === 'traveling' ? 'departed' : 'declined';
        result.message = result.outcome === 'departed'
          ? `${party.name}が${dungeon.name}へ出発しました。到着には通常の移動時間がかかります。`
          : `${party.name}に${dungeon.name}を紹介しましたが、今回は訪問を見送りました。`;
      }
      if (result.learned) result.message += ' この冒険者はダンジョンの存在を新しく認知しました。';
    }
  }
  s.recruitment.pending = null; s.recruitment.lastResult = result;
  log(s, result.message, result.outcome === 'departed' ? 'success' : 'market', { view: 'hq' });
}
