import { FACILITIES, GOODS, PHASES } from '../game/config.ts';
import { localizedBaseName, localizedDungeonName } from '../game/i18n.ts';
import { btn, esc } from './helpers.ts';
import type { FacilityKey, GameState, GoodsKey } from '../game/model.ts';
import type { UIState } from './model.ts';

export function debugModal(state: GameState, ui: UIState): string {
  const tab = ui.debugTab || 'onboarding';
  const baseId = ui.debugBase || state.bases[0]?.id || 'b1';
  const base = state.bases.find(b => b.id === baseId) || state.bases[0];
  const dungeonId = ui.debugDungeon || state.dungeons[0]?.id || 'd1';
  const dungeon = state.dungeons.find(d => d.id === dungeonId) || state.dungeons[0];

  const isEn = ui.lang === 'en';
  const tabs = [
    { id: 'onboarding', label: isEn ? '📖 Onboarding' : '📖 オンボーディング' },
    { id: 'hq', label: isEn ? '💰 HQ & Finance' : '💰 財務・本店' },
    { id: 'time', label: isEn ? '⏱️ Time & Turns' : '⏱️ 時間・進行' },
    { id: 'base', label: isEn ? '🏰 Outposts' : '🏰 拠点・商館' },
    { id: 'dungeon', label: isEn ? '🗺️ Dungeons' : '🗺️ ダンジョン' },
    { id: 'reset', label: isEn ? '🔄 Reset Progress' : '🔄 進捗リセット' },
  ];

  const tabButtons = `
    <div class="tab-row debug-tabs" style="display:flex;gap:6px;margin-bottom:18px;flex-wrap:wrap;">
      ${tabs.map(t => `<button class="chip ${tab === t.id ? 'active' : ''}" data-action="debug-tab" data-tab="${t.id}">${t.label}</button>`).join('')}
    </div>
  `;

  let content = '';

  if (tab === 'onboarding') {
    const ob = state.onboarding || { status: 'complete', scene: 0 };
    content = `
      <div class="debug-panel">
        <h3>オンボーディング閲覧</h3>
        <p class="subtle">ゲーム進行を破壊することなく、いつでも序章ストーリーや冒険者到着演出を閲覧できます。</p>
        <div class="actions" style="margin-bottom:20px;">
          ${btn('▶ 序章ストーリーを閲覧 (シーン1〜3)', 'debug-view-story', { scene: 0 }, 'primary')}
          ${btn('▶ 最初の来訪演出を閲覧', 'debug-view-arrival', {}, 'secondary')}
        </div>
        <hr>
        <h3>オンボーディング進行ステータスの変更</h3>
        <p class="subtle">現在のセーブデータにおけるオンボーディング状態を直接書き換えます。</p>
        <form id="debug-onboarding-form" style="display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:end;margin-top:12px;">
          <label class="field" style="margin-bottom:0;">
            <span>ステータス (status)</span>
            <select name="status">
              ${[
                ['story', 'story (序章ストーリー表示中)'],
                ['investments', 'investments (初期3施設投資中)'],
                ['awaiting-arrival', 'awaiting-arrival (初来訪待ち)'],
                ['arrival', 'arrival (初来訪モーダル待機)'],
                ['awaiting-return', 'awaiting-return (初遠征からの帰還待ち)'],
                ['complete', 'complete (導入完了・通常プレイ)'],
                ['skipped', 'skipped (スキップ済)']
              ].map(([v, l]) => `<option value="${v}" ${ob.status === v ? 'selected' : ''}>${l}</option>`).join('')}
            </select>
          </label>
          <label class="field" style="margin-bottom:0;">
            <span>ストーリーシーン (scene 0〜2)</span>
            <select name="scene">
              <option value="0" ${ob.scene === 0 ? 'selected' : ''}>0: 夜明け前の追跡</option>
              <option value="1" ${ob.scene === 1 ? 'selected' : ''}>1: 口を開けた迷宮</option>
              <option value="2" ${ob.scene === 2 ? 'selected' : ''}>2: 迷宮の先は国道だった</option>
            </select>
          </label>
          <div style="grid-column:1/-1;display:flex;gap:10px;margin-top:8px;">
            <button class="btn primary" type="submit">オンボーディング状態を適用</button>
            ${btn('チュートリアルを最初からリセット', 'debug-restart-onboarding', {}, 'danger-outline')}
          </div>
        </form>
      </div>
    `;
  } else if (tab === 'hq') {
    const hq = state.hq;
    const fin = state.finance;
    content = `
      <div class="debug-panel">
        <h3>クイック操作</h3>
        <div class="actions" style="margin-bottom:18px;">
          ${btn('+10,000 G', 'debug-quick', { op: 'add-cash-10k' })}
          ${btn('+100,000 G', 'debug-quick', { op: 'add-cash-100k' })}
          ${btn('借金完済 (0 G)', 'debug-quick', { op: 'clear-debt' })}
          ${btn('信用最大 (150)', 'debug-quick', { op: 'max-trust' })}
          ${btn('本店在庫全補充 (各500)', 'debug-quick', { op: 'fill-hq-stock' })}
          ${btn('財務初期化', 'debug-quick', { op: 'reset-hq-finances' }, 'secondary')}
          ${btn('研究全LV0', 'debug-quick', { op: 'reset-hq-research' }, 'secondary')}
        </div>
        <hr>
        <h3>本店財務パラメータ</h3>
        <form id="debug-hq-form">
          <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));gap:12px;margin-top:12px;">
            <label class="field">
              <span>本店現金 (G)</span>
              <input name="cash" type="number" min="0" value="${hq.cash}" required>
            </label>
            <label class="field">
              <span>借金残高 (G)</span>
              <input name="debt" type="number" min="0" value="${hq.debt}" required>
            </label>
            <label class="field">
              <span>返済期限 (T)</span>
              <input name="debtDue" type="number" min="0" value="${hq.debtDue}" required>
            </label>
            <label class="field">
              <span>国家信用 (0〜200)</span>
              <input name="trust" type="number" min="0" max="200" step="1" value="${Math.round(hq.trust)}" required>
            </label>
            <label class="field">
              <span>未納税金 (G)</span>
              <input name="taxArrears" type="number" min="0" value="${fin.taxArrears || 0}">
            </label>
            <label class="field">
              <span>次回納税期日 (T)</span>
              <input name="taxDue" type="number" min="0" value="${fin.taxDue || 35}">
            </label>
            <label class="field">
              <span>本店規模 LV (1〜5)</span>
              <input name="level" type="number" min="1" max="5" value="${hq.level}">
            </label>
            <label class="field" style="justify-content:center;">
              <span>自動仕入設定</span>
              <label class="check" style="margin-top:6px;">
                <input name="autoSupply" type="checkbox" ${hq.autoSupply ? 'checked' : ''}> 自動仕入有効
              </label>
            </label>
          </div>
          <h4 style="margin:14px 0 8px;color:#eee0b8;">本店倉庫在庫</h4>
          <div style="display:grid;grid-template-columns:repeat(4, 1fr);gap:12px;">
            ${(Object.keys(GOODS) as GoodsKey[]).map(g => `
              <label class="field">
                <span>${GOODS[g].name} (${GOODS[g].unit})</span>
                <input name="${g}" type="number" min="0" value="${hq.inventory[g] || 0}">
              </label>
            `).join('')}
          </div>
          <div style="margin-top:16px;">
            <button class="btn primary" type="submit">財務パラメータを更新</button>
          </div>
        </form>
      </div>
    `;
  } else if (tab === 'time') {
    const curDay = Math.floor(state.turn / 5) + 1;
    const curTurnInDay = (state.turn % 5) + 1;
    content = `
      <div class="debug-panel">
        <h3>クイック時間進行・イベント</h3>
        <div class="actions" style="margin-bottom:18px;">
          ${btn('+1日 (5ターン進める)', 'debug-quick', { op: 'advance-1day' })}
          ${btn('+5日 (25ターン進める)', 'debug-quick', { op: 'advance-5days' })}
          ${btn('+30日 (150ターン進める)', 'debug-quick', { op: 'advance-30days' })}
          ${btn('重大情勢を解除', 'debug-quick', { op: 'clear-campaign' })}
          ${btn('👹 オーガ来襲を発生', 'debug-quick', { op: 'start-ogre-raid' })}
          ${btn('🛡️ 調査兵団を来訪させる', 'debug-quick', { op: 'trigger-survey-corps' })}
          ${btn('🧚 フェアリーを出現させる', 'debug-quick', { op: 'trigger-fairy' })}
          ${btn('🔮 デーモンコア売却依頼を発生', 'debug-quick', { op: 'trigger-demon-core-offer' })}
        </div>
        <hr>
        <h3>時間設定</h3>
        <form id="debug-time-form" style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:12px;align-items:end;">
          <label class="field" style="margin-bottom:0;">
            <span>総ターン数 (現在: ${curDay}日目 ${curTurnInDay}/5 ターン)</span>
            <input name="turn" type="number" min="0" value="${state.turn}" required>
          </label>
          <label class="field" style="margin-bottom:0;">
            <span>重大情勢キャンペーン</span>
            <select name="campaign">
              <option value="" ${!state.campaign ? 'selected' : ''}>なし (平常)</option>
              ${state.events.map(e => `<option value="${e.id}" ${state.campaign === e.id ? 'selected' : ''}>${esc(e.title || e.id)}</option>`).join('')}
            </select>
          </label>
          <div style="grid-column:1/-1;margin-top:8px;">
            <button class="btn primary" type="submit">時間設定を適用</button>
          </div>
        </form>
      </div>
    `;
  } else if (tab === 'base') {
    if (!base) {
      content = '<p class="subtle">営業中の商館がありません。</p>';
    } else {
      content = `
        <div class="debug-panel">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:10px;">
            <h3>商館選択</h3>
            <div class="tab-row" style="margin-bottom:0;">
              ${state.bases.map(b => `<button class="chip ${b.id === base.id ? 'active' : ''}" data-action="debug-select-base" data-id="${b.id}">${esc(b.name)}</button>`).join('')}
            </div>
          </div>
          <div class="actions" style="margin-bottom:18px;">
            ${btn('拠点資金 +10,000 G', 'debug-quick', { op: 'add-base-cash', id: base.id })}
            ${btn('拠点在庫補充 (各80)', 'debug-quick', { op: 'fill-base-stock', id: base.id })}
            ${btn('全施設 LV0 (更地)', 'debug-quick', { op: 'facilities-lv0', id: base.id }, 'danger-outline')}
            ${btn('全施設 LV1', 'debug-quick', { op: 'facilities-lv1', id: base.id })}
            ${btn('全施設 LV3', 'debug-quick', { op: 'facilities-lv3', id: base.id })}
            ${btn('全施設 LV5 (最大)', 'debug-quick', { op: 'facilities-lv5', id: base.id })}
          </div>
          <hr>
          <form id="debug-base-form">
            <input type="hidden" name="id" value="${base.id}">
            <h4 style="margin:14px 0 8px;color:#eee0b8;">基本パラメータ</h4>
            <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(160px, 1fr));gap:12px;">
              <label class="field">
                <span>拠点現金 (G)</span>
                <input name="cash" type="number" min="0" value="${base.cash}" required>
              </label>
              <label class="field">
                <span>拠点人気度 (0〜100)</span>
                <input name="popularity" type="number" min="0" max="100" value="${base.popularity}">
              </label>
              <label class="field">
                <span>防衛力 (0〜100)</span>
                <input name="defense" type="number" min="0" max="100" value="${base.defense}">
              </label>
              <label class="field">
                <span>魔石・素材在庫</span>
                <input name="materials" type="number" min="0" value="${base.materials}">
              </label>
            </div>
            <h4 style="margin:14px 0 8px;color:#eee0b8;">拠点商品在庫</h4>
            <div style="display:grid;grid-template-columns:repeat(4, 1fr);gap:12px;">
              ${(Object.keys(GOODS) as GoodsKey[]).map(g => `
                <label class="field">
                  <span>${GOODS[g].name} (${GOODS[g].unit})</span>
                  <input name="good_${g}" type="number" min="0" value="${base.inventory[g] || 0}">
                </label>
              `).join('')}
            </div>
            <h4 style="margin:14px 0 8px;color:#eee0b8;">施設レベル (0〜5)</h4>
            <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(140px, 1fr));gap:12px;">
              ${(Object.keys(FACILITIES) as FacilityKey[]).map(f => `
                <label class="field">
                  <span>${FACILITIES[f].symbol} ${FACILITIES[f].name}</span>
                  <input name="fac_${f}" type="number" min="0" max="5" value="${base.facilities[f] || 0}">
                </label>
              `).join('')}
            </div>
            <div style="margin-top:16px;">
              <button class="btn primary" type="submit">商館パラメータを更新</button>
            </div>
          </form>
        </div>
      `;
    }
  } else if (tab === 'dungeon') {
    content = `
      <div class="debug-panel">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:10px;">
          <h3>ダンジョン選択</h3>
          <div class="tab-row" style="margin-bottom:0;">
            ${state.dungeons.map(d => `<button class="chip ${d.id === dungeon.id ? 'active' : ''}" data-action="debug-select-dungeon" data-id="${d.id}">${esc(localizedDungeonName(d.name, ui.lang))}</button>`).join('')}
          </div>
        </div>
        <div class="actions" style="margin-bottom:18px;">
          ${btn('ボス討伐済みにする', 'debug-quick', { op: 'defeat-boss', id: dungeon.id })}
          ${btn('ボス復活・進行リセット', 'debug-quick', { op: 'reset-dungeon-progress', id: dungeon.id }, 'secondary')}
          ${btn('道路開通・営業中', 'debug-quick', { op: 'operate-dungeon', id: dungeon.id })}
          ${btn('人気度100 (最大)', 'debug-quick', { op: 'max-dungeon-popularity', id: dungeon.id })}
        </div>
        <hr>
        <form id="debug-dungeon-form">
          <input type="hidden" name="id" value="${dungeon.id}">
          <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(170px, 1fr));gap:12px;margin-top:12px;">
            <label class="field">
              <span>進行段階 (phase)</span>
              <select name="phase">
                ${Object.entries(PHASES).map(([k, label]) => `
                  <option value="${k}" ${dungeon.phase === k ? 'selected' : ''}>${k} (${label})</option>
                `).join('')}
              </select>
            </label>
              <label class="field">
                <span>人気度（0〜100）</span>
              <input name="popularity" type="number" min="0" max="100" step="0.1" value="${dungeon.popularity.toFixed(1)}">
            </label>
              <label class="field">
                <span>認知PT率（0〜100%）</span>
                <input name="recognition" type="number" min="0" max="100" step="0.1" value="${dungeon.recognition}">
            </label>
            <label class="field">
              <span>到達済階層 (全${dungeon.floors}階)</span>
              <input name="knownFloor" type="number" min="0" max="${dungeon.floors}" value="${dungeon.knownFloor}">
            </label>
            <label class="field">
              <span>ボス状態</span>
              <select name="bossState">
                <option value="alive" ${dungeon.bossState === 'alive' ? 'selected' : ''}>alive (生存)</option>
                <option value="defeated" ${dungeon.bossState === 'defeated' ? 'selected' : ''}>defeated (討伐済)</option>
              </select>
            </label>
            <label class="field" style="justify-content:center;">
              <span>自社商圏フラグ</span>
              <label class="check" style="margin-top:6px;">
                <input name="owned" type="checkbox" ${dungeon.owned ? 'checked' : ''}> 自社商館あり
              </label>
            </label>
          </div>
          <div style="margin-top:16px;">
            <button class="btn primary" type="submit">ダンジョンパラメータを更新</button>
          </div>
        </form>
      </div>
    `;
  } else if (tab === 'reset') {
    content = `
      <div class="debug-panel reset-panel">
        <div class="notice alert" style="margin-bottom:16px;background:rgba(180,40,40,0.15);border:1px solid #d44;padding:10px 14px;border-radius:4px;">
          <strong style="color:#f88;">⚠️ ${isEn ? 'Progress Reset Center' : '進捗リセット機能'}</strong><br>
          <span class="subtle">${isEn ? 'Safely reset whole game progress or specific domains (onboarding, dungeons, outpost facilities, research, finances).' : 'ゲーム全体の進捗や、特定領域（チュートリアル、ダンジョン攻略、商館施設、技術研究、財務状況）の進捗を初期化・リセットできます。'}</span>
        </div>

        <h3>${isEn ? 'Full Progress Reset' : 'ゲーム全体の進捗リセット'}</h3>
        <p class="subtle">${isEn ? 'Reset all save data and restart the game from scratch. (Opens confirmation dialog)' : '現在のセーブデータを初期化し、最初からゲームを開始します（確認ダイアログが開きます）。'}</p>
        <div class="actions" style="margin-bottom:20px;display:flex;gap:10px;flex-wrap:wrap;">
          ${btn(isEn ? '🔄 Reset All Progress (Onboarding Start)' : '🔄 全進捗リセット（序章ストーリーから開始）', 'open-reset-confirm', { resetType: 'all-onboarding' }, 'danger')}
          ${btn(isEn ? '⚡ Reset All Progress (Standard Start)' : '⚡ 全進捗リセット（通常開始・導入済）', 'open-reset-confirm', { resetType: 'all-standard' }, 'danger-outline')}
        </div>

        <hr>

        <h3>${isEn ? 'Tutorial & Story Progress' : 'オンボーディング・ストーリー進捗'}</h3>
        <p class="subtle">${isEn ? 'Reset onboarding sequence to scene 1 (Night Before Dawn).' : 'オンボーディングを第1話（夜明け前の追跡）からやり直します。'}</p>
        <div class="actions" style="margin-bottom:20px;display:flex;gap:10px;flex-wrap:wrap;">
          ${btn(isEn ? '📖 Restart Onboarding' : '📖 オンボーディングを最初からリセット', 'open-reset-confirm', { resetType: 'onboarding' }, 'secondary')}
          ${btn(isEn ? 'Immediate Tutorial Reset' : '即時チュートリアルリセット', 'debug-restart-onboarding', {}, 'text-btn')}
        </div>

        <hr>

        <h3>${isEn ? 'Dungeon Exploration Progress' : 'ダンジョン攻略・観測進捗リセット'}</h3>
        <p class="subtle">${isEn ? 'Revive bosses, reset explored floors, and reset party awareness/impressions.' : '到達階層を初期化し、ボスを生存(alive)に戻し、認知PT率・平均印象・観測トレンド履歴を初期状態に戻します。'}</p>
        <div class="actions" style="margin-bottom:20px;display:flex;gap:10px;flex-wrap:wrap;">
          ${btn(isEn ? `Reset "${localizedDungeonName(dungeon.name, ui.lang)}" Progress` : `『${esc(dungeon.name)}』の攻略進捗をリセット`, 'open-reset-confirm', { resetType: 'dungeon', targetId: dungeon.id }, 'secondary')}
          ${btn(isEn ? 'Reset All Dungeons' : '全ダンジョンの攻略進捗を一括リセット', 'open-reset-confirm', { resetType: 'dungeons' }, 'danger-outline')}
          ${btn(isEn ? 'Immediate Dungeon Reset' : '即時ダンジョンリセット', 'debug-quick', { op: 'reset-dungeon-progress', id: dungeon.id }, 'text-btn')}
        </div>

        <hr>

        <h3>${isEn ? 'Outpost Facilities Progress' : '拠点・商館開発進捗リセット'}</h3>
        <p class="subtle">${isEn ? 'Demolish all facilities back to LV0, and reset outpost stock.' : '商館の全施設を未建設 (LV0) に戻し、在庫を初期状態にリセットします。'}</p>
        <div class="actions" style="margin-bottom:20px;display:flex;gap:10px;flex-wrap:wrap;">
          ${base ? btn(isEn ? `Reset "${localizedBaseName(base.name, ui.lang)}" Facilities (LV0)` : `『${esc(base.name)}』の全施設をLV0にリセット`, 'open-reset-confirm', { resetType: 'base', targetId: base.id }, 'danger-outline') : '<span class="subtle">商館がありません</span>'}
          ${base ? btn(isEn ? 'Immediate Outpost Reset' : '即時更地化', 'debug-quick', { op: 'facilities-lv0', id: base.id }, 'text-btn') : ''}
        </div>

        <hr>

        <h3>${isEn ? 'Research & Finance Progress' : '研究・財務進捗リセット'}</h3>
        <p class="subtle">${isEn ? 'Reset HQ research tiers to 0, or reset treasury cash, debt and trust rating to defaults.' : '本店の技術研究レベルを全てLV0にリセット、または財務（初期資金24,000G、初期借金、信用ランク2）を初期値に戻します。'}</p>
        <div class="actions" style="margin-bottom:10px;display:flex;gap:10px;flex-wrap:wrap;">
          ${btn(isEn ? 'Reset Research Levels (All LV0)' : '本店研究を初期化 (全LV0)', 'open-reset-confirm', { resetType: 'research' }, 'secondary')}
          ${btn(isEn ? 'Reset Finances (Starting Balance)' : '財務・借金・信用を初期状態にリセット', 'open-reset-confirm', { resetType: 'finance' }, 'secondary')}
          ${btn(isEn ? 'Immediate Research Reset' : '即時研究リセット', 'debug-quick', { op: 'reset-hq-research' }, 'text-btn')}
          ${btn(isEn ? 'Immediate Finance Reset' : '即時財務リセット', 'debug-quick', { op: 'reset-hq-finances' }, 'text-btn')}
        </div>
      </div>
    `;
  }

  return `
    <div class="debug-container">
      ${tabButtons}
      ${content}
    </div>
  `;
}
