import { GOODS } from './config.ts';
import { cashCapacity, hqCapacity, isTaxExempt } from './selectors.ts';
import { log } from './state.ts';
import type { Language } from './i18n.ts';
import type { AccountCategory, Base, GameState, GoodsKey } from './model.ts';

export function book(s: GameState, base: Base | null | undefined, revenue: number, expense = 0, details: { category?: AccountCategory; good?: GoodsKey; quantity?: number } = {}): void {
  const profit = revenue - expense;
  if (!isTaxExempt(s)) s.finance.periodProfit += profit;
  s.finance.totalProfit += profit;
  if (base) {
    base.revenue += revenue; base.profit += profit; base.todayRevenue += revenue; base.todayProfit += profit;
    const category = details.category ?? 'other';
    base.todayAccounts.revenue[category] += revenue;
    base.todayAccounts.expenses[category] += expense;
    if (details.good) {
      const goods = base.todayAccounts.goods[details.good];
      goods.count += details.quantity ?? 0; goods.revenue += revenue; goods.cost += expense;
    }
  }
}
export const researchLevel = (s: GameState, good: GoodsKey): number => s.hq?.research?.[good] || 0;
export const standardSellPrice = (s: GameState, good: GoodsKey, level = researchLevel(s, good)): number =>
  Math.ceil(GOODS[good].sell * (1 + level * 0.25) * s.prices[good]);
export const price = (s: GameState, good: GoodsKey, kind: 'buy' | 'sell' = 'buy', base?: Base | null): number => {
  if (kind === 'sell') {
    if (base?.customPrices?.[good] && base.customPrices[good] > 0) {
      return Math.ceil(base.customPrices[good] * s.prices[good]);
    }
    return standardSellPrice(s, good);
  }
  if (good === 'food') {
    // 食材は小さな相場差も仕入れ画面に出るよう、整数G単位で価格を調整する。
    return Math.max(1, GOODS.food.buy + Math.round((s.prices.food - 1) * 8));
  }
  return Math.ceil(GOODS[good].buy * s.prices[good]);
};
export function facilityPrice(s: GameState, base: Base | null | undefined, key: 'inn' | 'tavern' | 'hospital', levelOverride?: number): number {
  if (key === 'inn') {
    const lv = levelOverride ?? (base?.facilities?.inn || 0);
    if (levelOverride === undefined && base?.customPrices?.inn && base.customPrices.inn > 0) return base.customPrices.inn;
    return lv > 0 ? 12 + lv * 3 : 15;
  }
  if (key === 'tavern') {
    const lv = levelOverride ?? (base?.facilities?.tavern || 0);
    const trend = s.events.some(e => e.type === 'trend' && e.state === 'active') ? 1.5 : 1;
    if (levelOverride === undefined && base?.customPrices?.tavern && base.customPrices.tavern > 0) return Math.round(base.customPrices.tavern * trend);
    return Math.round((lv > 0 ? lv * 7 : 7) * trend);
  }
  const lv = levelOverride ?? (base?.facilities?.hospital || 0);
  if (levelOverride === undefined && base?.customPrices?.hospital && base.customPrices.hospital > 0) return base.customPrices.hospital;
  return lv > 0 ? lv * 8 : 8;
}
export const potionHealAmount = (s: GameState, level = researchLevel(s, 'potion')): number => 15 + level * 8;
export const magicPotionRestoreAmount = (s: GameState, level = researchLevel(s, 'magicPotion')): number => 10 + level * 5;
export const foodValuePerUnit = (s: GameState, level = researchLevel(s, 'food')): number => 6 + level * 2;
export const foodCarryBonus = (s: GameState, level = researchLevel(s, 'food')): number => level * 4;
export const weaponCombatBonus = (s: GameState, smithLv = 1, level = researchLevel(s, 'weapon')): number => smithLv + level * 2;
export const armorCombatBonus = (s: GameState, smithLv = 1, level = researchLevel(s, 'armor')): number => smithLv + level * 2;
export const armorHpBonus = (s: GameState, level = researchLevel(s, 'armor')): number => level * 4;
export function goodEffectSummary(s: GameState, good: GoodsKey, level = researchLevel(s, good), smithLevel = 1, lang: Language = 'ja'): string {
  if (lang === 'en') {
    if (good === 'potion') return `HP recovery +${potionHealAmount(s, level)} / bottle`;
    if (good === 'magicPotion') return `MP recovery +${magicPotionRestoreAmount(s, level)} / bottle`;
    if (good === 'antidote') return 'Cures 1 adventurer of poison';
    if (good === 'food') return `Ration value +${foodValuePerUnit(s, level)} / ration${level > 0 ? ` · Carry cap +${foodCarryBonus(s, level)}` : ''}`;
    if (good === 'weapon') return `Combat power +${weaponCombatBonus(s, smithLevel, level)}~ (Cap +${level * 15})`;
    return `Combat power +${armorCombatBonus(s, smithLevel, level)}~${level > 0 ? ` · Max HP +${armorHpBonus(s, level)} · Endurance +${level * 3}` : ''}`;
  }
  if (good === 'potion') return `HP回復 +${potionHealAmount(s, level)}/本`;
  if (good === 'magicPotion') return `MP回復 +${magicPotionRestoreAmount(s, level)}/本`;
  if (good === 'antidote') return '毒状態の冒険者1名を治療';
  if (good === 'food') return `食料値 +${foodValuePerUnit(s, level)}/食${level > 0 ? `・携行上限 +${foodCarryBonus(s, level)}` : ''}`;
  if (good === 'weapon') return `戦闘力 +${weaponCombatBonus(s, smithLevel, level)}〜（上限 +${level * 15}）`;
  return `戦闘力 +${armorCombatBonus(s, smithLevel, level)}〜${level > 0 ? `・最大HP +${armorHpBonus(s, level)}・継戦 +${level * 3}` : ''}`;
}
export function hqDeposit(s: GameState, amount: number): number {
  if (amount <= 0) return 0;
  if (s.finance.taxArrears > 0) {
    const seized = Math.min(amount, s.finance.taxArrears);
    s.finance.taxArrears -= seized;
    s.finance.paidTax += seized;
    amount -= seized;
    log(s, `【強制徴収】馬車到着資金より未納税 ${seized.toLocaleString()} G が国庫へ強制徴収されました（未納残高: ${s.finance.taxArrears.toLocaleString()} G）。`, 'warning', { view: 'tax' });
  }
  const accepted = Math.min(amount, Math.max(0, cashCapacity(s) - s.hq.cash));
  s.hq.cash += accepted;
  return amount - accepted;
}
export function restockHQ(s: GameState): void {
  if (!s.hq.autoSupply) return;
  for (const k of Object.keys(GOODS) as GoodsKey[]) {
    if ((k === 'weapon' || k === 'armor') && s.hq.trust < 25) continue;
    const target = Math.floor(hqCapacity(s, k) * 0.65);
    const count = Math.min(Math.max(0, target - s.hq.inventory[k]), Math.max(0, Math.floor((s.hq.cash - 3500) / price(s, k))));
    s.hq.inventory[k] += count; s.hq.cash -= count * price(s, k);
  }
}
