      const shopMarker = shopBase ? `<span class="shop-tile-marker ${shopDungeonActive > 0 ? 'dungeon-active' : ''}" aria-label="${esc(localizedBaseName(shopBase.name, lang))}・${isEn ? 'Shop' : '商店'}" title="${esc(localizedBaseName(shopBase.name, lang))}"><b>⚑</b><small>${isEn ? 'Shop' : '商店'}</small>${liveShopPulse}</span>` : '';
      const kingdomEntry = roads.some(({ road }) => road.from === 'highway' && road.cells[0] === i) || (a.id === 'e' && highway && i === 1);
      const cellText = builder ? target ? (isEn ? 'Target' : '接続先') : next ? freeTile ? (isEn ? 'Use Highway' : '国道を利用') : (isEn ? `Build Road · ${tileCost.toLocaleString()} G` : `道を敷く · ${tileCost.toLocaleString()} G`) : paved ? (isEn ? `Road LV${roadLevel}` : `道路 LV${roadLevel}`) : place : shopBase ? (isEn ? 'Shop' : '商店') : found ? (isEn ? '◇ Found' : '◇ 発見') : rumored ? (isEn ? '? Rumor' : '? 噂の範囲') : paved ? (isEn ? `Road LV${roadLevel}` : `道路 LV${roadLevel}`) : place;
      const cellSubtext = builder ? target ? (isEn ? 'Connect here' : 'ここまでつなぐ') : next ? freeTile ? (isEn ? 'Free' : '無料') : (isEn ? 'Available' : '選択可能') : (isEn ? 'Survey / Pave' : '調査・整備') : shopBase ? esc(localizedBaseName(shopBase.name, lang)) : surveyed ? (isEn ? 'Surveyed' : '調査済み') : chosen ? (isEn ? 'Target' : '調査対象') : '';
