import type { GameState } from '../game/model.ts';
import { empty, esc, nav } from './helpers.ts';
import {
  DEFAULT_MY_PAGE_WIDGETS,
  isMyPageWidgetId,
  MY_PAGE_WIDGET_IDS,
  type MyPageWidgetId,
  type UIState,
} from './model.ts';
import { eventsView } from './business.ts';
import { supplyTripView } from './operations.ts';
import { recruitmentPanel } from './recruitment.ts';

const COMPONENTS: Record<MyPageWidgetId, { title: { ja: string; en: string }; description: { ja: string; en: string } }> = {
  recruitment: {
    title: { ja: '勧誘', en: 'Recruitment' },
    description: { ja: '冒険者パーティをダンジョンへ勧誘します。', en: 'Invite an adventurer party to a dungeon.' },
  },
  'delivery-map': {
    title: { ja: '配送マップ', en: 'Delivery map' },
    description: { ja: '馬車と冒険者の移動状況を地図で確認します。', en: 'Track wagons and adventurers on the route map.' },
  },
  events: {
    title: { ja: '出来事', en: 'Kingdom events' },
    description: { ja: '王国のイベントと記録を表示します。', en: 'View kingdom events and chronicle entries.' },
  },
};

function selectedWidgets(ui: UIState): MyPageWidgetId[] {
  const configured = ui.myPageWidgets ?? [...DEFAULT_MY_PAGE_WIDGETS];
  return configured.filter((widget, index): widget is MyPageWidgetId =>
    isMyPageWidgetId(widget) && configured.indexOf(widget) === index,
  );
}

function componentContent(id: MyPageWidgetId, s: GameState, ui: UIState): string {
  if (id === 'recruitment') return recruitmentPanel(s, ui);
  if (id === 'events') return eventsView(s, ui);

  const base = s.bases.find(candidate => candidate.id === ui.base && !candidate.abandoned)
    || s.bases.find(candidate => !candidate.abandoned);
  return base
    ? supplyTripView(s, base, false, ui)
    : `<div class="notice">${ui.lang === 'en' ? 'Build an outpost to display a delivery map.' : '配送マップを表示するには、営業中の商館が必要です。'}${nav(ui.lang === 'en' ? 'Open logistics' : '物流を開く', 'logistics', undefined, 'button')}</div>`;
}

export function myPageView(s: GameState, ui: UIState): string {
  const lang = ui.lang || s.lang || 'ja';
  const isEn = lang === 'en';
  const widgets = selectedWidgets(ui);
  const availableWidgets = MY_PAGE_WIDGET_IDS;

  const picker = availableWidgets.map(id => {
    const component = COMPONENTS[id];
    const enabled = widgets.includes(id);
    return `<article class="my-page-component-option ${enabled ? 'is-selected' : ''}">
      <div class="my-page-component-copy"><strong>${component.title[lang]}</strong><p>${component.description[lang]}</p></div>
      <button type="button" class="btn ${enabled ? 'secondary' : 'primary'}" data-action="my-page-widget-toggle" data-widget="${id}" aria-pressed="${enabled}">${enabled ? (isEn ? 'Remove' : '非表示') : (isEn ? 'Add' : '追加')}</button>
    </article>`;
  }).join('');

  const dashboard = widgets.length
    ? widgets.map((id, index) => {
      const component = COMPONENTS[id];
      return `<section class="my-page-widget my-page-widget-${id}" aria-label="${esc(component.title[lang])}">
        <header class="my-page-widget-header">
          <div><span class="eyebrow">${isEn ? `COMPONENT ${index + 1}` : `表示部品 ${index + 1}`}</span><h2>${component.title[lang]}</h2></div>
          <div class="my-page-widget-controls" role="group" aria-label="${isEn ? 'Reorder or remove component' : '部品の順序と表示設定'}">
            <button type="button" class="btn chip" data-action="my-page-widget-move" data-widget="${id}" data-direction="up" aria-label="${isEn ? 'Move up' : '上へ移動'}"${index === 0 ? ' disabled' : ''}>↑</button>
            <button type="button" class="btn chip" data-action="my-page-widget-move" data-widget="${id}" data-direction="down" aria-label="${isEn ? 'Move down' : '下へ移動'}"${index === widgets.length - 1 ? ' disabled' : ''}>↓</button>
            <button type="button" class="btn text-btn" data-action="my-page-widget-toggle" data-widget="${id}">${isEn ? 'Remove' : '削除'}</button>
          </div>
        </header>
        <div class="my-page-widget-content">${componentContent(id, s, ui)}</div>
      </section>`;
    }).join('')
    : `<div class="my-page-empty">${empty(isEn ? 'No components selected. Add one above to build your page.' : '表示部品がありません。上から部品を追加してページを作成してください。')}</div>`;

  return `<div class="my-page-view">
    <div class="view-heading"><div><div class="eyebrow">PERSONAL DASHBOARD</div><h1>${isEn ? 'My Page' : 'マイページ'}<span>${isEn ? 'Choose what you want to see' : '表示する情報を組み合わせる'}</span></h1></div></div>
    <section class="panel my-page-editor" aria-labelledby="my-page-editor-title">
      <div class="panel-heading"><div><h2 id="my-page-editor-title">${isEn ? 'Page components' : '表示する部品'}</h2><p class="subtle">${isEn ? 'Add or remove components, then reorder them below. Your choices are saved.' : '部品を追加・削除し、下の矢印で順序を変更できます。設定は保存されます。'}</p></div></div>
      <div class="my-page-component-picker">${picker}</div>
    </section>
    <div class="my-page-widgets">${dashboard}</div>
  </div>`;
}
