export const BASE_MATERIAL_BUY_PRICE = 18;
export const BASE_MATERIAL_SELL_PRICE = 29;

export function getMaterialDef(name: string): MaterialDef {
  const monsterDrop = getMonsterDrop(name);
  if (monsterDrop) {
    return {
      id: `mat-${monsterDrop.id}`,
      name,
      weight: monsterDrop.value / BASE_MATERIAL_BUY_PRICE,
      rarity: monsterDrop.rarity,
      category: 'beast',
      description: monsterDrop.description,
    };
  }
  const found = MATERIAL_CATALOG[name];
  if (found) return found;
  return {
    id: `mat-gen-${name}`,
    name,
    weight: 1.0,
    rarity: 'common',
    category: 'gem',
    description: '迷宮から採取された素材。',
  };
}

export function materialBuyPrice(name: string, priceMultiplier = 1): number {
  const def = getMaterialDef(name);
  return Math.round(BASE_MATERIAL_BUY_PRICE * def.weight * priceMultiplier);
}

export function materialSellPrice(name: string, priceMultiplier = 1): number {
  const def = getMaterialDef(name);
  return Math.round(BASE_MATERIAL_SELL_PRICE * def.weight * priceMultiplier);
}

export function rarityLabel(rarity: MaterialRarity, lang: Language = 'ja'): string {
  if (lang === 'en') {
    return {
      common: 'Common',
      uncommon: 'Uncommon',
      rare: 'Rare',
      epic: 'Epic',
    }[rarity];
  }
  return {
    common: '普通',
    uncommon: '上質',
    rare: '希少',
    epic: '伝説',
  }[rarity];
}
