export function getAdventurerSituation(party: Party, member: Member): AdventurerSituation {
  // 1. 怪我、死亡者が出てダンジョンをリタイアしたとき
  if (
    member.status === 'injured' ||
    party.members.some(m => m.status === 'injured' || m.status === 'dead') ||
    party.lastReturnReason === 'casualty'
  ) {
    return 'casualty';
  }

  // 2. 初回到着時 (怪我なしで、探索未経験または初回到着フラグ)
  if (
    party.isFirstArrival ||
    (party.trips === 0 && (!party.floor || party.floor <= 1) && !party.lastProfit && !party.lastTradeNote)
  ) {
    return 'first_arrival';
  }

  // 3. レベルアップしたとき
  if (member.justLeveledUp || party.justLeveledUp) {
    return 'levelup';
  }

  // 4. 装備を買ったとき
  if (
    member.boughtEquipment ||
    party.boughtEquipment ||
    (party.lastTradeNote && (party.lastTradeNote.includes('鍛冶屋') || party.lastTradeNote.includes('装備')))
  ) {
    return 'equipment';
  }

  // 5. 酒場を利用したとき
  if (party.usedTavern || party.lastUsedFacility === 'tavern') {
    return 'tavern';
  }

  // 6. 宿屋を利用したとき
  if (party.usedInn || party.lastUsedFacility === 'inn' || party.action === 'healing') {
    return 'inn';
  }

  // 7. 一時退却をして、再び挑戦するとき
  if (
    party.retreated ||
    party.lastReturnReason === 'retreat' ||
    (party.lastEncounter && party.lastEncounter.includes('退却'))
  ) {
    return 'retreat';
  }

  // 8. 平常時、到着時
  return 'normal';
}

export function getAdventurerSpeech(
  s: GameState,
  member: Member,
  party: Party,
  lang: Language = 'ja'
): { situation: AdventurerSituation; text: string } {
  const situation = getAdventurerSituation(party, member);
  const speeches = (ADVENTURER_SPEECHES[lang] || ADVENTURER_SPEECHES.ja)[situation];
  const count = speeches.length;
  // メンバーID、ターン数、パーティ名から安定した擬似乱数シードを計算
  const nameHash = (party.name || '').split('').reduce((acc, ch) => (acc * 31 + ch.charCodeAt(0)) >>> 0, 0);
  const seed = (Math.abs(member.id * 37 + (s.turn || 1) * 13 + nameHash)) >>> 0;
  const index = seed % count;
  const text = speeches[index] ?? speeches[0];
  return { situation, text };
}
