import { adventurerDisplayName, badge, bar, empty, esc, partyCasualtyBadges, partyDirectionBadge, partyDisplayName, stat } from './helpers.ts';
import { getPartyCasualtySummary, turnLabel } from '../game/selectors.ts';
import { ensureMinimumEquipment, equipmentEffectText, getEquippedMemberStats, getMemberMaxMp } from '../game/equipment.ts';
import { jobName, localizedBaseName, localizedDungeonName } from '../game/i18n.ts';
import type { GameState, PartyAction, SponsoredAdventurer } from '../game/model.ts';
import type { Language } from './model.ts';

const actionName = (action: PartyAction, lang: Language): string => {
  const names: Record<PartyAction, [string, string]> = {
    resting: ['休息中', 'Resting'], reforming: ['PT募集中', 'Recruiting'], traveling: ['移動中', 'Traveling'],
    hunting: ['資金稼ぎ', 'Earning funds'], visiting: ['商館で補給中', 'Resupplying'], exploring: ['迷宮を探索中', 'Exploring'],
    returning: ['迷宮から帰還中', 'Retreating'], homeward: ['王国へ帰還中', 'Heading home'], healing: ['治療中', 'Recovering'],
  };
  return names[action][lang === 'en' ? 1 : 0];
};

function logList(adventurer: SponsoredAdventurer, kind: 'activity' | 'decision', lang: Language): string {
  const entries = (adventurer.logs || []).filter(entry => entry.kind === kind).slice(-40).reverse();
  if (!entries.length) return `<p class="subtle">${lang === 'en' ? 'No records yet.' : '記録はまだありません。'}</p>`;
  return `<div class="log-list">${entries.map(entry => `<div class="log-entry"><span class="log-time">${turnLabel(entry.turn)}</span>${badge(kind === 'activity' ? (lang === 'en' ? 'ACTIVITY' : '活動') : (lang === 'en' ? 'DECISION' : '判断'), kind === 'activity' ? 'green' : 'gold')}<span class="log-message">${esc(entry.text)}</span></div>`).join('')}</div>`;
}

export function adventurerWatchView(s: GameState, adventurerId: string | undefined, lang: Language = 'ja'): string {
  const isEn = lang === 'en';
  const adventurer = s.sponsoredAdventurers.find(candidate => candidate.id === adventurerId);
  if (!adventurer) return empty(isEn ? 'This adventurer cannot be found.' : '見守る冒険者が見つかりません。');

  const party = s.parties.find(candidate => candidate.id === adventurer.partyId);
  const member = party?.members.find(candidate => candidate.id === adventurer.memberId);
  const base = s.bases.find(candidate => candidate.id === adventurer.baseId);
  const dungeonId = party?.currentDungeonId || party?.lastDungeonId;
  const dungeon = s.dungeons.find(candidate => candidate.id === dungeonId);
  const status = member?.status === 'dead' || adventurer.status === 'dead'
    ? (isEn ? 'Fallen' : '戦死')
    : adventurer.status === 'lost' || !party
      ? (isEn ? 'Missing' : '消息不明')
      : (isEn ? 'Active' : '活動中');
  const activePartyMembers = party?.members.filter(candidate => candidate.status !== 'dead') || [];
  const partyCas = party ? getPartyCasualtySummary(party) : null;
  if (member) ensureMinimumEquipment(member);
  const equipped = member ? getEquippedMemberStats(member) : null;
  const partyMembers = party?.members.length
    ? party.members.map(candidate => {
        const isTarget = candidate.id === adventurer.memberId;
        const badgeKind = candidate.status === 'healthy' ? 'green' : candidate.status === 'injured' ? 'amber' : 'red';
        const statusLabel = candidate.status === 'healthy' ? (isEn ? 'Healthy' : '健在') : candidate.status === 'injured' ? (isEn ? 'Injured 🩹' : '負傷 🩹') : (isEn ? 'Fallen 💀' : '戦死 💀');
        return `<span class="badge ${badgeKind} ${isTarget ? 'target-member-badge' : ''}" title="${statusLabel}">${esc(adventurerDisplayName(candidate.name, lang))} · ${esc(jobName(candidate.job, lang))}（${statusLabel}）</span>`;
      }).join(' ')
    : `<span class="subtle">${isEn ? 'No party members.' : '仲間はいません。'}</span>`;
  const dirBadge = party ? partyDirectionBadge(party, lang) : '';
  const currentActivity = party
    ? `${actionName(party.action, lang)}${dungeon ? ` · ${esc(localizedDungeonName(dungeon.name, lang))}` : ''}${party.location === 'dungeon' ? ` · ${isEn ? `Floor ${party.floor}` : `第${party.floor}階`}${dirBadge ? ` ${dirBadge}` : ''}` : ''}`
    : status;

  const partySummaryDetail = party
    ? `${activePartyMembers.length} / ${party.members.length} ${isEn ? 'members' : '人'}${partyCas?.hasDead ? (isEn ? ' (Fallen)' : '（戦死あり）') : partyCas?.hasInjured ? (isEn ? ' (Injured)' : '（負傷あり）') : ''}`
    : status;

  return `<div class="view-heading"><div><div class="eyebrow">${isEn ? 'ADVENTURER WATCH' : 'ADVENTURER WATCH'}</div><h1>${esc(adventurerDisplayName(adventurer.name, lang))}<span>${esc(jobName(adventurer.job, lang))}</span></h1></div>${badge(status, status === (isEn ? 'Active' : '活動中') ? 'green' : 'red')}</div>
    <section class="panel adventurer-quote"><span class="eyebrow">${isEn ? 'A NEW JOURNEY' : '新たな冒険へ'}</span><p>「${isEn ? 'I wonder what kind of adventures lie ahead.' : 'どんな冒険をしてくれるか、楽しみだ'}」</p></section>
    <section class="panel adventurer-summary">
      <h2>${isEn ? 'Current Status' : '現在の状況'}</h2>
      <div class="stats-grid compact">
        ${stat(isEn ? 'Level' : 'レベル', `LV${member?.level ?? adventurer.level}`, isEn ? 'Growth continues through expeditions' : '遠征を通じて成長します')}
        ${stat(isEn ? 'HP' : 'HP', member ? `${Math.round(member.hp)} / ${Math.round(equipped!.maxHp)}` : '—', member ? (member.status === 'healthy' ? (isEn ? 'Healthy' : '健在') : member.status === 'injured' ? (isEn ? 'Injured' : '負傷') : (isEn ? 'Fallen' : '戦死')) : status)}
        ${stat('MP', member ? `${equipped!.mp ?? 0} / ${getMemberMaxMp(member)}` : '—')}
        ${stat(isEn ? 'Equipment' : '装備', member ? `+${member.equipment}` : '—', isEn ? 'Current gear' : '現在の装備段階')}
        ${stat(isEn ? 'Party' : 'パーティ', party ? esc(partyDisplayName(party.name, lang)) : '—', partySummaryDetail, partyCas?.hasDead ? 'negative' : partyCas?.hasInjured ? 'warning' : '')}
      </div>
      <details class="adventurer-stat-details">
        <summary>${isEn ? 'Detailed stats' : '詳細ステータス'}</summary>
        <div class="stats-grid compact">
          ${stat(isEn ? 'Attack' : '攻撃', member ? `${equipped!.attack ?? 0}` : '—')}
          ${stat(isEn ? 'Defense' : '防御', member ? `${equipped!.defense ?? 0}` : '—')}
          ${stat(isEn ? 'Magic Attack' : '魔攻', member ? `${equipped!.magicAttack ?? 0}` : '—')}
          ${stat(isEn ? 'Magic Defense' : '魔防', member ? `${equipped!.magicDefense ?? 0}` : '—')}
          ${stat(isEn ? 'Speed' : '素早さ', member ? `${equipped!.speed ?? 0}` : '—')}
        </div>
      </details>
      <p><strong>${isEn ? 'Current activity:' : '現在の活動：'}</strong> ${currentActivity}</p>
      ${party?.action === 'reforming' ? `
        <div class="recruiting-progress-box" style="margin:12px 0;padding:12px 14px;background:#203028;border:1px solid #4a6851;border-radius:6px;">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
            <strong style="color:#d8e8d4;font-size:0.88rem;">${isEn ? 'Party Recruitment Progress' : '仲間集めの進捗'}</strong>
            <span class="badge gold">${activePartyMembers.length} / 4 ${isEn ? 'members' : '人'}</span>
          </div>
          ${bar(activePartyMembers.length, 4)}
          <small class="subtle" style="display:block;margin-top:6px;color:#a8c2b5;">${isEn ? 'When 4 members gather, they will select a dungeon and begin their expedition.' : '4人のパーティが揃うと、目標の迷宮を選定して遠征に出発します。'}</small>
        </div>` : ''}
      <p class="subtle" style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
        <span>${isEn ? 'Sponsored by' : '支援した商店'}：<strong>${esc(base ? localizedBaseName(base.name, lang) : '—')}</strong></span>
        ${base ? `<button type="button" class="btn text-btn" data-action="navigate" data-view="base" data-id="${base.id}" style="padding:2px 6px;font-size:0.78rem;">${isEn ? 'Visit Outpost →' : '商館へ移動 →'}</button>` : ''}
        ${party ? partyCasualtyBadges(party, lang) : ''}
      </p>
      <div class="adventurer-party-members">${partyMembers}</div>
    </section>
    <section class="panel adventurer-gear-section">
      <div class="panel-heading">
        <h2>${isEn ? 'Equipped Gear' : '装備品'}</h2>
        <span class="badge gold">${isEn ? 'Loadout' : '身支度'}</span>
      </div>
      <p class="subtle">${isEn ? 'Grades −3 to +3 change power/armor by 1 and special bonuses by 10% per grade.' : '品質 −3〜＋3：1段階ごとに威力・防御±1、特殊効果±10%。'}</p>
      <div class="gear-slot-grid">
        <div class="gear-slot-card gear-card-weapon">
          <span class="slot-label">${isEn ? 'Weapon' : '武器'}</span>
          <strong>${esc(member?.gear?.weapon?.name || '—')}</strong>
          <small>${member ? esc(equipmentEffectText(member.gear.weapon, isEn)) : '—'}</small>
        </div>
        <div class="gear-slot-card">
          <span class="slot-label">${isEn ? 'Head' : '頭部'}</span>
          <strong>${esc(member?.gear?.head?.name || '—')}</strong>
          <small>${member ? esc(equipmentEffectText(member.gear.head, isEn)) : '—'}</small>
        </div>
        <div class="gear-slot-card ${member?.gear?.body?.name === '布の服' ? 'card-cloth-base' : ''}">
          <span class="slot-label">${isEn ? 'Body' : '身体'}</span>
          <strong>${esc(member?.gear?.body?.name === '布の服' && isEn ? 'Cloth Clothes' : (member?.gear?.body?.name || (isEn ? 'Cloth Clothes' : '布の服')))}</strong>
          <small>${member ? esc(equipmentEffectText(member.gear.body, isEn)) : '—'}</small>
        </div>
        <div class="gear-slot-card">
          <span class="slot-label">${isEn ? 'Arms' : '腕部'}</span>
          <strong>${esc(member?.gear?.arms?.name || '—')}</strong>
          <small>${member ? esc(equipmentEffectText(member.gear.arms, isEn)) : '—'}</small>
        </div>
        <div class="gear-slot-card">
          <span class="slot-label">${isEn ? 'Legs' : '脚部'}</span>
          <strong>${esc(member?.gear?.legs?.name || '—')}</strong>
          <small>${member ? esc(equipmentEffectText(member.gear.legs, isEn)) : '—'}</small>
        </div>
      </div>
    </section>
    <div class="adventurer-watch-columns">
      <section class="panel"><h2>${isEn ? 'Activity Log' : '活動ログ'}</h2>${logList(adventurer, 'activity', lang)}</section>
      <section class="panel"><h2>${isEn ? 'Adventure Decisions' : '冒険の判断'}</h2>${logList(adventurer, 'decision', lang)}</section>
    </div>`;
}
