import { RECRUITMENT_TARGETS } from '../game/recruitment.ts';
import { baseFor, turnLabel } from '../game/selectors.ts';
import { localizedDungeonName } from '../game/i18n.ts';
import type { Language } from '../game/i18n.ts';
import type { GameState } from '../game/model.ts';
import type { UIState } from './model.ts';
import { badge, btn, esc, field, section } from './helpers.ts';

export function recruitmentPanel(s: GameState, ui?: UIState): string {
  const pending = s.recruitment.pending;
  const result = s.recruitment.lastResult;
  const dungeons = s.dungeons.filter(d => d.owned && d.phase === 'operating' && d.bossState === 'alive' && baseFor(s, d.id));
  const ready = ['complete', 'skipped'].includes(s.onboarding.status) && (s.onboarding.firstReturnStep ?? 0) !== 1 && (s.onboarding.firstReturnStep ?? 0) !== 2;
  const destination = pending?.dungeonId ?? result?.dungeonId ?? dungeons[0]?.id;
  const target = pending?.target ?? result?.target ?? 'beginner';
  const lang: Language = ui?.lang || s.lang || 'ja';
  const isEn = lang === 'en';
  const options = dungeons.map(d => `<option value="${esc(d.id)}" ${d.id === destination ? 'selected' : ''}>${esc(localizedDungeonName(d.name, lang))}</option>`).join('');
  const targetLabels: Record<string, string> = isEn
    ? { beginner: 'Novice Adventurers', mid: 'Mid-tier Adventurers', veteran: 'Veteran Adventurers' }
    : { beginner: '初級冒険者', mid: '中堅冒険者', veteran: '熟練冒険者' };
  const form = `<form id="recruitment-form" class="recruitment-form">
    ${field(isEn ? 'Destination Dungeon' : '送り先のダンジョン', `<select name="dungeon" required ${pending || !dungeons.length ? 'disabled' : ''}>${options || `<option value="">${isEn ? 'No eligible dungeons' : '対象なし'}</option>`}</select>`)}
    ${field(isEn ? 'Target Adventurers' : 'ターゲットの冒険者', `<select name="target" ${pending ? 'disabled' : ''}>${Object.entries(RECRUITMENT_TARGETS).map(([key, value]) => `<option value="${key}" ${key === target ? 'selected' : ''}>${targetLabels[key] || value.label}（${isEn ? `Ranks ${value.ranks.join('/')}` : `${value.ranks.join('/')}ランク`}）</option>`).join('')}</select>`)}
    <button class="btn primary" type="submit" ${pending || !ready || !dungeons.length ? 'disabled' : ''}>${isEn ? 'Recruit 1 party (Free)' : '無料で1組を勧誘する'}</button>
  </form>`;
  const status = pending
    ? `<div class="notice" role="status">${badge(isEn ? 'Recruiting' : '勧誘中', 'gold')} ${isEn ? `Results in <strong>${Math.max(0, pending.resolvesAt - s.turn)} turns</strong> · Ready at ${turnLabel(pending.resolvesAt)}` : `結果まであと <strong>${Math.max(0, pending.resolvesAt - s.turn)}ターン</strong> · ${turnLabel(pending.resolvesAt)}に結果`}</div>`
    : '';
  const lastResult = result
    ? `<div class="recruitment-result" aria-label="${isEn ? 'Recent recruitment result' : '直近の勧誘結果'}"><strong>${turnLabel(result.completedAt)} · ${isEn ? 'Recruitment Result' : '勧誘結果'}</strong><p>${esc(result.message)}</p>${result.partyId && s.parties.some(p => p.id === result.partyId) ? btn(isEn ? 'Adventurer Party Details' : '冒険者PTの詳細', 'party', { id: result.partyId, dungeon: result.dungeonId }, 'text-btn') : ''}</div>`
    : '';
  const sectionTitle = isEn ? 'Recruitment (Free)' : '勧誘（無料）';
  const desc = isEn
    ? 'When recruitment succeeds, the target party becomes aware of the dungeon, raising awareness rate. This slightly encourages them to visit, though visits are not guaranteed. Resolves in 3 turns plus travel time. Only 1 recruitment at a time.'
    : '勧誘に成功すると、対象PTがダンジョンを認知して認知PT率が上がります。通常の目的地選びで訪問を少し後押ししますが、来訪は確約されません。結果は3ターン後で、移動時間は別にかかります。同時に行える勧誘は1件です。';
  const notReadyMsg = isEn ? 'Available once initial business guidance is completed.' : '最初の営業案内を終えると利用できます。';
  const noDungeonMsg = isEn ? 'Requires an operating, undefeated player dungeon.' : '営業中で未討伐の自社ダンジョンが必要です。';
  return section(sectionTitle, `<p class="subtle">${desc}</p>${!ready ? `<p class="notice">${notReadyMsg}</p>` : ''}${!dungeons.length ? `<p class="notice">${noDungeonMsg}</p>` : ''}${form}${status}${lastResult}`);
}
