import { esc } from './helpers.ts';
import { isTaxExempt, warnings } from '../game/selectors.ts';
import { ONBOARDING_FACILITIES } from '../game/config.ts';
import { t, heroPortrait, protagonistMerchantName, protagonistMerchantTitle } from '../game/i18n.ts';
import type { GameState } from '../game/model.ts';
import type { UIState } from './model.ts';

export function getDialogueQuote(s: GameState, ui: UIState): string {
  const lang = ui?.lang || s?.lang || 'ja';

  if (s.demonCoreFirstClearChoiceDungeonId) return t('quote_first_demon_core', lang);

  // 1. 重大イベント中
  if (s.campaign) {
    return t('quote_campaign', lang);
  }

  if (ui?.dialogueNotice === 'quote_first_stockout') return t('quote_first_stockout', lang);

  if (s.onboarding?.firstReturnStep === 1 && s.onboarding.firstReturnReport) {
    const rep = s.onboarding.firstReturnReport;
    const revStr = `${rep.revenue.toLocaleString()} G`;
    const profSign = rep.profit >= 0 ? '+' : '';
    const profStr = `${profSign}${rep.profit.toLocaleString()} G`;
    const matStr = rep.materials > 0 ? (lang === 'en' ? `, Materials: ${rep.materials}` : `、素材: ${rep.materials}個`) : '';
    return lang === 'en'
      ? `The adventurers have headed home. Here is our sales breakdown: (Revenue: ${revStr} / Profit: ${profStr}${matStr})`
      : `冒険者が帰って行ったぞ。売り上げはこんな感じだ。（売上: ${revStr} / 収支: ${profStr}${matStr}）`;
  }

  if (s.onboarding?.firstReturnStep === 2) {
    return lang === 'en'
      ? 'More adventurers may visit as our dungeon grows famous.'
      : 'こんな感じで、うちの迷宮が有名になってくれれば、どんどん冒険者が来るっていう算段さ';
  }

  if (s.onboarding?.firstReturnStep === 3) return t('quote_onboarding_recruitment', lang);

  if (ui?.dialogueNotice) return t(ui.dialogueNotice, lang);

  if (s.onboarding?.status === 'story' && s.onboarding.scene === 1) return t('quote_onboarding_discovery', lang);

  if (s.onboarding?.status === 'investments') {
    const base = s.bases.find(b => b.dungeonId === s.onboarding.targetDungeonId && !b.abandoned);
    const next = ONBOARDING_FACILITIES.find(key => !((base?.facilities[key] ?? 0) > 0));
    if (next) return t(`quote_onboarding_${next}`, lang);
  }
  if (s.onboarding?.status === 'awaiting-arrival') return t('quote_onboarding_start', lang);
  if (s.onboarding?.status === 'awaiting-return') return t('quote_onboarding_awaiting_return', lang);

  // 2. 警告に基づく優先セリフ
  const warnList = warnings(s).filter(w => w.severity === 'warning');
  if (warnList.length > 0) {
    if (s.hq.debtOverdue && s.hq.debt > 0) return t('quote_debt_overdue', lang);
    if (warnList.some(w => w.text.includes('借入金'))) return t('quote_debt_warn', lang);
    if (warnList.some(w => w.text.includes('現金不足'))) return t('quote_cash_warn', lang);
    if (warnList.some(w => w.text.includes('欠品'))) return t('quote_stock_warn', lang);
    if (warnList.some(w => w.text.includes('納税'))) return t('quote_tax_warn', lang);
    if (warnList.some(w => w.text.includes('山賊'))) return t('quote_bandit_warn', lang);
  }

  // 3. 画面別のセリフ
  if (ui.view === 'tax' && isTaxExempt(s)) return t('quote_view_tax_exempt', lang);
  const viewKey = `quote_view_${ui.view}`;
  return t(viewKey, lang);
}

export function dialogueWindow(s: GameState, ui: UIState): string {
  const lang = ui?.lang || s?.lang || 'ja';
  const quote = getDialogueQuote(s, ui);
  const hasPendingCoreChoice = Boolean(s.demonCoreFirstClearChoiceDungeonId);
  const isMinimized = Boolean(ui.dialogueMinimized) && !hasPendingCoreChoice;
  const portrait = heroPortrait(s);
  const merchantName = protagonistMerchantName(s, lang);
  const merchantTitle = protagonistMerchantTitle(s, lang);

  let actionBtn = '';
  if (hasPendingCoreChoice) {
    const dungeonId = s.demonCoreFirstClearChoiceDungeonId!;
    actionBtn = `<button class="btn primary dialogue-step-btn" data-action="game-action" data-kind="firstClearDemonCore" data-id="${dungeonId}" data-option="use" style="white-space: nowrap; flex-shrink: 0; padding: 4px 14px; font-size: 0.82rem;">${lang === 'en' ? 'Revive boss (1 Core)' : 'ボスを復活（コア1個）'}</button><button class="btn dialogue-step-btn" data-action="game-action" data-kind="firstClearDemonCore" data-id="${dungeonId}" data-option="keep" style="white-space: nowrap; flex-shrink: 0; padding: 4px 14px; font-size: 0.82rem;">${lang === 'en' ? 'Keep the Core' : 'コアを保管'}</button>`;
  } else if (s.onboarding?.firstReturnStep === 1) {
    actionBtn = `<button class="btn primary dialogue-step-btn" data-action="dialogue-next" style="white-space: nowrap; flex-shrink: 0; padding: 4px 14px; font-size: 0.82rem;">${lang === 'en' ? 'Next ▶' : '次へ ▶'}</button>`;
  } else if (s.onboarding?.firstReturnStep === 2) {
    const targetDungeon = s.dungeons.find(d => d.id === s.onboarding?.targetDungeonId && d.owned) || s.dungeons.find(d => d.owned);
    const hasOffer = Boolean(targetDungeon && targetDungeon.offers.length > 0 && !targetDungeon.maps.includes(targetDungeon.offers[0].floor));
    const offer = hasOffer && targetDungeon ? targetDungeon.offers[0] : null;
    const buyBtn = offer && targetDungeon
      ? `<button class="btn primary dialogue-step-btn" data-action="onboarding-buy-map" data-id="${targetDungeon.id}" data-floor="${offer.floor}" style="white-space: nowrap; flex-shrink: 0; padding: 4px 14px; font-size: 0.82rem;">${lang === 'en' ? `Buy Map (${offer.price} G)` : `地図を買い取る（${offer.price} G）`}</button>`
      : '';
    actionBtn = `${buyBtn}<button class="btn primary dialogue-step-btn" data-action="dialogue-next" style="white-space: nowrap; flex-shrink: 0; padding: 4px 14px; font-size: 0.82rem;">${lang === 'en' ? 'Next ▶' : '次へ ▶'}</button>`;
  } else if (s.onboarding?.firstReturnStep === 3) {
    actionBtn = `<button class="btn primary dialogue-step-btn" data-action="onboarding-recruitment" style="white-space: nowrap; flex-shrink: 0; padding: 4px 14px; font-size: 0.82rem;">${lang === 'en' ? 'Open HQ recruitment →' : '本店の勧誘を見る →'}</button><button class="btn dialogue-step-btn" data-action="dialogue-finish" style="white-space: nowrap; flex-shrink: 0; padding: 4px 14px; font-size: 0.82rem;">${lang === 'en' ? 'Close' : '閉じる'}</button>`;
  }

  if (isMinimized) {
    return `
      <div class="dialogue-bar collapsed" data-action="toggle-dialogue" title="${lang === 'ja' ? '会話ウィンドウを展開' : 'Expand dialogue'}">
        <img class="dialogue-avatar-mini pixel-art" src="${portrait}" alt="${esc(merchantTitle)}">
        <div class="dialogue-mini-text">
          <span class="dialogue-speaker-mini">${esc(merchantName)}</span>
          <span class="dialogue-quote-mini">${esc(quote)}</span>
        </div>
        <button class="dialogue-toggle-btn" aria-label="${lang === 'ja' ? '展開' : 'Expand'}">▲</button>
      </div>
    `;
  }

  return `
    <section class="dialogue-window" aria-label="${esc(merchantName)}">
      <div class="dialogue-portrait-frame">
        <img class="dialogue-avatar pixel-art" src="${portrait}" alt="${esc(merchantTitle)}">
        <span class="dialogue-portrait-tag">${t('tag_master', lang)}</span>
      </div>
      <div class="dialogue-content">
        <div class="dialogue-header">
          <div class="dialogue-name">
            <strong>${esc(merchantName)}</strong>
            <small>${t('dialogue_subtitle', lang)}</small>
          </div>
          <div class="dialogue-actions">
            ${hasPendingCoreChoice ? '' : `<button class="dialogue-minimize-btn" data-action="toggle-dialogue" title="${lang === 'ja' ? '最小化' : 'Minimize'}" aria-label="最小化">${t('dialogue_minimize', lang)}</button>`}
          </div>
        </div>
        <div class="dialogue-body">
          <p class="dialogue-text">${esc(quote)}</p>
          ${actionBtn}
        </div>
      </div>
    </section>
  `;
}
