function adventurerPresence(count: number, location: '拠点' | 'ダンジョン', dungeonId?: string, isEn = false): string {
  if (count < 1) return '';
  const locLabel = isEn ? (location === 'ダンジョン' ? 'dungeon' : 'outpost') : location;
  const label = isEn ? `${count} parties at ${locLabel}` : `${location}に冒険者が${count}組います`;
  const navAttrs = location === 'ダンジョン' && dungeonId ? ` data-action="navigate" data-view="parties" data-id="${dungeonId}" style="cursor:pointer;" role="button" tabindex="0"` : ' role="img"';
  const pulseMarkup = location === 'ダンジョン' ? '<span class="presence-pulse-beacon" aria-hidden="true"><span class="beacon-wave"></span><span class="beacon-point"></span></span>' : '';
  return `<span class="badge gold adventurer-presence"${navAttrs} aria-label="${label}" title="${label}">${adventurerGlyph}<strong>${count}</strong>${pulseMarkup}</span>`;
}

