import type { AREAS, FACILITIES, GOODS, JOBS, RANKS } from './config.ts';
import type { WeeklyReport, WeeklyDataBuffer } from './weekly-report.ts';

export type GoodsKey = keyof typeof GOODS;
export type FacilityKey = keyof typeof FACILITIES;
export type Rank = (typeof RANKS)[number];
export type Job = (typeof JOBS)[number];
export type AreaId = (typeof AREAS)[number]['id'];

export type OnboardingStatus = 'story' | 'investments' | 'awaiting-arrival' | 'arrival' | 'awaiting-return' | 'complete' | 'skipped';
export type GameViewId = 'world' | 'region' | 'base' | 'dungeon' | 'parties' | 'maps' | 'hq' | 'logistics' | 'tax' | 'intel' | 'events' | 'adventurer-watch' | 'ogre-battle';
export type LogType = 'success' | 'rumor' | 'warning' | 'major' | 'market' | 'story';
export type DungeonPhase = 'rumor' | 'surveying' | 'discovered' | 'applying' | 'permitted' | 'road' | 'operating' | 'cleared' | 'abandoned';
export type PartyLocation = 'kingdom' | 'outskirts' | 'road' | 'base' | 'dungeon';
export type PartyAction = 'resting' | 'reforming' | 'traveling' | 'hunting' | 'visiting' | 'exploring' | 'returning' | 'homeward' | 'healing';
export type MemberStatus = 'healthy' | 'injured' | 'dead';
export type EventType = 'guild' | 'bandits' | 'trend' | 'shortage' | 'dragon' | 'festival' | 'sword' | 'raid' | 'wagon-ambush' | 'refugees' | 'ogre-raid' | 'survey-corps' | 'fairy-dream';
// Kingdom funds support public crises and guild directives, not market trends or individual wagon incidents.
export const canReceiveKingdomSupport = (type: EventType | string): boolean => ['guild', 'bandits', 'shortage', 'dragon', 'raid', 'ogre-raid'].includes(type as EventType);
export type PriceTargetKey = GoodsKey | 'inn' | 'tavern' | 'hospital';
export type CustomPrices = Record<PriceTargetKey, number>;
export interface TradeFeedbackEntry {
  turn: number;
  partyId: string;
  partyName: string;
  item: string;
  reason: string;
}

export type VisitorType = 'noble' | 'merchant';

export interface BaseVisitor {
  id: string;
  baseId: string;
  type: VisitorType;
  name: string;
  title: string;
  timer: number;
  spent: number;
  purchases: string[];
  note: string;
}

export type InvestmentKind = 'facility' | 'roadTile' | 'hq' | 'wagon' | 'wagonCapacity' | 'baseAd' | 'dungeonAd' | 'repair' | 'surveyLevel' | 'research';
export type GameAction = 'onboardingNext' | 'onboardingSkip' | 'onboardingFinish' | 'survey' | 'apply' | 'renameDungeon' | 'buildRoad' | 'buildRoadTile' | 'openBase' | 'mapBuy' | 'mapPolicy' | 'toggleMapFloor' | 'supplyPolicy' | 'repay' | 'borrow' | 'payArrears' | 'restock' | 'autoSupply' | 'contribute' | 'donateOrphanage' | 'nobleDinnerChoice' | 'refugeesChoice' | 'acknowledge' | 'assignWagon' | 'charterWagon' | 'setPrice' | 'research' | 'recruit' | 'buyDemonCore' | 'reviveDungeon' | 'firstClearDemonCore' | 'buyHolySword' | 'triggerSurveyCorps' | 'clickFairy' | 'triggerFairy' | 'demonCoreOfferChoice';

export interface ActionPayload {
  id?: string;
  name?: string;
  areaId?: string;
  cells?: number[];
  cell?: number;
  route?: string;
  location?: string;
  floor?: number;
  policy?: string;
  limit?: number;
  price?: number;
  cash?: number;
  target?: number;
  priority?: string;
  amount?: number;
  good?: string;
  option?: string;
  prices?: Partial<Record<PriceTargetKey, number>>;
  count?: number;
  enabled?: boolean;
  wagonId?: string;
  borrow?: boolean;
  recruitmentTarget?: string;
  targetType?: 'sell' | 'buy';
}

export type RecruitmentTarget = 'strong' | 'regular' | 'beginner';
export interface RecruitmentOrder {
  dungeonId: string;
  target: RecruitmentTarget;
  startedAt: number;
  resolvesAt: number;
}
export interface RecruitmentResult extends RecruitmentOrder {
  completedAt: number;
  partyId: string | null;
  partyName: string;
  outcome: 'departed' | 'contacted' | 'declined' | 'unavailable' | 'cancelled';
  learned: boolean;
  message: string;
}

export type AccountCategory = 'goods' | 'services' | 'maps' | 'materials' | 'highway' | 'upkeep' | 'spoilage' | 'raids' | 'advertising' | 'repair' | 'other';
export interface DailyAccounts {
  turn: number;
  revenue: Record<AccountCategory, number>;
  expenses: Record<AccountCategory, number>;
  goods: Record<GoodsKey, { count: number; revenue: number; cost: number }>;
  visitors: number;
  stockoutRate: number;
  complete: boolean;
}

export type ActionResult = { ok: true; message: string; baseId?: string } | { ok: false; message: string };
export type InvestmentQuoteFailure = {
  ok: false;
  message: string;
  cost?: number;
  title?: string;
  effect?: string;
  next?: number;
  kind?: InvestmentKind;
  id?: string;
  option?: string;
};
export type InvestmentQuoteSuccess = {
  ok: true;
  message: string;
  cost: number;
  title: string;
  effect: string;
  next: number;
  kind: InvestmentKind;
  id: string;
  option: string;
};
export type InvestmentQuote = InvestmentQuoteFailure | InvestmentQuoteSuccess;

