export type ArmorSlot = 'head' | 'body' | 'arms' | 'legs';
export type EquipmentSlot = 'weapon' | ArmorSlot;

export type EquipmentStat = 'maxHp' | 'mp' | 'attack' | 'defense' | 'magicAttack' | 'magicDefense' | 'speed';
export type EquipmentBonuses = Partial<Record<EquipmentStat, number>>;

export interface EquipmentItem {
  id: string;
  name: string;
  slot: EquipmentSlot;
  tier: number;
  effect: number;
  job?: Job;
  description?: string;
  /** Base values are stored unchanged; enhancement scales them when used. */
  enhancement?: number;
  bonuses?: EquipmentBonuses;
}

export interface UnitEquipment {
  weapon: EquipmentItem;
  head: EquipmentItem;
  body: EquipmentItem;
  arms: EquipmentItem;
  legs: EquipmentItem;
}

