interface DungeonSummaryCommon {
  id: string;
  name: string;
  areaId: AreaId;
  phase: DungeonPhase;
  phaseName: string;
  public: boolean;
}

export type DungeonSummary =
  | (DungeonSummaryCommon & { public: false; owned: false })
  | (DungeonSummaryCommon & { public: true; owned: false; difficulty: number; popularity: number; recognition: number; distance: number; bossState: Dungeon['bossState']; rumorProfit: number; rumorFloor: number; materialRumor: string })
  | (DungeonSummaryCommon & { public: true; owned: true; difficulty: number; popularity: number; recognition: number; distance: number; bossState: Dungeon['bossState']; knownFloor: number; active: number; averageProfit: number; visits: number; returns: number; materials: string[]; progressSpeed: number; baseId?: string; deaths: number; wipes: number });
export type OwnedDungeonSummary = Extract<DungeonSummary, { owned: true }>;

