export type ArmorCategory = 'heavy' | 'light' | 'cloth';

/**
 * 職業に応じた防具カテゴリ（重装・軽装・法衣）を判定する。
 * - 重装（Heavy）: 戦士、ナイト
 * - 軽装（Light）: シーフ、ローグ、狩人、アサシン
 * - 法衣（Cloth）: 魔法使い、僧侶
 */
export function getJobArmorCategory(job: Job): ArmorCategory {
  switch (job) {
    case '戦士':
    case 'ナイト':
      return 'heavy';
    case '魔法使い':
    case '僧侶':
      return 'cloth';
    case 'ローグ':
    case 'シーフ':
    case '狩人':
    case 'アサシン':
    default:
      return 'light';
  }
}

