export const ARMOR_SLOTS: readonly ArmorSlot[] = ['head', 'body', 'arms', 'legs'] as const;
export const ALL_EQUIPMENT_SLOTS: readonly EquipmentSlot[] = ['weapon', ...ARMOR_SLOTS] as const;

export const EQUIPMENT_STATS: readonly EquipmentStat[] = ['maxHp', 'mp', 'attack', 'defense', 'magicAttack', 'magicDefense', 'speed'];

/** A grade changes attack/defense by one per step and special bonuses by 10%. */
export function withEquipmentEnhancement(item: EquipmentItem, enhancement: number): EquipmentItem {
  const grade = item.id === CLOTH_CLOTHES.id || item.id === HOLY_SWORD.id
    ? 0 : Math.max(-3, Math.min(3, Math.trunc(Number.isFinite(enhancement) ? enhancement : 0)));
  const baseName = item.name.replace(/ [＋−][1-3]$/u, '');
  return {
    ...item,
    name: `${baseName}${grade === 0 ? '' : ` ${grade > 0 ? '＋' : '−'}${Math.abs(grade)}`}`,
    enhancement: grade,
    ...(item.bonuses ? { bonuses: { ...item.bonuses } } : {}),
  };
}

export function getEquipmentEffect(item: EquipmentItem): number {
  return Math.max(1, item.effect + (item.enhancement ?? 0));
}

export function getEquipmentBonuses(item: EquipmentItem): EquipmentBonuses {
  const multiplier = 1 + (item.enhancement ?? 0) * 0.1;
  return Object.fromEntries(Object.entries(item.bonuses ?? {}).map(([stat, value]) => [stat, Math.round(value * multiplier)]));
}

/** Keep level-growth stats intact, deriving equipped bonuses on every read. */
export function getMemberEquipmentBonuses(member: Member): Record<EquipmentStat, number> {
  const result = { maxHp: 0, mp: 0, attack: 0, defense: 0, magicAttack: 0, magicDefense: 0, speed: 0 };
  for (const slot of ALL_EQUIPMENT_SLOTS) {
    const item = member.gear?.[slot];
    if (!item) continue;
    const bonuses = getEquipmentBonuses(item);
    for (const stat of EQUIPMENT_STATS) result[stat] += bonuses[stat] ?? 0;
  }
  return result;
}

export function getEquippedMemberStats(member: Member): Record<EquipmentStat, number> {
  const stats = getMemberEquipmentBonuses(member);
  for (const stat of EQUIPMENT_STATS) stats[stat] += member[stat];
  stats.mp = getMemberCurrentMp(member);
  return stats;
}

export function getMemberMaxMp(member: Member): number {
  return Math.max(0, member.mp + getMemberEquipmentBonuses(member).mp);
}

export function getMemberCurrentMp(member: Member): number {
  const maxMp = getMemberMaxMp(member);
  const spent = Math.min(maxMp, Math.max(0, Math.round(member.mpSpent ?? 0)));
  return maxMp - spent;
}

export function spendMemberMp(member: Member, amount: number): boolean {
  const cost = Math.max(0, Math.ceil(amount));
  const currentMp = getMemberCurrentMp(member);
  if (currentMp < cost) return false;
  member.mpSpent = Math.min(getMemberMaxMp(member), Math.max(0, member.mpSpent ?? 0) + cost);
  return true;
}

export function restoreMemberMp(member: Member, amount: number): number {
  const maxMp = getMemberMaxMp(member);
  const currentMp = getMemberCurrentMp(member);
  const restored = Math.max(0, Math.floor(amount));
  const nextMp = Math.min(maxMp, currentMp + restored);
  member.mpSpent = maxMp - nextMp;
  return nextMp - currentMp;
}

export function getMemberMaxHp(member: Member): number {
  return member.maxHp + getMemberEquipmentBonuses(member).maxHp;
}

export function equipMemberItem(member: Member, item: EquipmentItem): void {
  const previousMax = getMemberMaxHp(member);
  member.gear[item.slot] = withEquipmentEnhancement(item, item.enhancement ?? 0);
  const nextMax = getMemberMaxHp(member);
  member.mpSpent = Math.min(getMemberMaxMp(member), Math.max(0, member.mpSpent ?? 0));
  // Preserve missing HP, and never revive a dead or zero-HP member by equipping.
  member.hp = member.status === 'dead' || member.hp <= 0 ? 0
    : Math.max(1, Math.min(nextMax, member.hp + nextMax - previousMax));
}

export function getEquipmentChoices(job: Job, slot: EquipmentSlot, tier: number): EquipmentItem[] {
  const base = slot === 'weapon' ? getWeaponForJob(job, tier) : getArmorForJobAndSlot(job, slot, tier);
  return [base, ...JOB_EQUIPMENT_VARIANTS[job].filter(item =>
    item.slot === slot && item.tier === base.tier,
  )].map(item => withEquipmentEnhancement(item, 0));
}

function equipmentRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

export function rollEquipment(job: Job, slot: EquipmentSlot, tier: number, random: () => number): EquipmentItem {
  const choices = getEquipmentChoices(job, slot, tier);
  const item = choices[Math.min(choices.length - 1, Math.floor(random() * choices.length))];
  return withEquipmentEnhancement(item, Math.floor(random() * 7) - 3);
}

export function equipmentEffectText(item: EquipmentItem, isEn = false): string {
  const labels: Record<EquipmentStat, string> = isEn
    ? { maxHp: 'Max HP', mp: 'MP', attack: 'Attack', defense: 'Defense', magicAttack: 'Magic Attack', magicDefense: 'Magic Defense', speed: 'Speed' }
    : { maxHp: '最大HP', mp: 'MP', attack: '攻撃', defense: '防御', magicAttack: '魔攻', magicDefense: '魔防', speed: '素早さ' };
  const primary = item.slot === 'weapon' ? (isEn ? 'Weapon power' : '武器威力') : (isEn ? 'Armor' : '防具防御');
  return [`${primary} +${getEquipmentEffect(item)}`, ...Object.entries(getEquipmentBonuses(item))
    .filter(([, value]) => value !== 0).map(([stat, value]) => `${labels[stat as EquipmentStat]} +${value}`)].join(' / ');
}

export function getClothClothes(): EquipmentItem {
  return { ...CLOTH_CLOTHES };
}

export function getWeaponForJob(job: Job, tier = 1): EquipmentItem {
  const weapons = JOB_WEAPONS[job] || JOB_WEAPONS['戦士'];
  const exact = weapons.find(w => Math.abs(w.tier - tier) < 0.01);
  if (exact) return { ...exact };
  let best = weapons[0];
  let bestDiff = Math.abs(best.tier - tier);
  for (const w of weapons) {
    const diff = Math.abs(w.tier - tier);
    if (diff < bestDiff) {
      best = w;
      bestDiff = diff;
    }
  }
  return { ...best };
}

export function getArmorForSlot(slot: ArmorSlot, tier = 1, job?: Job): EquipmentItem {
  const category = job ? getJobArmorCategory(job) : 'heavy';
  const armors = CATEGORY_ARMORS[category][slot];
  const exact = armors.find(a => Math.abs(a.tier - tier) < 0.01);
  if (exact) return { ...exact };
  let best = armors[0];
  let bestDiff = Math.abs(best.tier - tier);
  for (const a of armors) {
    const diff = Math.abs(a.tier - tier);
    if (diff < bestDiff) {
      best = a;
      bestDiff = diff;
    }
  }
  return { ...best };
}

export function getArmorForJobAndSlot(job: Job, slot: ArmorSlot, tier = 1): EquipmentItem {
  return getArmorForSlot(slot, tier, job);
}

/**
 * 部位ごとの自然なティアばらつきパターン（合計オフセット0で平均ティアを維持）
 * 0.5オフセットにより、Tier 2.5やTier 4.5といった選択肢・特化装備が自然に生成される。
 * 順序: [weapon, head, body, arms, legs]
 */
const VARIATION_PATTERNS: readonly (readonly [number, number, number, number, number])[] = [
  [0, 1, 0, -1, 0],         // Head +, Arms -
  [0.5, 0, -0.5, 0, 0],     // Weapon +0.5 (T2.5/T4.5 選択肢), Body -0.5
  [0, -0.5, 0.5, 0, 0],     // Body +0.5 (T2.5/T4.5 選択肢), Head -0.5
  [1, 0, -1, 0, 0],         // Weapon +, Body -
  [0, 0.5, 0, -0.5, 0],     // Head +0.5 (T2.5/T4.5 選択肢), Arms -0.5
  [-0.5, 0, 0, 0.5, 0],     // Arms +0.5 (T2.5/T4.5 選択肢), Weapon -0.5
  [0, 0, -1, 0, 1],         // Legs +, Body -
  [0, 0, 0.5, 0, -0.5],     // Body +0.5, Legs -0.5
  [-1, 1, 0, 0, 0],         // Head +, Weapon -
  [0, 0, 0, 0.5, -0.5],     // Arms +0.5, Legs -0.5
  [0, -1, 0, 0, 1],         // Legs +, Head -
  [0.5, -0.5, 0, 0, 0],     // Weapon +0.5, Head -0.5
];

/**
 * ユニット用の初期・規定装備一式を生成。
 * 職業に応じた防具カテゴリ（重装・軽装・法衣）を選択し、各スロットに自然なティア分散（Tier 2.5・4.5含む）を付与。
 * 体防具は最低でも「布の服」を保証する。
 */
export function createDefaultEquipment(job: Job, level = 1, tier?: number, seedOrId?: number): UnitEquipment {
  const calculatedTier = tier !== undefined ? tier : (1 + Math.floor(level / 15));
  const clampedTier = Math.max(1, Math.min(7, calculatedTier));

  const seed = seedOrId !== undefined
    ? Math.abs(Math.floor(seedOrId))
    : (job.charCodeAt(0) * 17 + level * 31 + Math.floor(clampedTier) * 7);

  const offsets = clampedTier > 1
    ? VARIATION_PATTERNS[seed % VARIATION_PATTERNS.length]
    : [0, 0, 0, 0, 0];

  const wTier = Math.max(1, Math.min(7, clampedTier + offsets[0]));
  const hTier = Math.max(1, Math.min(7, clampedTier + offsets[1]));
  const bTier = Math.max(1, Math.min(7, clampedTier + offsets[2]));
  const aTier = Math.max(1, Math.min(7, clampedTier + offsets[3]));
  const lTier = Math.max(1, Math.min(7, clampedTier + offsets[4]));
  const random = equipmentRandom(seed * 7919 + Math.round(clampedTier * 100));

  return {
    weapon: rollEquipment(job, 'weapon', wTier, random),
    head: rollEquipment(job, 'head', hTier, random),
    body: bTier <= 1 ? getClothClothes() : rollEquipment(job, 'body', bTier, random),
    arms: rollEquipment(job, 'arms', aTier, random),
    legs: rollEquipment(job, 'legs', lTier, random),
  };
}

/**
 * 最低装備の保証チェック。
 * - 全部位の存在を保証
 * - 体防具は「布の服（効果1）」以上を必ず保証（下回る、または欠損時は布の服を装備）
 * - 各スロットはユニットの職業カテゴリに適した装備を補完
 */
export function ensureMinimumEquipment(m: Member): void {
  if (!m.gear || typeof m.gear !== 'object') {
    const tier = Math.max(1, Math.min(7, Math.floor(m.equipment || 1)));
    m.gear = createDefaultEquipment(m.job, m.level, tier, m.id ?? m.growthSeed);
  }
  // 体防具の最低保証: 布の服（効果1）を下回らない
  if (!m.gear.body || m.gear.body.slot !== 'body' || m.gear.body.effect < 1) {
    m.gear.body = getClothClothes();
  }
  if (!m.gear.weapon || m.gear.weapon.slot !== 'weapon') {
    m.gear.weapon = getWeaponForJob(m.job, Math.max(1, m.gear.weapon?.tier || 1));
  }
  if (!m.gear.head || m.gear.head.slot !== 'head') {
    m.gear.head = getArmorForJobAndSlot(m.job, 'head', Math.max(1, m.gear.head?.tier || 1));
  }
  if (!m.gear.arms || m.gear.arms.slot !== 'arms') {
    m.gear.arms = getArmorForJobAndSlot(m.job, 'arms', Math.max(1, m.gear.arms?.tier || 1));
  }
  if (!m.gear.legs || m.gear.legs.slot !== 'legs') {
    m.gear.legs = getArmorForJobAndSlot(m.job, 'legs', Math.max(1, m.gear.legs?.tier || 1));
  }
}

/**
 * 装備枠のアップグレード。
 * 宝箱からのドロップや鍛冶屋での購入時にユニットが装備を更新する。
 * ユニットの職業に適合した装備が選定される。
 */
export function upgradeMemberEquipment(
  m: Member,
  gain = 1,
  preferredSlot?: EquipmentSlot,
  targetTier?: number,
  random?: () => number,
): EquipmentItem {
  ensureMinimumEquipment(m);
  const slots: EquipmentSlot[] = preferredSlot
    ? [preferredSlot]
    : ['weapon', 'body', 'head', 'arms', 'legs'];

  // 最もtierが低い枠を優先してアップグレード（同率ならpreferredSlotまたは先頭）
  let targetSlot = slots[0];
  let minTier = 999;
  for (const slot of slots) {
    const item = m.gear[slot as keyof UnitEquipment];
    const itemTier = item ? item.tier : 1;
    if (itemTier < minTier) {
      minTier = itemTier;
      targetSlot = slot;
    }
  }

  const currentItem = m.gear[targetSlot as keyof UnitEquipment];
  const curTier = currentItem?.tier || 1;
  const newTier = targetTier !== undefined
    ? Math.max(1, Math.min(7, targetTier))
    : Math.min(7, curTier + Math.max(0.5, gain));

  const newItem = rollEquipment(m.job, targetSlot, newTier, random ?? equipmentRandom(m.id * 7919 + Math.round(newTier * 100)));

  equipMemberItem(m, newItem);

  // 全体装備レベルの同期
  const averageTier = Math.round(
    (m.gear.weapon.tier + m.gear.head.tier + m.gear.body.tier + m.gear.arms.tier + m.gear.legs.tier) / 5
  );
  m.equipment = Math.max(m.equipment, averageTier);

  return newItem;
}

/**
 * 死亡時などの装備喪失・劣化処理。
 * 【重要】最低装備として「布の服」は保証され、体防具が布の服未満に下がることは絶対にない。
 */
export function degradeMemberEquipment(m: Member): { lostItemName: string | null } {
  ensureMinimumEquipment(m);

  // 劣化可能なスロット（tier > 1）を探索
  // 体防具はtier 1（布の服）になったら絶対に劣化・消失させない
  const degradableSlots: EquipmentSlot[] = (['weapon', 'head', 'arms', 'legs', 'body'] as const).filter(slot => {
    const item = m.gear[slot as keyof UnitEquipment];
    return item && item.tier > 1;
  });

  if (degradableSlots.length > 0) {
    // 最も高いtierのスロットを1段階劣化
    const sorted = [...degradableSlots].sort((a, b) => {
      const tierA = m.gear[a as keyof UnitEquipment]?.tier || 1;
      const tierB = m.gear[b as keyof UnitEquipment]?.tier || 1;
      return tierB - tierA;
    });
    const targetSlot = sorted[0];
    const prevItem = m.gear[targetSlot as keyof UnitEquipment];
    const prevTier = prevItem?.tier || 2;
    // 0.5刻みの場合は0.5減衰、整数の場合は1減衰
    const step = prevTier === 2.5 || prevTier === 4.5 ? 0.5 : 1;
    const newTier = Math.max(1, prevTier - step);

    const newItem = targetSlot === 'weapon'
      ? getWeaponForJob(m.job, newTier)
      : (targetSlot === 'body' && newTier <= 1
          ? getClothClothes()
          : getArmorForJobAndSlot(m.job, targetSlot as ArmorSlot, newTier));

    equipMemberItem(m, newItem);

    // 体防具がtier 1以下になった場合は必ず「布の服」を再保証
    if (targetSlot === 'body' && newTier <= 1) {
      equipMemberItem(m, getClothClothes());
    }

    const averageTier = Math.max(1, Math.round(
      (m.gear.weapon.tier + m.gear.head.tier + m.gear.body.tier + m.gear.arms.tier + m.gear.legs.tier) / 5
    ));
    m.equipment = averageTier;

    return { lostItemName: prevItem.name };
  }

  // 全スロットがtier 1（最低装備状態）の場合、体防具は布の服のまま保証
  equipMemberItem(m, getClothClothes());
  m.equipment = 1;
  return { lostItemName: null };
}

/**
 * ユニットの防具（足・体・腕・頭）による総防御効果。
 * 布の服の効果（+1）が最低保証として含まれる。
 */
export function getUnitArmorEffect(m: Member): number {
  ensureMinimumEquipment(m);
  return (
    getEquipmentEffect(m.gear.head) +
    getEquipmentEffect(m.gear.body) +
    getEquipmentEffect(m.gear.arms) +
    getEquipmentEffect(m.gear.legs)
  );
}

/**
 * ユニットの武器効果（職業別）。
 */
export function getUnitWeaponEffect(m: Member): number {
  ensureMinimumEquipment(m);
  return getEquipmentEffect(m.gear.weapon);
}
