import type { Language, ViewId } from './model.ts';
import type { Party } from '../game/model.ts';
import { difficultyLabel } from '../game/i18n.ts';
import { localizedAdventurerName, localizedPartyName } from '../game/names.ts';
import { getPartyCasualtySummary, partyDungeonDirection } from '../game/selectors.ts';

const HTML_ESCAPES: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export const esc = (value: unknown): string => String(value ?? '').replace(/[&<>"']/g, character => HTML_ESCAPES[character] ?? character);
export const partyDisplayName = (name: string, lang: Language = 'ja'): string => localizedPartyName(name.replace(/\s+\d+$/, ''), lang);
export const adventurerDisplayName = (name: string, lang: Language = 'ja'): string => localizedAdventurerName(name, lang);
export const money = (n: number): string => `${Math.round(n).toLocaleString('ja-JP')} <small>G</small>`;
export const moneyStep = (current: number, target: number): number => {
  const from = Math.round(Number(current) || 0), to = Math.round(Number(target) || 0);
  return from + Math.sign(to - from) * Math.min(100, Math.abs(to - from));
};
export const num = (n: number): string => Math.round(n).toLocaleString('ja-JP');
export const percent = (n: number): string => `${Math.round(n)}%`;
export const btn = (label: string, action: string, data: Record<string, string | number | boolean> = {}, cls = '', disabled = false, tooltip = ''): string => `<button class="btn ${cls}" data-action="${esc(action)}" ${tooltip ? `title="${esc(tooltip)}" ` : ''}${Object.entries(data).map(([k, v]) => `data-${k.replace(/([A-Z])/g, '-$1').toLowerCase()}="${esc(v)}"`).join(' ')} ${disabled ? 'disabled' : ''}>${label}</button>`;
export const nav = (label: string, view: ViewId, id?: string | null, cls = ''): string => btn(label, 'navigate', { view, ...(id ? { id } : {}) }, cls);
export const badge = (label: string, kind = ''): string => `<span class="badge ${kind}">${esc(label)}</span>`;
export const bar = (value: number, max = 100, cls = '', label = '進捗'): string => `<span class="meter ${cls}" role="meter" aria-valuenow="${Math.round(value)}" aria-valuemin="0" aria-valuemax="${Math.max(Math.round(max), Math.round(value))}" aria-label="${esc(label)}"><i style="width:${Math.max(0, Math.min(100, max ? value / max * 100 : 0))}%"></i></span>`;
export const countdownMeter = (remaining: number, max: number, label: string, cls = ''): string => {
  const safeMax = Math.max(1, Math.ceil(max));
  const safeRemaining = Math.max(0, Math.min(safeMax, remaining));
  return `<span class="countdown-meter ${cls}" role="meter" aria-valuenow="${Math.ceil(safeRemaining)}" aria-valuemin="0" aria-valuemax="${safeMax}" aria-label="${esc(label)}"><i class="countdown-meter-fill" data-remaining="${safeRemaining}" data-max="${safeMax}" style="width:${safeRemaining / safeMax * 100}%"></i></span>`;
};
export const stat = (label: string, value: string, detail = '', cls = '', tooltip = ''): string => `<div class="stat ${cls}"${tooltip ? ` title="${esc(tooltip)}" data-tooltip="${esc(tooltip)}"` : ''}><span class="label">${label}</span><strong>${value}</strong>${detail ? `<span class="subtle">${detail}</span>` : ''}</div>`;
export const empty = (text: string, action = ''): string => `<div class="empty"><span class="empty-mark">◇</span><p>${text}</p>${action}</div>`;
export const section = (title: string, content: string, extra = ''): string => `<section class="panel"><div class="panel-heading"><h2>${title}</h2>${extra}</div>${content}</section>`;
export const disclosure = (key: string, title: string, content: string, preview = ''): string => `<details class="panel disclosure" data-disclosure="${esc(key)}"><summary><span class="disclosure-heading"><strong>${esc(title)}</strong>${preview ? `<span class="disclosure-preview">${preview}</span>` : ''}</span><span class="disclosure-chevron" aria-hidden="true">⌄</span></summary><div class="disclosure-body">${content}</div></details>`;
export const profitClass = (n: number): string => n >= 0 ? 'positive' : 'negative';
export const investButton = (label: string, kind: string, id?: string | null, option?: string, cls = ''): string => btn(label, 'quote', { kind, id: id || '', option: option || '' }, cls);
export const difficulty = (n: number, lang: Language = 'ja'): string => difficultyLabel(n, lang);
export const field = (label: string, content: string): string => `<label class="field"><span>${label}</span>${content}</label>`;

export const partyDirectionBadge = (p: Party, lang: Language = 'ja'): string => {
  const dir = partyDungeonDirection(p);
  if (!dir) return '';
  const isEn = lang === 'en';
  const label = isEn ? (dir === 'ascending' ? 'Ascending' : 'Descending') : (dir === 'ascending' ? '上昇中' : '下降中');
  const title = dir === 'ascending'
    ? (isEn ? 'Ascending towards entrance' : '地上・入口へ向けて上昇中')
    : (isEn ? 'Descending deeper' : '深層へ向けて下降中');
  return `<span class="party-dir-badge party-dir-${dir}" title="${title}"><i class="dir-arrow" aria-hidden="true">${dir === 'ascending' ? '▲' : '▼'}</i>${label}</span>`;
};

export const partyCasualtyBadges = (p: Party, lang: Language = 'ja'): string => {
  const cas = getPartyCasualtySummary(p);
  if (!cas.hasDead && !cas.hasInjured) return '';
  const isEn = lang === 'en';
  const badges: string[] = [];
  if (cas.dead > 0) {
    badges.push(`<span class="badge casualty-badge badge-dead" title="${isEn ? `${cas.dead} fallen` : `戦死 ${cas.dead}名`}"><i class="casualty-icon" aria-hidden="true">💀</i>${isEn ? `Fallen ${cas.dead}` : `戦死 ${cas.dead}`}</span>`);
  }
  if (cas.injured > 0) {
    badges.push(`<span class="badge casualty-badge badge-injured" title="${isEn ? `${cas.injured} injured` : `負傷 ${cas.injured}名`}"><i class="casualty-icon" aria-hidden="true">🩹</i>${isEn ? `Injured ${cas.injured}` : `負傷 ${cas.injured}`}</span>`);
  }
  return badges.join(' ');
};

