    if (!cells.length || cells.length > 8 || cells.some(c => !Number.isInteger(c) || c < 0 || c > 15)) return fail(isEn ? 'Please select 1 to 8 tiles.' : '1〜8区画を選んでください。');
    const cost = surveyCostForCells(cells.length);
    if (s.hq.cash < cost) return fail(isEn ? 'Not enough survey funds.' : '調査費が不足しています。');
