    log(s, isEn ? `Dispatched survey team to ${localizedAreaName(a.name, 'en')}.` : `${a.name}に調査隊を派遣しました。`, 'market', { view: 'region', id: a.id }); return ok(isEn ? 'Dispatched survey team. Results will arrive as time advances.' : '調査隊を派遣しました。時間を進めると結果が届きます。');
