interface SeedState { seed: number }
interface IdState extends SeedState { nextId: number; parties?: readonly Party[] }

export function random(state: SeedState): number {
  state.seed = (Math.imul(1664525, state.seed) + 1013904223) >>> 0;
  return state.seed / 4294967296;
}
export function pick<T>(s: SeedState, items: readonly [T, ...T[]]): T;
export function pick<T>(s: SeedState, items: readonly T[]): T | undefined;
export function pick<T>(s: SeedState, items: readonly T[]): T | undefined {
  return items[Math.floor(random(s) * items.length)];
}
export const clamp = (n: number, min: number, max: number): number => Math.min(max, Math.max(min, n));
export function log(state: Pick<GameState, 'nextId' | 'turn' | 'logs'>, text: string, type: LogType = 'market', target: LogTarget | null = null, broadcastOnce = false): void {
  state.logs.unshift({ id: state.nextId++, turn: state.turn, text, type, target, ...(broadcastOnce ? { broadcastOnce: true } : {}) });
  if (state.logs.length > 120) {
    let oldestRegularLog = state.logs.length - 1;
    while (oldestRegularLog >= 0 && state.logs[oldestRegularLog].broadcastOnce && !state.logs[oldestRegularLog].broadcasted) oldestRegularLog--;
    if (oldestRegularLog >= 0) state.logs.splice(oldestRegularLog, 1);
    else state.logs.length = 120;
  }
}

export function expireOldRumors(state: Pick<GameState, 'turn' | 'rumors'>): void {
  const retentionTurns = 14 * 5; // One in-game day is five turns.
  state.rumors = state.rumors.filter(rumor => state.turn - rumor.turn < retentionTurns);
}

export function makeMember(state: IdState, rank: Rank, i: number, jobOffset = 0, usedNames: ReadonlySet<string> = new Set()): Member {
  const level = 1 + RANKS.indexOf(rank) * 12 + Math.floor(random(state) * 7);
  const job: Job = RANKS.indexOf(rank) >= 4 ? JOBS[(i + jobOffset) % JOBS.length] : pick(state, JOBS);
  const id = state.nextId++;
  const growthSeed = memberGrowthSeed(state.seed, id);
  const equipTier = 1 + Math.floor(level / 15);
  const stats = memberStatsForLevel(job, level, growthSeed);
  const member: Member = {
    id,
    name: adventurerName(random(state), usedNames),
    rank,
    level,
    experience: 0,
    growthSeed,
    job,
    status: 'healthy',
    poisoned: false,
    hp: stats.maxHp,
    ...stats,
    mpSpent: 0,
    equipment: equipTier,
    gear: createDefaultEquipment(job, level, equipTier, id),
  };
  member.hp = getMemberMaxHp(member);
  return member;
}
export function makeParty(state: IdState, rank: Rank = 'E', members = 4 + Math.floor(random(state) * 3)): Party {
  const id = state.nextId++;
  const jobOffset = id % JOBS.length;
  const usedMemberNames = new Set<string>();
  const partyMembers = Array.from({ length: members }, (_, i) => {
    const member = makeMember(state, rank, i, jobOffset, usedMemberNames);
    usedMemberNames.add(member.name);
    return member;
  });
  const { spells, skills } = derivePartySpellsAndSkills(partyMembers);
  return {
    id: `p${id}`, name: partyName(random(state), random(state), new Set(state.parties?.map(party => party.name))),
    rank, members: partyMembers,
    location: 'kingdom', action: members < 4 ? 'reforming' : 'resting', timer: 1 + Math.floor(random(state) * 8),
    money: 300 + RANKS.indexOf(rank) * 600 + Math.floor(random(state) * 400), potions: 0, magicPotions: 0, antidotes: 0, motivation: 45 + random(state) * 40,
    food: 0, maxFood: 40, hp: 100, floor: 0, progress: 0, loot: 0, tripCost: 0, lastProfit: 0,
    stats: { combat: 12 + RANKS.indexOf(rank) * 15, endurance: 40, recovery: 10, exploration: 10, traps: 10 },
    spells, skills, knownFloors: {}, knownDungeons: [], dungeonImpressions: {}, maps: {}, currentDungeonId: null, lastDungeonId: null,
    pendingFloors: [], trips: 0, experience: 0, holySword: false, luckyMonsterVictories: [], encounter: null,
  };
}
const DUNGEON_MATERIALS: Record<string, string[]> = {
  d1: ['薬草', '魔石の欠片', '碧緑の苔'],
  d2: ['銀鉱石', '氷晶石', '墓守の古銀貨'],
  d3: ['黒曜石', '純魔石', '竜血の結晶'],
  d4: ['琥珀原石', '古代鉄', '黄金の砂'],
  d5: ['白樺の樹液', '軟銀鉱', '妖精の胞子'],
  d6: ['薬草', '魔石の欠片', '碧緑の苔'],
  d7: ['薬草', '魔石の欠片', '碧緑の苔'],
};

function defaultMaterialsForDifficulty(difficulty: number): string[] {
  if (difficulty <= 1) return ['薬草', '魔石の欠片', '碧緑の苔'];
  if (difficulty === 2) return ['白樺の樹液', '軟銀鉱', '妖精の胞子'];
  if (difficulty === 3) return ['銀鉱石', '古代鉄', '琥珀原石'];
  if (difficulty === 4) return ['氷晶石', '墓守の古銀貨', '黒曜石'];
  return ['黒曜石', '純魔石', '竜血の結晶'];
}

export function makeDungeon(id: string, areaId: GameState['areas'][number]['id'], name: string, difficulty: number, distance: number, floors: number, owned = false): Dungeon {
  const materialTable = DUNGEON_MATERIALS[id] || defaultMaterialsForDifficulty(difficulty);
  return { id, areaId, name, difficulty, distance, floors, owned, phase: owned ? 'operating' : 'operating', popularity: 0, recognition: 0,
    knownFloor: owned ? 1 : 0, rumorFloor: 2, bossState: 'alive', bossHp: getMonstersForDifficulty(difficulty).find(monster => monster.grade === 'boss')?.stats.hp ?? 0, bossClosureMessageShown: false, rumorProfit: 0.25, materialTable,
    monsterTable: getMonstersForDifficulty(difficulty).map(monster => monster.name), experienceCounts: {}, maps: [], mapDisabledSales: [], mapDisabledBuys: [], offers: [], mapPolicy: 'manual', mapLimit: 800,
    mapSales: 0, mapRevenue: 0, mapRanks: {}, visits: 0, returns: 0, totalProfit: 0, breakthroughs: [], trends: [{ turn: 0, popularity: 0, recognition: 0 }], survey: null, permitAt: null, roadId: null,
    advertisementUntil: 0, discoveredAt: 0, clearedAt: null, deaths: 0, wipes: 0 };
}
export function makeBase(id: string, dungeon: Dungeon, location: Base['location'] = 'highway', _hqLevel = 1, _trust = 0): Base {
  const base: Base = { id, dungeonId: dungeon.id, name: `${dungeon.name.replace(/の迷宮|の洞窟|遺跡|地下墓所/g, '')}前哨商館`, location,
    cash: 2600, inventory: { potion: 0, magicPotion: 0, antidote: 0, food: 0, weapon: 0, armor: 0 }, materials: 0, materialStock: {},
    facilities: Object.fromEntries(Object.keys(FACILITIES).map(key => [key, ONBOARDING_FACILITIES.includes(key as any) ? 1 : 0])) as Record<FacilityKey, number>,
    popularity: 20, defense: 6, roadConnection: dungeon.roadId,
    revenue: 0, profit: 0, todayRevenue: 0, todayProfit: 0, lastRevenue: 0, lastProfit: 0,
    visitors: 0, lastVisitors: 0, stockouts: 0, damage: 0, cashTarget: 2800, stockTarget: 0.75,
    priority: 'balanced', adUntil: 0, abandoned: false, investment: BALANCE.baseCost,
    metrics: Object.fromEntries(Object.keys(FACILITIES).map(k => [k, { users: 0, revenue: 0, lastUsers: 0, lastRevenue: 0 }])) as Base['metrics'],
    consumption: { potion: 0, magicPotion: 0, antidote: 0, food: 0, weapon: 0, armor: 0 }, lastConsumption: { potion: 0, magicPotion: 0, antidote: 0, food: 0, weapon: 0, armor: 0 }, lastStockoutRate: 0,
    customPrices: { potion: 0, magicPotion: 0, antidote: 0, food: 0, weapon: 0, armor: 0, inn: 0, tavern: 0, hospital: 0 },
    tradeFeedback: [],
    todayAccounts: emptyAccounts(), lastAccounts: emptyAccounts(), previousAccounts: null,
  };
  base.inventory = fullStockInventory(base);
  return base;
}
export function makeWagon(state: Pick<IdState, 'nextId'>, baseId: string): Wagon {
  return { id: `w${state.nextId++}`, baseId, location: 'kingdom', destination: 'base', cargo: { cash: 0, materials: 0, potion: 0, magicPotion: 0, antidote: 0, food: 0, weapon: 0, armor: 0, passengers: 0, bodies: [], materialBreakdown: {} }, capacity: BALANCE.wagonCapacity,
    eta: 1, totalEta: 1, status: 'loading', trips: 0, lost: 0, lastArrival: 0, chartered: false };
}
export function createState(seed = 20260912): GameState {
  const state: GameState = { version: VERSION, seed: seed >>> 0, initialSeed: seed >>> 0, merchantName: '', nextId: 1, turn: 0, lastExpressWagonDay: null,
    recruitment: { pending: null, lastResult: null },
    onboarding: { status: 'complete', scene: 0, targetDungeonId: 'd1', arrivalTurn: null, arrivalPartyId: null, firstReturnReport: null, firstReturnStep: 0 },
    hq: { level: 1, cash: 24000, demonCores: 1, inventory: { potion: 240, magicPotion: 80, antidote: 80, food: 500, weapon: 0, armor: 0 },
      research: { potion: 0, magicPotion: 0, antidote: 0, food: 0, weapon: 0, armor: 0 }, trust: 2,
      lastOrphanageDonationDay: null,
      debt: BALANCE.debtAmount, debtDue: BALANCE.debtDue, debtOverdue: false, materialsSold: 0, autoSupply: true },
    demonCoreFirstClearChoiceMade: false, demonCoreFirstClearChoiceDungeonId: null,
    finance: { periodProfit: 0, totalProfit: 0, taxDue: BALANCE.taxPeriod, paidTax: 0, taxArrears: 0, history: [], ledger: [] },
    areas: AREAS.map(a => ({ ...a, surveyed: [], surveyLevel: 1 })),
    dungeons: [makeDungeon('d1', 'e', '若葉の迷宮', 1, 3, 18, true), makeDungeon('d2', 'nw', '銀霜の地下墓所', 3, 9, 32), makeDungeon('d3', 'w', '黒曜の深淵', 5, 12, 45), makeDungeon('d4', 'se', '琥珀の遺跡', 3, 7, 28)],
    bases: [], roads: [{ id: 'r1', from: 'highway', to: 'd1', level: 1, danger: 8, cells: [5, 9, 13], cellLevels: [1, 1, 1] }], wagons: [], parties: [], sponsoredAdventurers: [], adventurerCreationPending: [], visitors: [],
    rumors: [], events: [], logs: [], prices: { potion: 1, magicPotion: 1, antidote: 1, food: 1, weapon: 1, armor: 1, material: 1 }, marketTrend: { food: 1, material: 1 }, pendingPartyTrades: [], firstStockoutAdviceShown: false,
    campaign: null, menuIntrosSeen: [], swordHolder: null, stats: { deaths: 0, recruits: 0, revivals: 0, extinctParties: 0 },
    weeklyReports: [], ogreRaid: null, fairy: null, demonCoreOffers: [],
  };
  state.dungeons[0].roadId = 'r1';
  state.dungeons[0].secretCell = 13;
  state.dungeons[0].popularity = 20;
  state.dungeons[1].popularity = 52; state.dungeons[1].recognition = 35; state.dungeons[1].rumorFloor = 7;
  state.dungeons[2].popularity = 27; state.dungeons[2].recognition = 35; state.dungeons[2].rumorProfit = -0.3;
  state.dungeons[3].popularity = 81; state.dungeons[3].recognition = 35; state.dungeons[3].rumorFloor = 11;
  state.bases.push(makeBase('b1', state.dungeons[0]));
  state.wagons.push(makeWagon(state, 'b1'));
  for (const [rank, count] of Object.entries({ S: 10, A: 50, B: 100, C: 200, D: 400, E: 240 }) as Array<[Rank, number]>) {
    for (let i = 0; i < count; i++) state.parties.push(makeParty(state, rank, rank === 'E' && i >= 200 ? 3 : rank === 'A' || rank === 'S' ? 6 : 4 + Math.floor(random(state) * 3)));
  }
  for (let i = 0; i < 14; i++) {
    const p = state.parties[500 + i]; p.currentDungeonId = 'd1'; p.lastDungeonId = 'd1'; p.location = 'base'; p.action = 'visiting'; p.timer = 1 + i % 3;
  }
  const hidden = makeDungeon('d5', 'ne', '白樺の洞窟', 2, 5, 24);
  hidden.phase = 'rumor'; hidden.secretCell = 6; hidden.owned = false;
  const windDungeon = makeDungeon('d6', 'sw', '風渡りの洞窟', 1, 4, 16);
  windDungeon.popularity = 36; windDungeon.recognition = 35; windDungeon.rumorFloor = 3;
  const riverDungeon = makeDungeon('d7', 's', '緑水の洞窟', 1, 4, 18);
  riverDungeon.popularity = 34; riverDungeon.recognition = 35; riverDungeon.rumorFloor = 2;
  state.dungeons.push(hidden, windDungeon, riverDungeon);
  seedAllDungeonAwarenessFromMetrics(state);
  for (const dungeon of state.dungeons) dungeon.trends = [{ turn: state.turn, popularity: dungeon.popularity, recognition: dungeon.recognition }];
  state.rumors.push({ id: 'rumor1', type: 'discovery', targetId: 'd5', areaId: 'ne', strength: 70, accuracy: '北東部・中程度', cells: [2, 3, 6, 7], turn: 0, text: '白樺の森の北東で、青い光と魔物の足跡が見つかった。' });
  log(state, '若葉の迷宮の営業権を取得。王国からの馬車が運行を開始しました。', 'success', { view: 'base', id: 'b1' });
  log(state, '白樺の森に新たなダンジョンの噂。調査隊を派遣できます。', 'rumor', { view: 'region', id: 'ne' });
  log(state, '創業特例として、開始10日は納税免除期間が適用されます。', 'market', { view: 'tax' });
  return state;
}

export function createOnboardingState(seed = 20260912): GameState {
  const state = createState(seed);
  state.onboarding = { status: 'story', scene: 0, targetDungeonId: 'd1', arrivalTurn: null, arrivalPartyId: null, firstReturnReport: null, firstReturnStep: 0 };
  state.hq.cash = 3000;

  const dungeon = state.dungeons[0];
  dungeon.name = '黎明の迷宮'; dungeon.distance = 1; dungeon.popularity = 20; dungeon.rumorProfit = 0.5;
  for (const rival of state.dungeons.slice(1)) rival.popularity = 0;
  const base = state.bases[0];
  base.name = '黎明の平原 B-3 国道商館'; base.location = 'highway';
  base.facilities = Object.fromEntries(Object.keys(FACILITIES).map(key => [key, 0])) as Record<FacilityKey, number>;
  base.inventory = { potion: 0, magicPotion: 0, antidote: 0, food: 0, weapon: 0, armor: 0 };
  base.popularity = 20; base.visitors = 0; base.lastVisitors = 0;
  state.wagons = state.wagons.slice(0, 1);

  const firstGuidedParty = state.parties.find(party => party.rank === 'E' && party.members.length >= 4);
  for (const [i, party] of state.parties.entries()) {
    party.currentDungeonId = null; party.lastDungeonId = null; party.location = 'kingdom';
    party.knownDungeons = []; party.dungeonImpressions = {};
    party.action = party.members.length < 4 ? 'reforming' : 'resting';
    party.timer = party.id === firstGuidedParty?.id ? 1 : 2 + i % 5;
  }
  if (firstGuidedParty) makePartyAware(state, firstGuidedParty, dungeon, 20);
  refreshAllDungeonMetrics(state);
  for (const item of state.dungeons) item.trends = [{ turn: state.turn, popularity: item.popularity, recognition: item.recognition }];
  state.logs = [];
  log(state, 'オオカミに追われた主人公が、黎明の平原 B-3 で迷宮を見つけました。', 'story');
  log(state, '迷宮の出口は国道へ続いています。その先には新たな商圏が広がっています。', 'story');
  log(state, '創業特例として、開始10日は納税免除期間が適用されます。', 'market', { view: 'tax' });
  return state;
}
