export function getSkillDef(name: string, fallbackKind: 'spell' | 'skill' = 'skill'): SkillDef {
  if (SKILL_CATALOG[name]) {
    return SKILL_CATALOG[name];
  }
  return {
    name,
    kind: fallbackKind,
    kindLabel: fallbackKind === 'spell' ? '魔法' : 'スキル',
    description: `「${name}」を駆使して迷宮探索や戦闘を有利に進める能力。`,
  };
}

export function getSpellMpCost(name: string): number {
  const spell = SKILL_CATALOG[name];
  return spell?.kind === 'spell' ? Math.max(0, spell.mpCost ?? 0) : 0;
}

export function getJobTraitDescription(job: string): string {
  return JOB_TRAIT_DESCRIPTIONS[job] || `冒険者パーティで専門技術を活かして活躍する。`;
}

