export function getMemberSpells(member: Member): string[] {
  if (member.status === 'dead') return [];
  const rules = JOB_SPELLS[member.job] || [];
  return rules
    .filter(rule => (rule.minLevel ?? 1) <= member.level)
    .map(rule => rule.spell);
}

export function getMemberSkills(member: Member): string[] {
  if (member.status === 'dead') return [];
  const rules = JOB_SKILLS[member.job] || [];
  return rules
    .filter(rule => (rule.minLevel ?? 1) <= member.level)
    .map(rule => rule.skill);
}

export function derivePartySpellsAndSkills(members: Member[]): { spells: string[]; skills: string[] } {
  const aliveMembers = members.filter(m => m.status !== 'dead');
  const spellSet = new Set<string>();
  const skillSet = new Set<string>();

  for (const member of aliveMembers) {
    for (const spell of getMemberSpells(member)) {
      spellSet.add(spell);
    }
    for (const skill of getMemberSkills(member)) {
      skillSet.add(skill);
    }
  }

  if (aliveMembers.length > 0) {
    skillSet.add('野営');
  }

  return {
    spells: Array.from(spellSet),
    skills: Array.from(skillSet),
  };
}

export function syncPartySkills(party: Party): void {
  const { spells, skills } = derivePartySpellsAndSkills(party.members);
  party.spells = spells;
  party.skills = skills;
}
