const SLOTS: readonly EquipmentSlot[] = ['weapon', 'head', 'body', 'arms', 'legs'];

/** Two additional, job-specific choices per slot: vitality and specialty. */
export const JOB_EQUIPMENT_VARIANTS = Object.fromEntries(
  Object.entries(OUTFITS).map(([job, outfit]) => [job, SLOTS.flatMap((slot, index): EquipmentItem[] => {
    const caster = job === '魔法使い' || job === '僧侶';
    return [
      {
        id: `special-${outfit.key}-${slot}-vitality`, name: outfit.vitality[index],
        job: job as Job, slot, tier: 3, effect: slot === 'weapon' ? 9 : slot === 'body' ? 5 : 6,
        bonuses: { maxHp: slot === 'body' ? 18 : slot === 'weapon' ? 10 : 8 },
        description: '生命の加護で最大HPを増やし、長い遠征を支える装備。',
      },
      {
        id: `special-${outfit.key}-${slot}-specialty`, name: outfit.specialty[index],
        job: job as Job, slot, tier: 5, effect: slot === 'weapon' ? 16 : slot === 'body' ? 10 : 11,
        bonuses: {
          [outfit.focus]: slot === 'weapon' ? 6 : 4,
          ...(caster ? { mp: slot === 'head' ? 12 : 6 } : { maxHp: slot === 'body' ? 12 : 4 }),
        },
        description: `${job}の技を引き出す特製装備。職業の得意能力を高める。`,
      },
    ];
  })]),
) as Record<Job, EquipmentItem[]>;
