import type { GameState, GoodsKey } from '../game/model.ts';
import type { Language } from './model.ts';
import { badge, btn, esc, money, num, stat } from './helpers.ts';
import type { WeeklyReport } from '../game/weekly-report.ts';

export type WeeklyReportTab = 'financial' | 'market' | 'adventurers' | 'kingdom';

export const WEEKLY_REPORT_TABS: Array<{ id: WeeklyReportTab; label: string; icon: string }> = [
  { id: 'financial', label: '売上・店舗実績', icon: '💰' },
  { id: 'market', label: '商品・価格・機会損失', icon: '📦' },
  { id: 'adventurers', label: '冒険者・評判・被害', icon: '⚔️' },
  { id: 'kingdom', label: '王国情勢・商店LVアップ', icon: '👑' },
];

export interface LineSeries {
  id: string;
  name: string;
  color: string;
  dashed?: boolean;
  values: number[];
  unit?: string;
  fillGradient?: boolean;
  valueFormatter?: (v: number) => string;
}

export interface SvgLineChartOptions {
  chartId: string;
  title?: string;
  subtitle?: string;
  width?: number;
  height?: number;
  xLabels: string[];
  yMin?: number;
  yMax?: number;
  yTicks?: number[];
  yUnit?: string;
  series: LineSeries[];
  showLegend?: boolean;
  legendHint?: string;
  zeroLine?: boolean;
}

export function renderSvgLineChart(opts: SvgLineChartOptions): string {
  const width = opts.width || 640;
  const height = opts.height || 190;
  const padLeft = 52;
  const padRight = 24;
  const padTop = 22;
  const padBottom = 26;
  const plotW = width - padLeft - padRight;
  const plotH = height - padTop - padBottom;

  const allValues = opts.series.flatMap(s => s.values.filter(v => typeof v === 'number' && !isNaN(v)));
  if (allValues.length === 0) {
    return `
      <div class="weekly-report-chart-card empty-chart" style="padding: 24px; text-align: center; background: #141e24; border: 1px solid #33464e; border-radius: 6px; margin-bottom: 16px;">
        <span class="subtle">十分な推移データがありません</span>
      </div>`;
  }

  let actualMin = opts.yMin !== undefined ? opts.yMin : Math.min(...allValues);
  let actualMax = opts.yMax !== undefined ? opts.yMax : Math.max(...allValues);

  if (opts.yMin === undefined) {
    if (actualMin >= 0) actualMin = 0;
    else actualMin = Math.floor(actualMin * 1.1);
  }

  if (opts.yMax === undefined) {
    if (actualMax <= actualMin) actualMax = actualMin + 10;
    else {
      const range = actualMax - actualMin;
      const mag = Math.pow(10, Math.floor(Math.log10(range || 1)));
      const step = Math.ceil(range / (mag * 4)) * mag;
      actualMax = actualMin + step * 4;
      if (actualMax <= Math.max(...allValues)) {
        actualMax = Math.ceil(Math.max(...allValues) * 1.15);
      }
    }
  }

  const range = actualMax - actualMin || 1;

  const ticks = opts.yTicks || [
    actualMin,
    actualMin + range * 0.25,
    actualMin + range * 0.5,
    actualMin + range * 0.75,
    actualMax,
  ];

  const xForIndex = (i: number, total: number) => {
    if (total <= 1) return padLeft + plotW / 2;
    return padLeft + (i / (total - 1)) * plotW;
  };

  const yForValue = (val: number) => {
    const clamped = Math.max(actualMin, Math.min(actualMax, val));
    return padTop + plotH - ((clamped - actualMin) / range) * plotH;
  };

  const gridLines = ticks.map(t => {
    const y = yForValue(t);
    const label = `${Math.round(t).toLocaleString()}${opts.yUnit ? ` ${opts.yUnit}` : ''}`;
    return `
      <line x1="${padLeft}" y1="${y.toFixed(1)}" x2="${(padLeft + plotW).toFixed(1)}" y2="${y.toFixed(1)}" stroke="#2a3c42" stroke-dasharray="2 3" stroke-width="1" />
      <text x="${padLeft - 6}" y="${(y + 3).toFixed(1)}" fill="#7e9696" font-size="9" text-anchor="end" font-family="monospace">${label}</text>
    `;
  }).join('');

  let zeroLine = '';
  if (actualMin < 0 && actualMax > 0) {
    const zy = yForValue(0);
    zeroLine = `<line x1="${padLeft}" y1="${zy.toFixed(1)}" x2="${(padLeft + plotW).toFixed(1)}" y2="${zy.toFixed(1)}" stroke="#5c777d" stroke-dasharray="3 2" stroke-width="1.2" />`;
  }

  const defs = opts.series.filter(s => s.fillGradient).map(s => `
    <linearGradient id="grad-${opts.chartId}-${s.id}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${s.color}" stop-opacity="0.32" />
      <stop offset="100%" stop-color="${s.color}" stop-opacity="0.0" />
    </linearGradient>
  `).join('');

  const seriesElements = opts.series.map(s => {
    const coords = s.values.map((v, i) => ({
      x: xForIndex(i, opts.xLabels.length),
      y: yForValue(v),
      val: v,
    }));

    let lineD = '';
    if (coords.length === 1) {
      lineD = `M ${padLeft} ${coords[0].y.toFixed(1)} L ${(padLeft + plotW).toFixed(1)} ${coords[0].y.toFixed(1)}`;
    } else {
      lineD = coords.map((c, i) => `${i === 0 ? 'M' : 'L'} ${c.x.toFixed(1)} ${c.y.toFixed(1)}`).join(' ');
    }

    const baselineY = yForValue(Math.max(0, actualMin));
    const areaD = (s.fillGradient && coords.length > 1)
      ? `${lineD} L ${coords[coords.length - 1].x.toFixed(1)} ${baselineY.toFixed(1)} L ${coords[0].x.toFixed(1)} ${baselineY.toFixed(1)} Z`
      : '';

    const dots = coords.map((c, i) => {
      const isLatest = i === coords.length - 1;
      const fmtVal = s.valueFormatter ? s.valueFormatter(c.val) : `${c.val.toLocaleString()}${s.unit || opts.yUnit || ''}`;
      return `
        <circle cx="${c.x.toFixed(1)}" cy="${c.y.toFixed(1)}" r="${isLatest ? 4.5 : 3}" fill="#162227" stroke="${s.color}" stroke-width="${isLatest ? 2.5 : 1.5}">
          <title>${esc(s.name)}: ${fmtVal} (${opts.xLabels[i] || `Day ${i + 1}`})</title>
        </circle>
        ${isLatest ? `<text x="${c.x.toFixed(1)}" y="${(c.y - 7).toFixed(1)}" fill="${s.color}" font-size="9.5" font-weight="bold" text-anchor="middle" font-family="monospace">${fmtVal}</text>` : ''}
      `;
    }).join('');

    return `
      ${areaD ? `<path d="${areaD}" fill="url(#grad-${opts.chartId}-${s.id})" />` : ''}
      <path d="${lineD}" fill="none" stroke="${s.color}" stroke-width="${s.dashed ? '2' : '2.5'}" ${s.dashed ? 'stroke-dasharray="4 2"' : ''} stroke-linejoin="round" stroke-linecap="round" />
      ${dots}
    `;
  }).join('');

  const xLabelsSvg = opts.xLabels.map((lbl, i) => {
    const x = xForIndex(i, opts.xLabels.length);
    return `<text x="${x.toFixed(1)}" y="${height - 7}" fill="#7e9696" font-size="9" text-anchor="middle" font-family="monospace">${esc(lbl)}</text>`;
  }).join('');

  const legendItems = opts.series.map(s => {
    const latestVal = s.values[s.values.length - 1] ?? 0;
    const firstVal = s.values[0] ?? latestVal;
    const diff = latestVal - firstVal;
    const diffText = diff > 0
      ? `<small style="color:#8bb889;font-weight:bold;">(+${Math.round(diff * 10) / 10})</small>`
      : diff < 0
        ? `<small style="color:#d9847d;font-weight:bold;">(${Math.round(diff * 10) / 10})</small>`
        : '<small class="subtle">(±0)</small>';

    const formattedVal = s.valueFormatter ? s.valueFormatter(latestVal) : `${latestVal.toLocaleString()}${s.unit || opts.yUnit || ''}`;

    return `
      <div class="weekly-report-chart-legend-item" style="display:flex;align-items:center;gap:6px;font-size:0.83rem;">
        <span style="display:inline-block;width:12px;height:${s.dashed ? '2px' : '4px'};background:${s.color};border-radius:2px;${s.dashed ? 'border-top:2px dashed ' + s.color : ''}"></span>
        <span class="subtle">${esc(s.name)}:</span>
        <strong style="color:${s.color};font-family:monospace;">${formattedVal}</strong>
        ${s.values.length > 1 ? diffText : ''}
      </div>
    `;
  }).join('');

  return `
    <div class="weekly-report-chart-card" style="background:#141e24;border:1px solid #33464e;border-radius:6px;padding:12px 14px 8px;margin-bottom:16px;">
      ${(opts.title || opts.showLegend !== false) ? `
        <div class="weekly-report-chart-top-bar" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid #28373d;">
          ${opts.title ? `<div><strong style="font-size:0.95rem;color:#e8f0ec;">${esc(opts.title)}</strong>${opts.subtitle ? `<span class="subtle" style="font-size:0.78rem;margin-left:8px;">${esc(opts.subtitle)}</span>` : ''}</div>` : '<div></div>'}
          <div class="weekly-report-chart-legend" style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;">
            ${legendItems}
          </div>
        </div>` : ''}
      <div class="weekly-report-chart-svg-wrap" style="width:100%;overflow-x:auto;">
        <svg class="weekly-report-svg-chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" style="width:100%;height:auto;max-height:220px;display:block;">
          <defs>${defs}</defs>
          ${gridLines}
          ${zeroLine}
          ${seriesElements}
          ${xLabelsSvg}
        </svg>
      </div>
      ${opts.legendHint ? `<p class="subtle" style="font-size:0.73rem;margin:6px 0 0;line-height:1.45;">${opts.legendHint}</p>` : ''}
    </div>
  `;
}

export function renderWeeklyReportModal(
  s: GameState,
  reportWeek?: number,
  currentTab: WeeklyReportTab = 'financial',
  lang: Language = 'ja',
  selectedGood?: GoodsKey,
): { title: string; body: string; footer: string } {
  const isEn = lang === 'en';
  const reports = s.weeklyReports || [];

  if (reports.length === 0) {
    return {
      title: isEn ? 'Weekly Summary Report' : '週間サマリーレポート',
      body: `
        <div class="empty" style="padding: 40px 20px; text-align: center;">
          <div style="font-size: 2.5rem; margin-bottom: 12px;">📋</div>
          <p style="font-size: 1.1rem; margin-bottom: 8px;"><strong>${isEn ? 'No weekly reports available yet.' : 'まだ週間レポートはありません。'}</strong></p>
          <p class="subtle">${isEn ? 'The first report is generated after 7 in-game days (35 turns).' : 'ゲーム開始から7日目（35ターン）経過時に、最初の週間レポートが自動生成されます。'}</p>
        </div>`,
      footer: btn(isEn ? 'Close' : '閉じる', 'close-modal'),
    };
  }

  // 選択された週、または最新週
  const selectedReport = (reportWeek !== undefined ? reports.find(r => r.week === reportWeek) : reports[0]) || reports[0];
  const prevWeekReport = reports.find(r => r.week === selectedReport.week - 1);
  const nextWeekReport = reports.find(r => r.week === selectedReport.week + 1);

  const title = isEn
    ? `Week ${selectedReport.week} Summary Report (Day ${selectedReport.startDay} - Day ${selectedReport.endDay})`
    : `第${selectedReport.week}週 週間経営レポート（${selectedReport.startDay}日目〜${selectedReport.endDay}日目）`;

  // 週セレクター＆タブバー
  const weekSelector = `
    <div class="weekly-report-nav-bar" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid #3d5053;">
      <div class="week-selector-group" style="display:flex;align-items:center;gap:8px;">
        <span class="subtle" style="font-size:0.85rem;">${isEn ? 'Report Week:' : '対象週:'}</span>
        ${prevWeekReport ? `<button class="btn chip" data-action="weekly-report-week" data-week="${prevWeekReport.week}">◀ 第${prevWeekReport.week}週</button>` : ''}
        <span class="badge gold" style="font-size:0.95rem;padding:4px 10px;font-weight:bold;">第${selectedReport.week}週</span>
        ${nextWeekReport ? `<button class="btn chip" data-action="weekly-report-week" data-week="${nextWeekReport.week}">第${nextWeekReport.week}週 ▶</button>` : ''}
        ${reports.length > 1 ? `
          <select class="week-select-dropdown" data-action="weekly-report-select" style="padding:4px 8px;border-radius:4px;background:#18282b;color:#e8f0ec;border:1px solid #4a6265;font-size:0.85rem;">
            ${reports.map(r => `<option value="${r.week}" ${r.week === selectedReport.week ? 'selected' : ''}>第${r.week}週（${r.startDay}〜${r.endDay}日目）</option>`).join('')}
          </select>` : ''}
      </div>
      <div class="subtle" style="font-size:0.82rem;">
        ${isEn ? `Generated at turn ${selectedReport.endTurn}` : `集計時点: ${selectedReport.endTurn} ターン（${selectedReport.endDay}日目終了）`}
      </div>
    </div>
  `;

  // タブボタン行
  const tabRow = `
    <div class="tab-row" style="display:flex;gap:6px;margin-bottom:20px;border-bottom:2px solid #2d3f44;padding-bottom:2px;">
      ${WEEKLY_REPORT_TABS.map(tab => {
        const isActive = tab.id === currentTab;
        return `
          <button class="btn chip ${isActive ? 'active' : ''}" data-action="weekly-report-tab" data-tab="${tab.id}" data-week="${selectedReport.week}" style="font-size:0.9rem;padding:8px 14px;border-radius:6px 6px 0 0;${isActive ? 'background:#2d4447;border-bottom:2px solid #dfc374;color:#f0e4b8;font-weight:bold;' : 'background:#18262a;'}">
            <span aria-hidden="true">${tab.icon}</span> ${esc(tab.label)}
          </button>`;
      }).join('')}
    </div>
  `;

  let tabContent = '';
  if (currentTab === 'financial') {
    tabContent = renderFinancialTab(selectedReport, prevWeekReport, isEn);
  } else if (currentTab === 'market') {
    tabContent = renderMarketTab(selectedReport, isEn, selectedGood);
  } else if (currentTab === 'adventurers') {
    tabContent = renderAdventurersTab(selectedReport, prevWeekReport, isEn, s);
  } else if (currentTab === 'kingdom') {
    tabContent = renderKingdomTab(selectedReport, isEn);
  }

  const body = `
    <div class="weekly-report-container" style="min-width:320px;">
      ${weekSelector}
      ${tabRow}
      <div class="weekly-report-tab-body">
        ${tabContent}
      </div>
    </div>
  `;

  // タブの前へ・次へナビゲーション
  const currentTabIdx = WEEKLY_REPORT_TABS.findIndex(t => t.id === currentTab);
  const prevTab = currentTabIdx > 0 ? WEEKLY_REPORT_TABS[currentTabIdx - 1] : null;
  const nextTab = currentTabIdx < WEEKLY_REPORT_TABS.length - 1 ? WEEKLY_REPORT_TABS[currentTabIdx + 1] : null;

  const footer = `
    <div style="display:flex;justify-content:space-between;align-items:center;width:100%;gap:10px;flex-wrap:wrap;">
      <div>
        ${prevTab ? `<button class="btn secondary" data-action="weekly-report-tab" data-tab="${prevTab.id}" data-week="${selectedReport.week}">← ${prevTab.icon} ${esc(prevTab.label)}</button>` : ''}
      </div>
      <div style="display:flex;gap:8px;">
        ${nextTab ? `<button class="btn primary" data-action="weekly-report-tab" data-tab="${nextTab.id}" data-week="${selectedReport.week}">${nextTab.icon} ${esc(nextTab.label)} →</button>` : ''}
      </div>
    </div>
  `;

  return { title, body, footer };
}

/**
 * タブ1: 総売り上げ & 店舗・宿屋の実績
 */
function renderFinancialTab(rep: WeeklyReport, prevRep?: WeeklyReport, _isEn = false): string {
  const profitPositive = rep.netProfit >= 0;
  const prevRevenueDiff = prevRep ? rep.totalRevenue - prevRep.totalRevenue : null;
  const prevProfitDiff = prevRep ? rep.netProfit - prevRep.netProfit : null;

  const revDiffBadge = prevRevenueDiff !== null
    ? `<small class="subtle" style="font-size:0.75rem;display:block;margin-top:2px;">前週比 ${prevRevenueDiff >= 0 ? '+' : ''}${num(prevRevenueDiff)} G</small>`
    : '';
  const profitDiffBadge = prevProfitDiff !== null
    ? `<small class="subtle" style="font-size:0.75rem;display:block;margin-top:2px;">前週比 ${prevProfitDiff >= 0 ? '+' : ''}${num(prevProfitDiff)} G</small>`
    : '';

  // カテゴリ別売上
  const categoryNames: Record<string, string> = {
    goods: '商品売上（道具屋）',
    services: '施設利用料（宿・酒場・治療）',
    maps: '迷宮地図取引',
    materials: '素材売却',
    highway: '街道販売',
    upkeep: '施設維持費',
    spoilage: '食材廃棄損',
    raids: '魔物襲撃被害',
    advertising: '宣伝投資',
    repair: '修繕費用',
    other: 'その他',
  };

  const revenueRows = Object.entries(rep.revenueByCategory)
    .filter(([_, amount]) => amount > 0)
    .sort((a, b) => b[1] - a[1]);

  const expenseRows = Object.entries(rep.expensesByCategory)
    .filter(([_, amount]) => amount > 0)
    .sort((a, b) => b[1] - a[1]);

  return `
    <div class="financial-summary-section">
      <!-- 主要メトリクス -->
      <div class="stats-grid compact" style="margin-bottom:20px;grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));">
        ${stat('週間総売上', money(rep.totalRevenue), revDiffBadge, 'positive')}
        ${stat('週間総支出', money(rep.totalExpenses), '維持費・仕入れ・被害等', 'negative')}
        ${stat('週間純利益', money(rep.netProfit), profitDiffBadge, profitPositive ? 'positive' : 'negative')}
        ${stat('今期の税金', rep.tax.isExempt ? '<span style="color:#8bb889;">免税特例</span>' : money(rep.tax.lastPaidAmount), rep.tax.isExempt ? `免税残り${rep.tax.exemptionTurnsRemaining}T` : rep.tax.taxArrears > 0 ? `未納 ${money(rep.tax.taxArrears)}` : '納付完了')}
        ${stat('来訪パーティ総数', `${num(rep.totalVisitors)} <small>組</small>`, '拠点利用延べ数')}
      </div>

      <!-- 店舗・宿屋の実績 -->
      <div class="panel" style="margin-bottom:20px;">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;">🏬 店舗・宿屋・各施設の実績</h3>
          <span class="subtle">今週の利用状況と売上</span>
        </div>
        <div class="table-scroll">
          <table>
            <thead>
              <tr>
                <th>施設種別</th>
                <th>最大LV</th>
                <th>週間利用者数</th>
                <th>週間売上高</th>
                <th>評価・稼働状況</th>
              </tr>
            </thead>
            <tbody>
              ${rep.facilities.map(f => {
                const isShop = f.facility === 'shop';
                const isInn = f.facility === 'inn';
                const rowHighlight = (isShop || isInn) ? 'background:rgba(218,190,118,0.06);' : '';
                return `
                  <tr style="${rowHighlight}">
                    <td><strong>${esc(f.name)}</strong> ${isShop ? badge('店舗', 'gold') : isInn ? badge('主要施設', 'green') : ''}</td>
                    <td>LV ${f.level}</td>
                    <td>${num(f.users)} 名/組</td>
                    <td><strong>${money(f.revenue)}</strong></td>
                    <td>${f.level === 0 ? '<span class="subtle">未建設</span>' : f.revenue > 0 ? '<span class="badge green">高稼働</span>' : '<span class="subtle">待機中</span>'}</td>
                  </tr>`;
              }).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <!-- 収支内訳の2カラム -->
      <div class="two-column" style="gap:16px;margin-bottom:20px;">
        <div class="panel" style="margin:0;">
          <div class="panel-heading"><h4 style="margin:0;">📈 収入の内訳</h4></div>
          ${revenueRows.length ? `
            <table class="compact-table">
              ${revenueRows.map(([cat, amt]) => {
                const ratio = rep.totalRevenue > 0 ? Math.round((amt / rep.totalRevenue) * 100) : 0;
                return `
                  <tr>
                    <td>${esc(categoryNames[cat] || cat)}</td>
                    <td style="text-align:right;"><strong>${money(amt)}</strong> <small class="subtle">(${ratio}%)</small></td>
                  </tr>`;
              }).join('')}
            </table>` : '<p class="subtle">今週の売上記録はありません。</p>'}
        </div>
        <div class="panel" style="margin:0;">
          <div class="panel-heading"><h4 style="margin:0;">📉 支出の内訳</h4></div>
          ${expenseRows.length ? `
            <table class="compact-table">
              ${expenseRows.map(([cat, amt]) => {
                const ratio = rep.totalExpenses > 0 ? Math.round((amt / rep.totalExpenses) * 100) : 0;
                return `
                  <tr>
                    <td>${esc(categoryNames[cat] || cat)}</td>
                    <td style="text-align:right;"><strong>${money(amt)}</strong> <small class="subtle">(${ratio}%)</small></td>
                  </tr>`;
              }).join('')}
            </table>` : '<p class="subtle">今週の支出記録はありません。</p>'}
        </div>
      </div>

      <!-- 今期の税金・公課セクション -->
      <div class="panel" style="margin-bottom:20px;background:rgba(20,35,40,0.45);border:1px solid #3c5257;">
        <div class="panel-heading">
          <h4 style="margin:0;display:flex;align-items:center;gap:8px;">
            <span>🏛️ 今期の税金・納税状況</span>
            <span class="badge ${rep.tax.isExempt ? 'green' : rep.tax.taxArrears > 0 ? 'red' : 'gold'}">${esc(rep.tax.statusText)}</span>
          </h4>
          <span class="subtle">法定税率: ${Math.round(rep.tax.taxRate * 100)}% (7日周期)</span>
        </div>
        <div class="stats-grid compact" style="margin:0;grid-template-columns:repeat(auto-fit, minmax(140px, 1fr));border:0;background:transparent;">
          ${stat('今期納付済税額', rep.tax.isExempt ? '0 G (免税)' : money(rep.tax.lastPaidAmount), rep.tax.isExempt ? '創業特例期間中' : '国庫納付済み')}
          ${stat('未納税額 (滞納)', rep.tax.taxArrears > 0 ? money(rep.tax.taxArrears) : '0 G', rep.tax.taxArrears > 0 ? '強制徴収対象' : '滞納なし', rep.tax.taxArrears > 0 ? 'negative' : 'positive')}
          ${stat('累計納税額', money(rep.tax.totalPaidTax), '国家への通算貢献')}
          ${stat('次期納税見込', money(rep.tax.nextTaxEstimate), `期日: 第${rep.tax.nextTaxDueTurn}T`)}
        </div>
      </div>

      <!-- 日別売上推移グラフ / テーブル -->
      ${rep.dailySnapshots.length ? `
        <div class="panel">
          <div class="panel-heading">
            <h4 style="margin:0;display:flex;align-items:center;gap:8px;">
              <span>📅 週間日別 売上・利益の推移（線グラフ）</span>
              <span class="badge gold">Day ${rep.startDay} 〜 Day ${rep.endDay}</span>
            </h4>
            <span class="subtle">7日間の経営収支曲線</span>
          </div>

          ${renderSvgLineChart({
            chartId: 'fin-revenue-profit',
            width: 640,
            height: 195,
            xLabels: rep.dailySnapshots.map(d => `Day ${d.day}`),
            yUnit: 'G',
            series: [
              {
                id: 'rev',
                name: '日別総売上',
                color: '#dfc374',
                values: rep.dailySnapshots.map(d => d.revenue),
                fillGradient: true,
                valueFormatter: v => `${Math.floor(v).toLocaleString()} G`,
              },
              {
                id: 'profit',
                name: '日別純利益',
                color: '#7dd38c',
                values: rep.dailySnapshots.map(d => d.profit),
                valueFormatter: v => `${v >= 0 ? '+' : ''}${Math.floor(v).toLocaleString()} G`,
              },
            ],
            legendHint: '● <b style="color:#dfc374">日別総売上</b>: 前線拠点での商品・宿泊等の日次売上合計。 ● <b style="color:#7dd38c">日別純利益</b>: 売上から維持費・仕入れ等を差し引いた実質利益。',
          })}

          <div class="table-scroll">
            <table>
              <thead>
                <tr>
                  <th>日付</th>
                  <th>前線拠点売上</th>
                  <th>利益</th>
                  <th>来訪数</th>
                  <th>日次推移バー</th>
                </tr>
              </thead>
              <tbody>
                ${rep.dailySnapshots.map(snap => {
                  const maxRev = Math.max(1, ...rep.dailySnapshots.map(d => d.revenue));
                  const barPercent = Math.min(100, Math.round((snap.revenue / maxRev) * 100));
                  return `
                    <tr>
                      <td><strong>Day ${snap.day}</strong></td>
                      <td>${money(snap.revenue)}</td>
                      <td class="${snap.profit >= 0 ? 'positive' : 'negative'}">${snap.profit >= 0 ? '+' : ''}${money(snap.profit)}</td>
                      <td>${num(snap.visitors)} 組</td>
                      <td style="width:30%;min-width:120px;">
                        <span class="meter" style="height:8px;"><i style="width:${barPercent}%;background:#8db88b;"></i></span>
                      </td>
                    </tr>`;
                }).join('')}
              </tbody>
            </table>
          </div>
        </div>` : ''}
    </div>
  `;
}

/**
 * タブ2: 商品・価格推移 & 機会損失
 */
function renderMarketTab(rep: WeeklyReport, _isEn = false, selectedGood?: GoodsKey): string {
  const goodsList = Object.values(rep.goodsTrends);
  const opp = rep.opportunityLoss;

  const curGoodKey: GoodsKey = selectedGood && rep.goodsTrends[selectedGood] ? selectedGood : 'potion';
  const curGood = rep.goodsTrends[curGoodKey] || goodsList[0];

  const buyPrices = rep.dailySnapshots.map(snap => snap.prices[curGoodKey]?.buy ?? (curGood?.prices[0]?.buy ?? 0));
  const sellPrices = rep.dailySnapshots.map(snap => snap.prices[curGoodKey]?.sell ?? (curGood?.prices[0]?.sell ?? 0));

  const latestBuy = buyPrices[buyPrices.length - 1] ?? 0;
  const latestSell = sellPrices[sellPrices.length - 1] ?? 0;
  const curMarginG = Math.max(0, latestSell - latestBuy);
  const curMarginPercent = latestSell > 0 ? Math.round((curMarginG / latestSell) * 100) : 0;

  return `
    <div class="market-goods-section">
      <!-- 各売り上げアイテム数 -->
      <div class="panel" style="margin-bottom:20px;">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;">📦 各売り上げアイテムの実績</h3>
          <span class="subtle">販売数・売上高・粗利益</span>
        </div>
        <div class="table-scroll">
          <table>
            <thead>
              <tr>
                <th>商品名</th>
                <th>週間販売数</th>
                <th>売上高</th>
                <th>仕入原価</th>
                <th>粗利益</th>
                <th>最新仕入れ値</th>
                <th>最新販売値</th>
              </tr>
            </thead>
            <tbody>
              ${goodsList.map(g => {
                const latestPrice = g.prices[g.prices.length - 1];
                return `
                  <tr>
                    <td><strong>${esc(g.name)}</strong></td>
                    <td><strong>${num(g.count)}</strong></td>
                    <td>${money(g.revenue)}</td>
                    <td>${money(g.cost)}</td>
                    <td class="${g.profit >= 0 ? 'positive' : 'negative'}"><strong>${g.profit >= 0 ? '+' : ''}${money(g.profit)}</strong></td>
                    <td>${latestPrice ? `${num(latestPrice.buy)} G` : '-'}</td>
                    <td>${latestPrice ? `${num(latestPrice.sell)} G` : '-'}</td>
                  </tr>`;
              }).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <!-- 仕入れ値・販売値の推移（線グラフ） -->
      <div class="panel" style="margin-bottom:20px;">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;display:flex;align-items:center;gap:8px;">
            <span>📊 仕入れ値・販売値の推移（線グラフ）</span>
            <span class="badge gold">7日間推移</span>
          </h3>
          <span class="subtle">商品ごとの仕入値・販売価格の相場曲線</span>
        </div>

        <!-- 商品選択チップバー -->
        <div class="weekly-report-goods-selector" style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid #2d3e44;">
          <span class="subtle" style="font-size:0.83rem;align-self:center;margin-right:4px;">対象商品切替:</span>
          ${goodsList.map(g => {
            const isSelected = g.good === curGoodKey;
            return `
              <button class="btn chip ${isSelected ? 'active' : ''}" data-action="weekly-report-good" data-good="${g.good}" style="font-size:0.84rem;padding:5px 12px;${isSelected ? 'background:#384f52;border-color:#dfc374;color:#f0e4b8;font-weight:bold;' : 'background:#19272b;'}">
                ${esc(g.name)}
              </button>
            `;
          }).join('')}
        </div>

        ${renderSvgLineChart({
          chartId: `market-price-${curGoodKey}`,
          title: `【${esc(curGood?.name || curGoodKey)}】の価格推移と粗利幅`,
          subtitle: `Day ${rep.startDay} 〜 Day ${rep.endDay}`,
          width: 640,
          height: 195,
          xLabels: rep.dailySnapshots.map(d => `Day ${d.day}`),
          yUnit: 'G',
          series: [
            {
              id: 'buy',
              name: '仕入れ値（原価）',
              color: '#58b4db',
              values: buyPrices,
              fillGradient: true,
              valueFormatter: v => `${v.toLocaleString()} G`,
            },
            {
              id: 'sell',
              name: '販売基準値',
              color: '#dfc374',
              values: sellPrices,
              valueFormatter: v => `${v.toLocaleString()} G`,
            },
          ],
          legendHint: `● <b style="color:#58b4db">仕入れ値</b>: 本店での商品仕入原価。市場トレンドや豊凶・情勢で変動します。<br>● <b style="color:#dfc374">販売基準値</b>: 前線拠点での基本販売価格（最新の粗利率: 約${curMarginPercent}% / 利幅: ${curMarginG} G）。`,
        })}

        <div class="table-scroll">
          <table>
            <thead>
              <tr>
                <th>商品</th>
                ${rep.dailySnapshots.map(d => `<th>Day ${d.day}</th>`).join('')}
                <th>週間騰落</th>
              </tr>
            </thead>
            <tbody>
              ${goodsList.map(g => {
                const isCur = g.good === curGoodKey;
                const first = g.prices[0];
                const last = g.prices[g.prices.length - 1];
                const diffBuy = first && last ? last.buy - first.buy : 0;
                const trendText = diffBuy > 0 ? '<span class="badge red">高騰 ↑</span>' : diffBuy < 0 ? '<span class="badge green">下落 ↓</span>' : '<span class="badge muted">安定 →</span>';

                return `
                  <tr style="${isCur ? 'background:rgba(223,195,116,0.08);' : ''}">
                    <td><strong>${esc(g.name)}</strong> ${isCur ? badge('選択中', 'gold') : ''}</td>
                    ${rep.dailySnapshots.map(snap => {
                      const p = snap.prices[g.good];
                      return `
                        <td style="font-size:0.8rem;white-space:nowrap;">
                          仕 ${p ? num(p.buy) : '-'} / 販 ${p ? num(p.sell) : '-'}
                        </td>`;
                    }).join('')}
                    <td>${trendText}</td>
                  </tr>`;
              }).join('')}
            </tbody>
          </table>
        </div>
        <p class="subtle" style="font-size:0.75rem;margin:8px 0 0;">※表記は「仕: 仕入れ値 / 販: 販売値」。上の商品ボタンをクリックすると個別線グラフを切り替えられます。</p>
      </div>

      <!-- 機会損失数と内訳 -->
      <div class="panel" style="margin-bottom:20px;">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;">⚠️ 機会損失数と内訳（買えなかった客の分析）</h3>
          <span class="badge ${opp.total > 0 ? 'red' : 'green'}">今週の機会損失: ${opp.total} 件</span>
        </div>

        <div class="stats-grid compact" style="margin-bottom:16px;grid-template-columns:repeat(auto-fit, minmax(130px, 1fr));">
          ${stat('欠品・在庫切れ', `${num(opp.stockoutCount)} 件`, '商品不足による売り逃し', opp.stockoutCount > 0 ? 'negative' : '')}
          ${stat('価格高騰・買い控え', `${num(opp.priceRefusalCount)} 件`, '高値・所持金不足で見送り', opp.priceRefusalCount > 0 ? 'negative' : '')}
          ${stat('満室・満床', `${num(opp.capacityCount)} 件`, '宿屋や治療所の定員超過', opp.capacityCount > 0 ? 'negative' : '')}
          ${stat('その他見送り', `${num(opp.otherCount)} 件`, '要望不一致など')}
        </div>

        <!-- 商品別損失件数 -->
        <h4 style="margin:12px 0 8px;font-size:0.92rem;">商品・施設別の機会損失件数</h4>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;">
          ${Object.entries(opp.byItem).length ? Object.entries(opp.byItem).map(([item, count]) => `
            <div class="chip" style="background:#262d30;border:1px solid #4a5c61;padding:4px 10px;border-radius:4px;font-size:0.84rem;">
              <strong>${esc(item)}</strong>: <span style="color:#f29d9d;font-weight:bold;">${count}件</span>
            </div>
          `).join('') : '<span class="subtle">機会損失は発生していません。十分な在庫と適正な価格が維持されています！</span>'}
        </div>

        <!-- 冒険者の生の声（tradeFeedback抜粋） -->
        ${opp.feedbacks.length ? `
          <h4 style="margin:12px 0 8px;font-size:0.92rem;">冒険者たちの具体的な声（抜粋）</h4>
          <div class="table-scroll" style="max-height:220px;overflow-y:auto;">
            <table>
              <thead>
                <tr>
                  <th>発生日</th>
                  <th>冒険者パーティ</th>
                  <th>対象項目</th>
                  <th>理由・状況</th>
                </tr>
              </thead>
              <tbody>
                ${opp.feedbacks.slice(0, 15).map(f => `
                  <tr>
                    <td>Day ${f.day}</td>
                    <td><strong>${esc(f.partyName)}</strong></td>
                    <td>${badge(f.item, f.category === 'stockout' ? 'red' : f.category === 'price' ? 'gold' : '')}</td>
                    <td class="subtle">${esc(f.reason)}</td>
                  </tr>`).join('')}
              </tbody>
            </table>
          </div>` : ''}
      </div>
    </div>
  `;
}

/**
 * タブ3: 冒険者動向 & 評判
 */
function renderAdventurersTab(
  rep: WeeklyReport,
  prevRep?: WeeklyReport,
  _isEn = false,
  s?: GameState,
): string {
  const cas = rep.casualties;
  const prevVisitorsDiff = prevRep ? rep.totalVisitors - prevRep.totalVisitors : null;

  // 自営拠点（他商店除外）
  const playerBases = s?.bases ? s.bases.filter(b => !b.abandoned) : [];
  const targetBase = playerBases[0] || (rep.dailySnapshots[0]?.baseReputations[0] ? { id: rep.dailySnapshots[0].baseReputations[0].id, name: rep.dailySnapshots[0].baseReputations[0].name } : null);
  const baseName = targetBase?.name || '前線商館';
  const baseId = targetBase?.id || '';

  // 自営迷宮（他ダンジョン除外）
  const playerDungeons = s?.dungeons ? s.dungeons.filter(d => d.owned || playerBases.some(b => b.dungeonId === d.id)) : [];
  const targetDungeon = playerDungeons[0] || (rep.dailySnapshots[0]?.dungeonReputations[0] ? { id: rep.dailySnapshots[0].dungeonReputations[0].id, name: rep.dailySnapshots[0].dungeonReputations[0].name } : null);
  const dungeonName = targetDungeon?.name || '自営迷宮';
  const dungeonId = targetDungeon?.id || '';

  const basePopValues = rep.dailySnapshots.map(snap => {
    const cur = snap.baseReputations.find(b => !baseId || b.id === baseId);
    return cur ? cur.popularity : 0;
  });

  const dungeonPopValues = rep.dailySnapshots.map(snap => {
    const cur = snap.dungeonReputations.find(d => !dungeonId || d.id === dungeonId);
    return cur ? Math.round(cur.popularity) : 0;
  });

  const dungeonRecValues = rep.dailySnapshots.map(snap => {
    const cur = snap.dungeonReputations.find(d => !dungeonId || d.id === dungeonId);
    return cur ? Math.round(cur.recognition) : 0;
  });

  return `
    <div class="adventurers-summary-section">
      <!-- 来訪PT数サマリー -->
      <div class="stats-grid compact" style="margin-bottom:20px;grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));">
        ${stat('週間来訪PT総数', `${num(rep.totalVisitors)} <small>組</small>`, prevVisitorsDiff !== null ? `前週比 ${prevVisitorsDiff >= 0 ? '+' : ''}${num(prevVisitorsDiff)}組` : '商館訪問延べ数', 'positive')}
        ${stat('冒険者の死亡数', `${num(cas.deaths)} <small>名</small>`, '戦闘・罠・毒等による殉職', cas.deaths > 0 ? 'negative' : '')}
        ${stat('冒険者の負傷数', `${num(cas.injuries)} <small>名</small>`, '迷宮遠征での負傷者', cas.injuries > 0 ? 'negative' : '')}
        ${stat('パーティ全滅数', `${num(cas.wipes)} <small>組</small>`, '全員戦闘不能・壊滅', cas.wipes > 0 ? 'negative' : '')}
      </div>

      <!-- 拠点別来訪パーティ数 -->
      <div class="panel" style="margin-bottom:20px;">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;">🏕️ 商館拠点別の来訪PT実績</h3>
          <span class="subtle">各拠点の集客力</span>
        </div>
        <div class="table-scroll">
          <table>
            <thead>
              <tr>
                <th>商館拠点名</th>
                <th>週間来訪数</th>
                <th>シェア率</th>
                <th>来訪推移バー</th>
              </tr>
            </thead>
            <tbody>
              ${Object.entries(rep.visitorsByBase).map(([_baseId, data]) => {
                const ratio = rep.totalVisitors > 0 ? Math.round((data.visitors / rep.totalVisitors) * 100) : 0;
                return `
                  <tr>
                    <td><strong>${esc(data.baseName)}</strong></td>
                    <td><strong>${num(data.visitors)}</strong> 組</td>
                    <td>${ratio}%</td>
                    <td style="width:35%;min-width:140px;">
                      <span class="meter" style="height:8px;"><i style="width:${ratio}%;background:#90b4a4;"></i></span>
                    </td>
                  </tr>`;
              }).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <!-- 知名度・評判の推移（線グラフ） -->
      <div class="panel" style="margin-bottom:20px;">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;display:flex;align-items:center;gap:8px;">
            <span>🌟 知名度・評判の推移（線グラフ）</span>
            <span class="badge gold">Day ${rep.startDay} 〜 Day ${rep.endDay}</span>
          </h3>
          <span class="subtle">自営商館および自営迷宮の評価曲線（他ダンジョン・他店舗除外）</span>
        </div>

        ${renderSvgLineChart({
          chartId: 'adventurers-trend-chart',
          title: `【${esc(baseName)}・${esc(dungeonName)}】の知名度・評判推移`,
          subtitle: `自営店舗・迷宮の評価（他ダンジョン・他店舗除外）`,
          width: 640,
          height: 195,
          xLabels: rep.dailySnapshots.map(d => `Day ${d.day}`),
          yMin: 0,
          yMax: 100,
          yTicks: [0, 25, 50, 75, 100],
          series: [
            {
              id: 'base-pop',
              name: `${baseName}（商館評判）`,
              color: '#dfc374',
              values: basePopValues,
              fillGradient: true,
              valueFormatter: v => `${v} / 100`,
            },
            {
              id: 'dungeon-pop',
              name: `${dungeonName}（迷宮人気）`,
              color: '#7dd38c',
              values: dungeonPopValues,
              valueFormatter: v => `${v} / 100`,
            },
            {
              id: 'dungeon-rec',
              name: `${dungeonName}（認知PT率）`,
              color: '#59b0e8',
              dashed: true,
              values: dungeonRecValues,
              valueFormatter: v => `${v}%`,
            },
          ],
          legendHint: '※自営の前線商館（店舗）および拠点直結の自営迷宮のデータのみを集計しています（他ダンジョン・他店舗の情報は除外）。<br>● <b style="color:#dfc374">商館評判</b>: 店舗・宿屋の冒険者利用評価。<br>● <b style="color:#7dd38c">迷宮人気度</b>: 迷宮遠征での冒険者評価。<br>■ <b style="color:#59b0e8">迷宮認知PT率</b>: 周辺冒険者における迷宮の認知割合。',
        })}

        <div class="table-scroll">
          <table>
            <thead>
              <tr>
                <th>対象</th>
                ${rep.dailySnapshots.map(d => `<th>Day ${d.day}</th>`).join('')}
                <th>最終値</th>
              </tr>
            </thead>
            <tbody>
              <!-- 拠点の人気（自営商館のみ） -->
              <tr>
                <td><strong>${esc(baseName)}</strong> <small class="subtle">(自営商館・店舗評判)</small></td>
                ${rep.dailySnapshots.map((_snap, i) => `<td>${num(basePopValues[i])}</td>`).join('')}
                <td><strong style="color:#dfc374;">${num(basePopValues[basePopValues.length - 1] ?? 0)} / 100</strong></td>
              </tr>

              <!-- 迷宮の人気度（自営迷宮のみ） -->
              <tr>
                <td><strong>${esc(dungeonName)}</strong> <small class="subtle">(自営迷宮・人気度)</small></td>
                ${rep.dailySnapshots.map((_snap, i) => `<td>${num(dungeonPopValues[i])}</td>`).join('')}
                <td><strong style="color:#7dd38c;">${num(dungeonPopValues[dungeonPopValues.length - 1] ?? 0)} / 100</strong></td>
              </tr>

              <!-- 迷宮の認知率（自営迷宮のみ） -->
              <tr>
                <td><strong>${esc(dungeonName)}</strong> <small class="subtle">(自営迷宮・認知PT率)</small></td>
                ${rep.dailySnapshots.map((_snap, i) => `<td>${dungeonRecValues[i]}%</td>`).join('')}
                <td><strong style="color:#59b0e8;">${dungeonRecValues[dungeonRecValues.length - 1] ?? 0}%</strong></td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <!-- 冒険者の遭難・全滅ログ -->
      <div class="panel" style="margin-bottom:20px;">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;">💀 冒険者の被害・遭難ログ</h3>
          <span class="subtle">今週記録された死亡・全滅の報告</span>
        </div>
        ${cas.logs.length ? `
          <div class="table-scroll" style="max-height:220px;overflow-y:auto;">
            <table>
              <thead>
                <tr>
                  <th>発生日</th>
                  <th>種別</th>
                  <th>パーティ名</th>
                  <th>内容</th>
                </tr>
              </thead>
              <tbody>
                ${cas.logs.map(log => `
                  <tr>
                    <td>Day ${log.day}</td>
                    <td>${log.type === 'wipe' ? badge('全滅', 'red') : log.type === 'death' ? badge('死亡', 'red') : badge('負傷', 'gold')}</td>
                    <td><strong>${esc(log.partyName || '-')}</strong></td>
                    <td class="subtle">${esc(log.text)}</td>
                  </tr>`).join('')}
              </tbody>
            </table>
          </div>` : '<p class="subtle" style="padding:10px 0;">今週は冒険者の死亡・全滅などの重大被害は記録されていません。安全な開拓が進んでいます！</p>'}
      </div>
    </div>
  `;
}

/**
 * タブ4: 王国情勢 & 商店LVアップの条件
 */
function renderKingdomTab(rep: WeeklyReport, _isEn = false): string {
  const up = rep.hqUpgrade;

  return `
    <div class="kingdom-events-and-upgrade-section">
      <!-- 次の商店LVアップの条件 -->
      <div class="panel" style="margin-bottom:22px;border:1px solid #786438;background:radial-gradient(ellipse at 50% -20%,rgba(65,85,60,0.2) 0%,transparent 65%),linear-gradient(150deg,#1c2c29,#152522 60%,#182627);">
        <div class="panel-heading" style="border-bottom:1px solid #5a4b2c;padding-bottom:12px;">
          <div>
            <div style="display:flex;align-items:center;gap:8px;">
              <span class="badge gold" style="font-size:0.9rem;">商会発展</span>
              <h3 style="margin:0;font-size:1.25rem;color:#f0e2b6;">
                ${up.maxLevelReached ? '商会総本店（最高峰レベル到達）' : `次の本店レベルアップ目標: LV ${up.targetLevel}【${esc(up.targetTitle)}】`}
              </h3>
            </div>
            <p class="subtle" style="margin:6px 0 0;">現在: 本店 LV ${up.currentLevel}</p>
          </div>
          <div>
            ${up.canUpgrade
              ? '<span class="badge green" style="font-size:0.95rem;padding:6px 12px;font-weight:bold;">★ 条件達成！今すぐ昇格可能</span>'
              : up.maxLevelReached
                ? '<span class="badge gold">最高位</span>'
                : '<span class="badge" style="font-size:0.85rem;">昇格準備中</span>'}
          </div>
        </div>

        ${!up.maxLevelReached ? `
          <div style="margin:16px 0;">
            <h4 style="margin:0 0 10px;font-size:0.95rem;color:#d5e2d6;">昇格に必要な条件と現在の達成度</h4>
            <div class="table-scroll">
              <table>
                <thead>
                  <tr>
                    <th>条件項目</th>
                    <th>必要条件</th>
                    <th>現在の達成状況</th>
                    <th>進捗率</th>
                    <th>判定</th>
                  </tr>
                </thead>
                <tbody>
                  ${up.conditions.map(c => `
                    <tr>
                      <td><strong>${esc(c.label)}</strong></td>
                      <td>${esc(c.required)}</td>
                      <td><strong>${esc(c.current)}</strong></td>
                      <td style="width:25%;min-width:100px;">
                        <span class="meter ${c.satisfied ? '' : 'danger'}" style="height:7px;">
                          <i style="width:${c.progressPercent}%;background:${c.satisfied ? '#8bb889' : '#d29654'};"></i>
                        </span>
                      </td>
                      <td>${c.satisfied ? '<span class="badge green">✓ 達成</span>' : '<span class="badge red">✗ 未達</span>'}</td>
                    </tr>`).join('')}
                </tbody>
              </table>
            </div>

            <!-- 解禁される特権 -->
            <div class="notice" style="margin:16px 0 0;background:rgba(50,60,40,0.3);border:1px solid #635634;border-radius:6px;padding:12px 16px;">
              <strong style="color:#eed89e;">🎁 昇格で解禁される機能・恩恵:</strong>
              <p style="margin:6px 0 0;line-height:1.6;font-size:0.9rem;">${esc(up.unlocks)}</p>
            </div>
          </div>` : `
          <div style="padding:16px 0;">
            <p style="color:#d5dec6;line-height:1.6;">おめでとうございます！本店は最高峰レベル（LV5）に到達しており、すべての国家特権、中央金庫、大型馬車、最高位の施設枠が開放されています。</p>
          </div>`}

        <!-- 各商館の道具屋（店舗）の状況 -->
        <div style="margin-top:18px;padding-top:14px;border-top:1px dashed #4d5d54;">
          <h4 style="margin:0 0 8px;font-size:0.92rem;color:#b2c4ba;">商館拠点における「道具屋（店舗）」の拡張状況</h4>
          <div class="table-scroll">
            <table>
              <thead>
                <tr>
                  <th>商館拠点名</th>
                  <th>道具屋LV</th>
                  <th>最大上限LV</th>
                  <th>次LV拡張費用</th>
                  <th>拡張可否</th>
                </tr>
              </thead>
              <tbody>
                ${up.shopFacilities.map(s => `
                  <tr>
                    <td><strong>${esc(s.baseName)}</strong></td>
                    <td>LV ${s.currentLevel}</td>
                    <td>最大 LV ${s.maxLevel}</td>
                    <td>${s.currentLevel < s.maxLevel ? money(s.nextCost) : '<span class="subtle">最大</span>'}</td>
                    <td>${s.currentLevel >= s.maxLevel ? '<span class="badge muted">最大LV到達</span>' : s.canUpgrade ? '<span class="badge green">資金充足・拡張可</span>' : '<span class="subtle">拠点資金不足</span>'}</td>
                  </tr>`).join('')}
              </tbody>
            </table>
          </div>
          <p class="subtle" style="font-size:0.75rem;margin:6px 0 0;">※商館の道具屋レベル上限は、本店（商店）のレベルに応じて引き上げられます。</p>
        </div>
      </div>

      <!-- 王国への納税と信用度 -->
      <div class="panel" style="margin-bottom:22px;border:1px solid #4a5c54;background:rgba(23,38,36,0.35);">
        <div class="panel-heading" style="border-bottom:1px solid #3d4f48;padding-bottom:12px;">
          <div>
            <div style="display:flex;align-items:center;gap:8px;">
              <span class="badge gold">国家財政</span>
              <h3 style="margin:0;font-size:1.15rem;color:#f0e4b8;">🏛️ 王国への納税実績と国家信用</h3>
            </div>
            <p class="subtle" style="margin:4px 0 0;">法定税率: 営業利益の 15%（7日＝35ターン周期で算定・納付）</p>
          </div>
          <div>
            <span class="badge ${rep.tax.isExempt ? 'green' : rep.tax.taxArrears > 0 ? 'red' : 'gold'}" style="font-size:0.85rem;padding:4px 10px;">
              ${esc(rep.tax.statusText)}
            </span>
          </div>
        </div>

        <div style="margin:16px 0;">
          <div class="stats-grid compact" style="margin-bottom:16px;grid-template-columns:repeat(auto-fit, minmax(140px, 1fr));">
            ${stat('今期納付税額', rep.tax.isExempt ? '0 G (免税)' : money(rep.tax.lastPaidAmount), rep.tax.isExempt ? `創業特例（残${rep.tax.exemptionTurnsRemaining}T）` : rep.tax.trustGainOrLoss > 0 ? `国信用 +${rep.tax.trustGainOrLoss}` : '納付済み')}
            ${stat('未納残高 (滞納)', rep.tax.taxArrears > 0 ? money(rep.tax.taxArrears) : '0 G', rep.tax.taxArrears > 0 ? '強制徴収・信用低下' : '滞納なし', rep.tax.taxArrears > 0 ? 'negative' : 'positive')}
            ${stat('次回納税見込額', money(rep.tax.nextTaxEstimate), `次回納付期: 第${rep.tax.nextTaxDueTurn}T`)}
            ${stat('国家通算納税額', money(rep.tax.totalPaidTax), '王室への累計財政貢献')}
          </div>

          <div class="notice" style="margin:0;background:rgba(40,50,45,0.4);border:1px solid #4a5d52;font-size:0.86rem;line-height:1.7;">
            ${rep.tax.isExempt
              ? '<strong>【創業免税特例 適用中】</strong> 開業から10日間（50ターン）は新興商会への創業支援として納税が全額免除されます。事業基盤の整備と前線商館の強化に専念できます。'
              : rep.tax.taxArrears > 0
                ? `<strong style="color:#f88;">【⚠️ 未納税の警告】</strong> 未納残高 ${rep.tax.taxArrears.toLocaleString()} G が発生しています。未納税があると王国の信用度が継続低下し、本店資金が入金されると強制徴収が行われます。早めの納税・返済を行ってください。`
                : '<strong>【納税優良商会】</strong> 今期の税務は適正に完了しています。期限内の全額納税により王国の信任が深まり、商会昇格に必要な国家評価が蓄積されます。'}
          </div>
        </div>
      </div>

      <!-- 王国で発生したイベント -->
      <div class="panel">
        <div class="panel-heading">
          <h3 style="margin:0;font-size:1.05rem;">👑 王国で発生したイベント・出来事</h3>
          <span class="subtle">今週の情勢・社会動向</span>
        </div>
        ${rep.kingdomEvents.length ? `
          <div class="table-scroll">
            <table>
              <thead>
                <tr>
                  <th>発生ターン</th>
                  <th>種別</th>
                  <th>出来事の標題</th>
                  <th>内容と影響</th>
                  <th>状態</th>
                </tr>
              </thead>
              <tbody>
                ${rep.kingdomEvents.map(e => `
                  <tr>
                    <td>第${e.startTurn}T</td>
                    <td>${badge(e.type === 'dragon' ? '王国危機' : e.type === 'raid' ? '防衛戦' : e.type === 'shortage' ? '品不足' : e.type === 'trend' ? '流行' : 'ギルド', e.type === 'dragon' || e.type === 'raid' ? 'red' : 'gold')}</td>
                    <td><strong>${esc(e.title)}</strong></td>
                    <td class="subtle" style="max-width:320px;line-height:1.5;">${esc(e.text)}</td>
                    <td>${e.statusText === '進行中' ? '<span class="badge gold">進行中</span>' : '<span class="badge muted">終了</span>'}</td>
                  </tr>`).join('')}
              </tbody>
            </table>
          </div>` : '<p class="subtle" style="padding:10px 0;">今週は平穏でした。特筆すべき国家異変や緊急イベントは発生していません。</p>'}
      </div>
    </div>
  `;
}
