import { ONBOARDING_FACILITIES } from '../game/config.ts';
import { baseFor } from '../game/selectors.ts';
import { btn, esc, partyDisplayName } from './helpers.ts';
import { facilityName } from '../game/i18n.ts';
import type { GameState } from '../game/model.ts';
import type { Language } from '../game/i18n.ts';

const scenes = {
  ja: [
    { title: '夜明け前の追跡', text: 'オオカミの遠吠えが背後に迫る。地図も方角も失い、主人公は黎明の平原をさまよっていた。' },
    { title: '口を開けた迷宮', text: '崩れた岩の下に、未発見の迷宮が口を開けていた。旅商人の主人公は、商人が迷宮を発見すれば近くにキャラバンを構える権利を得られると思い出す。探索から戻る冒険者の素材を買い取り、食料やポーションを売る。追手から逃げ込んだだけの場所が、商機に見えてきた。' },
    { title: '迷宮の先は国道だった', text: '長い地下道を抜けると、朝日と国道が目の前に広がった。主人公は荷物を積んだ荷台に乗り、ゆっくりと道を進む。遠くに町の灯りが見え、道行く人々の声が朝の風に乗って届いた。' },
  ],
  en: [
    { title: 'Hunted before dawn', text: 'Wolves howl close behind. Lost and without a map, the protagonist wanders across the Dawn Plains.' },
    { title: 'A dungeon', text: 'Beneath the fallen rocks lies an undiscovered dungeon. The traveling merchant remembers the rule: whoever discovers a dungeon earns the right to establish a caravan nearby. Adventurers will need food and potions, and those who return will have materials to sell. What began as a hiding place could become a thriving trade.' },
    { title: 'The road beyond the dungeon', text: 'A long passage opens onto a sunlit highway. The protagonist rides atop a slow cargo wagon as town lights appear in the distance and travelers’ voices carry on the morning breeze.' },
  ],
};

const t = (lang: Language, ja: string, en: string): string => lang === 'en' ? en : ja;
const brandLogo = new URL('../assets/frontier-ledger-logo.svg', import.meta.url).href;

export function nextOnboardingFacility(s: GameState, baseId = baseFor(s, s.onboarding.targetDungeonId)?.id) {
  if (s.onboarding?.status !== 'investments') return null;
  const base = s.bases.find(x => x.id === baseId && !x.abandoned);
  return ONBOARDING_FACILITIES.find(key => !((base?.facilities[key] ?? 0) > 0)) || null;
}

export function canSkipOnboarding(s: GameState): boolean {
  return Number(s.hq?.level || 1) >= 2;
}

export function onboardingSkipButton(s: GameState, lang: Language = 'ja'): string {
  return canSkipOnboarding(s)
    ? btn(t(lang, '導入をスキップ', 'Skip onboarding'), 'onboarding-skip-guide', {}, 'text-btn')
    : '';
}

const sceneArtwork = [
  { name: 'wolves', src: new URL('../assets/onboarding-wolves.webp', import.meta.url).href, altJa: '夜明けの平原をオオカミから逃れる旅人', altEn: 'A traveler fleeing wolves across the dawn plain' },
  { name: 'dungeon', src: new URL('../assets/onboarding-dungeon.webp', import.meta.url).href, altJa: '黎明の平原で迷宮の入口を見つけた旅人', altEn: 'A traveler discovering a dungeon entrance on the dawn plain' },
  { name: 'highway', src: new URL('../assets/onboarding-highway.webp', import.meta.url).href, altJa: '荷馬車で迷宮の先にある国道へ出る旅人', altEn: 'A traveler riding a cargo wagon toward the highway beyond the dungeon' },
] as const;

function sceneArt(index: number, lang: Language): string {
  const scene = sceneArtwork[index] || sceneArtwork[2];
  return `<img class="onboarding-art art-${scene.name}" src="${scene.src}" alt="${t(lang, scene.altJa, scene.altEn)}" width="1672" height="941" decoding="async">`;
}

export function onboardingStory(s: GameState, lang: Language = 'ja'): string {
  const scene = Math.max(0, Math.min(2, s.onboarding?.scene || 0));
  const copy = scenes[lang] || scenes.ja;
  return `<article class="onboarding-story"><div class="onboarding-masthead"><img class="onboarding-logo" src="${brandLogo}" alt="Frontier Ledger" width="320" height="88"><div class="onboarding-kicker">${t(lang, '序章 · 黎明の平原', 'PROLOGUE · DAWN PLAINS')}<span>${scene + 1} / 3</span></div></div>${sceneArt(scene, lang)}<h3>${copy[scene].title}</h3><p>${copy[scene].text}</p><div class="onboarding-dots" aria-label="${scene + 1} / 3">${copy.map((_, i) => `<i class="${i === scene ? 'active' : i < scene ? 'done' : ''}"></i>`).join('')}</div></article>`;
}

export function onboardingArrival(s: GameState, lang: Language = 'ja'): string {
  const party = s.parties.find(p => p.id === s.onboarding?.arrivalPartyId);
  return `<article class="onboarding-arrival">${sceneArt(2, lang)}<div class="onboarding-kicker">${t(lang, '最初の来訪', 'FIRST ARRIVAL FROM THE HIGHWAY')}</div><h3>${t(lang, '国道から、冒険者がやってきた。', 'Your first adventurers have arrived.')}</h3><p>${party ? `${esc(partyDisplayName(party.name, lang))} · ${esc(party.rank)} ${t(lang, 'ランクのPTが商館に到着しました。', 'rank party has reached the outpost.')}` : t(lang, '黎明の迷宮を目指す冒険者が商館に到着しました。', 'Adventurers bound for the Dawn Dungeon have reached the outpost.')}</p></article>`;
}

export function onboardingGuide(s: GameState, lang: Language = 'ja'): string {
  const status = s.onboarding?.status;
  if (!['investments', 'awaiting-arrival', 'awaiting-return'].includes(status)) return '';
  if (!status) return '';
  const paceHint = `<small class="subtle">${t(lang, '導入中は通常の約3倍で進行します。', 'Onboarding runs about 3× faster.')}</small>`;
  const guide = (heading: string, text: string, action = '', mark = '↗') =>
    `<section class="onboarding-guide" aria-live="polite"><div class="onboarding-guide-mark">${mark}</div><div class="onboarding-guide-copy"><div class="onboarding-kicker"><span class="onboarding-kicker-title"><span class="badge gold" style="font-size:0.68rem;padding:1px 6px;margin-right:6px;vertical-align:1px;">${t(lang, 'チュートリアル', 'TUTORIAL')}</span>${t(lang, 'はじめての商圏', 'YOUR FIRST MARKET')}</span></div><h2>${heading}</h2><p>${text}</p>${paceHint}${action ? `<div class="onboarding-actions">${action}</div>` : ''}</div></section>`;
  if (status === 'awaiting-return') {
    const party = s.parties.find(p => p.id === s.onboarding?.arrivalPartyId);
    const partyName = party ? `${esc(partyDisplayName(party.name, lang))}（${party.rank}ランク）` : t(lang, '最初のパーティ', 'the first party');
    const returnHint = t(lang, '冒険者が帰ってきたら、ダンジョンの情報を聞いてみよう。仕入れた情報をもとに、他の冒険者に地図を売ることができる', 'When adventurers return, let’s hear what they learned in the dungeon. We can sell maps to other adventurers based on that information.');
    return guide(t(lang, '最初の遠征', 'First expedition'),
      t(lang, `${partyName}が初めての探索に出発しました。${returnHint}`, `${partyName} has set out on its first expedition. ${returnHint}`));
  }
  const baseId = s.bases.find(b => b.dungeonId === s.onboarding.targetDungeonId && !b.abandoned)?.id;
  const base = s.bases.find(b => b.id === baseId);
  const completed = ONBOARDING_FACILITIES.filter(key => (base?.facilities[key] ?? 0) > 0);
  const target = nextOnboardingFacility(s, baseId);
  const waiting = status === 'awaiting-arrival' || !target;
  const steps = ONBOARDING_FACILITIES.map((key, i) => `<li class="${(base?.facilities[key] ?? 0) > 0 ? 'done' : key === target ? 'current' : ''}"><i>${(base?.facilities[key] ?? 0) > 0 ? '✓' : i + 1}</i><span>${esc(facilityName(key, lang))}</span></li>`).join('');
  const heading = waiting ? t(lang, '初めての来訪', 'First visitors') : t(lang, '商館の施設', 'Outpost facilities');
  const text = waiting
    ? t(lang, '荷馬車は街道を進んでいます。', 'The wagon is on its way.')
    : '';
  const action = waiting
    ? ''
    : btn(t(lang, `${facilityName(target, 'ja')}を投資`, `Invest in ${facilityName(target, 'en')}`), 'onboarding-focus-facility', { option: target }, 'primary');
  const skip = onboardingSkipButton(s, lang);
  return `<section class="onboarding-guide" aria-live="polite"><div class="onboarding-guide-mark">${waiting ? '↗' : '✦'}</div><div class="onboarding-guide-copy"><div class="onboarding-kicker"><span class="onboarding-kicker-title"><span class="badge gold" style="font-size:0.68rem;padding:1px 6px;margin-right:6px;vertical-align:1px;">${t(lang, 'チュートリアル', 'TUTORIAL')}</span>${t(lang, 'はじめての商圏', 'YOUR FIRST MARKET')}</span><span>${completed.length} / ${ONBOARDING_FACILITIES.length}</span></div><h2>${heading}</h2>${text ? `<p>${text}</p>` : ''}<ol class="onboarding-progress">${steps}</ol>${action || skip ? `<div class="onboarding-actions">${action}${skip}</div>` : ''}</div></section>`;
}
