import type { AccountCategory, DailyAccounts, GoodsKey } from './model.ts';

export const ACCOUNT_CATEGORIES: readonly AccountCategory[] = ['goods', 'services', 'maps', 'materials', 'highway', 'upkeep', 'spoilage', 'raids', 'advertising', 'repair', 'other'];
export const GOODS_KEYS: readonly GoodsKey[] = ['potion', 'magicPotion', 'antidote', 'food', 'weapon', 'armor'];

export function emptyAccounts(turn = 0): DailyAccounts {
  return {
    turn,
    revenue: Object.fromEntries(ACCOUNT_CATEGORIES.map(key => [key, 0])) as DailyAccounts['revenue'],
    expenses: Object.fromEntries(ACCOUNT_CATEGORIES.map(key => [key, 0])) as DailyAccounts['expenses'],
    goods: Object.fromEntries(GOODS_KEYS.map(key => [key, { count: 0, revenue: 0, cost: 0 }])) as DailyAccounts['goods'],
    visitors: 0, stockoutRate: 0, complete: true,
  };
}

// Old saves retain their exact totals; unavailable historical categories are explicit.
export function legacyAccounts(turn: number, revenue: number, profit: number): DailyAccounts {
  const result = emptyAccounts(turn);
  result.revenue.other = revenue;
  result.expenses.other = revenue - profit;
  result.complete = revenue === 0 && profit === 0;
  return result;
}

export function accountTotal(values: Record<AccountCategory, number>): number {
  return ACCOUNT_CATEGORIES.reduce((sum, key) => sum + values[key], 0);
}
