export function protagonistMerchantTitle(s: Pick<GameState, 'merchantName'>, lang: Language = 'ja'): string {
  const name = protagonistMerchantName(s, lang);
  return lang === 'en' ? `${t('tag_master', lang)} ${name}` : `${t('tag_master', lang)}${name}`;
}

