export function timeOfDayLabel(turn: number, lang: Language = 'ja'): string {
  const keys = ['morning', 'forenoon', 'afternoon', 'evening', 'night'];
  return t(`time_${keys[turn % 5]}`, lang);
}

export function difficultyLabel(level: number, lang: Language = 'ja'): string {
  const keys = ['diff_easy', 'diff_normal', 'diff_hard', 'diff_very_hard', 'diff_extreme'];
  return t(keys[Math.max(0, Math.min(4, level - 1))], lang);
}

export function phaseLabel(phase: string, lang: Language = 'ja'): string {
  if (lang === 'en') {
    const enPhases: Record<string, string> = {
      rumor: 'Rumor Only',
      surveying: 'Surveying',
      discovered: 'Discovered',
      applying: 'Under Review',
      permitted: 'Permit Granted',
      road: 'Road Connected',
      operating: 'Operating',
      cleared: 'Boss Cleared',
      abandoned: 'Abandoned',
    };
    return enPhases[phase] ?? phase;
  }
  const jaPhases: Record<string, string> = {
    rumor: '噂のみ',
    surveying: '調査中',
    discovered: '発見済み',
    applying: '審査中',
    permitted: '開拓許可',
    road: '道路接続済み',
    operating: '商圏営業中',
    cleared: 'ボス討伐済み',
    abandoned: '撤退済み',
  };
  return jaPhases[phase] ?? phase;
}

const HERO_PORTRAITS = [
  new URL('../assets/hero_rank1.jpg', import.meta.url).href,
  new URL('../assets/hero_rank2.jpg', import.meta.url).href,
  new URL('../assets/hero_rank3.jpg', import.meta.url).href,
  new URL('../assets/hero_rank4.jpg', import.meta.url).href,
] as const;

export function heroPortrait(state: Pick<GameState, 'hq'> | null | undefined): string {
  const trust = state?.hq?.trust ?? 0;
  if (trust < 25) return HERO_PORTRAITS[0];
  if (trust < 65) return HERO_PORTRAITS[1];
  if (trust < 120) return HERO_PORTRAITS[2];
  return HERO_PORTRAITS[3];
}

export function heroRankIndex(state: Pick<GameState, 'hq'> | null | undefined): number {
  const trust = state?.hq?.trust ?? 0;
  if (trust < 25) return 1;
  if (trust < 65) return 2;
  if (trust < 120) return 3;
  return 4;
}

