import type { GameState } from '../game/model.ts';
import type { UIState } from './model.ts';
import { activeMembers } from '../game/selectors.ts';
import { getMemberMaxHp } from '../game/equipment.ts';
import { esc } from './helpers.ts';

export function ogreBattleView(state: GameState, ui: UIState): string {
  const isEn = ui.lang === 'en';
  const raid = state.ogreRaid;

  if (!raid) {
    return `
      <section class="panel ogre-battle-panel empty-state">
        <header class="panel-header">
          <h2>${isEn ? 'Ogre Defense' : 'オーガ迎撃戦'}</h2>
        </header>
        <div class="panel-body">
          <p class="muted">${isEn ? 'No active ogre raid in progress.' : '現在、オーガ来襲イベントは発生していません。'}</p>
        </div>
      </section>
    `;
  }

  const base = state.bases.find(b => b.id === raid.baseId) || state.bases[0];
  const percentKills = Math.min(100, Math.round((raid.ogresDefeated / Math.max(1, raid.ogresTotal)) * 100));
  const targetPercent = Math.round((raid.targetKills / Math.max(1, raid.ogresTotal)) * 100);
  const isTargetAchieved = raid.ogresDefeated >= raid.targetKills;

  // Phase badge
  let phaseBadge = '';
  if (raid.phase === 'preparing') {
    const daysLeft = Math.ceil(raid.prepareTurnsRemaining / 5);
    phaseBadge = `<span class="badge warning" style="background:#b8860b; color:#fff; padding:4px 8px; border-radius:4px; font-weight:bold;">${isEn ? `Preparing (${daysLeft} days remaining)` : `迎撃準備中（残り${daysLeft}日 / ${raid.prepareTurnsRemaining}T）`}</span>`;
  } else if (raid.phase === 'battle') {
    phaseBadge = `<span class="badge danger" style="background:#b22222; color:#fff; padding:4px 8px; border-radius:4px; font-weight:bold; animation:pulse 1.5s infinite;">${isEn ? `In Battle (Round ${raid.battleTurnsElapsed + 1}/${raid.battleTurnsMax})` : `迎撃戦闘中（第${raid.battleTurnsElapsed + 1}/${raid.battleTurnsMax}ラウンド）`}</span>`;
  } else {
    phaseBadge = raid.isVictory
      ? `<span class="badge success" style="background:#2e8b57; color:#fff; padding:4px 8px; border-radius:4px; font-weight:bold;">${isEn ? 'Victory!' : '撃退成功！'}</span>`
      : `<span class="badge danger" style="background:#8b0000; color:#fff; padding:4px 8px; border-radius:4px; font-weight:bold;">${isEn ? 'Defeat' : '撃退失敗'}</span>`;
  }

  // 1/3 Target status highlight
  const targetStatusHtml = isTargetAchieved
    ? `
      <div class="ogre-target-badge achieved" style="margin-top:8px; padding:10px 14px; background:rgba(46,139,87,0.2); border:1px solid #2e8b57; border-radius:6px; color:#2e8b57; font-weight:bold; display:flex; align-items:center; gap:8px;">
        <span style="font-size:1.3rem;">🎉</span>
        <div>
          <div>${isEn ? 'Defense Threshold Reached! (1/3+ Defeated)' : '【撃退成功ライン突破！】オーガの群れの撃退に成功！'}</div>
          <small style="font-weight:normal; opacity:0.9;">${isEn ? 'Defeated enough ogres to protect the outpost. Continue fighting for extra rewards!' : '1/3以上のオーガを討伐しました。さらなる討伐で戦果と追加報酬を拡大できます！'}</small>
        </div>
      </div>
    `
    : `
      <div class="ogre-target-badge pending" style="margin-top:8px; padding:10px 14px; background:rgba(184,134,11,0.15); border:1px solid #b8860b; border-radius:6px; color:#b8860b; font-weight:bold; display:flex; align-items:center; gap:8px;">
        <span style="font-size:1.3rem;">⚠️</span>
        <div>
          <div>${isEn ? `Repel Threshold: ${raid.targetKills} Ogres (${raid.targetKills - raid.ogresDefeated} more needed)` : `撃退成功目標: ${raid.targetKills}体以上撃破（あと ${raid.targetKills - raid.ogresDefeated} 体で撃退成功）`}</div>
          <small style="font-weight:normal; opacity:0.9;">${isEn ? 'Must defeat at least 1/3 of the horde to prevent store destruction.' : '群れの1/3以上を撃破することで拠点の半壊を阻止できます。冒険者たちを支援しましょう！'}</small>
        </div>
      </div>
    `;

  // Progress Bar with 1/3 Threshold Marker
  const progressBarHtml = `
    <div class="ogre-kill-progress" style="margin:16px 0;">
      <div style="display:flex; justify-content:space-between; margin-bottom:4px; font-size:0.9rem;">
        <strong>${isEn ? 'Ogre Horde Elimination' : 'オーガ軍団 討伐進捗'}</strong>
        <span><strong>${raid.ogresDefeated}</strong> / ${raid.ogresTotal} ${isEn ? 'Defeated' : '体討伐'}</span>
      </div>
      <div style="position:relative; height:24px; background:#222; border-radius:12px; overflow:hidden; border:1px solid #444;">
        <div style="position:absolute; left:0; top:0; bottom:0; width:${percentKills}%; background:linear-gradient(90deg, #b22222, ${isTargetAchieved ? '#2e8b57' : '#e67e22'}); transition:width 0.4s ease;"></div>
        <!-- 1/3 Threshold Indicator Line -->
        <div style="position:absolute; left:${targetPercent}%; top:0; bottom:0; width:2px; background:#ffd700; z-index:2;" title="${isEn ? 'Repel Threshold (1/3)' : '撃退成功ライン (1/3)'}"></div>
      </div>
      <div style="position:relative; margin-top:2px; height:18px; font-size:0.75rem;">
        <span style="position:absolute; left:${targetPercent}%; transform:translateX(-50%); color:#ffd700; font-weight:bold;">
          ▲ ${isEn ? `Goal: ${raid.targetKills} kills (1/3)` : `成功ライン: ${raid.targetKills}体 (1/3)`}
        </span>
      </div>
    </div>
  `;

  // Action Controls
  let controlsHtml = '';
  if (raid.phase === 'preparing') {
    controlsHtml = `
      <div class="ogre-controls" style="margin:16px 0; padding:14px; background:rgba(0,0,0,0.25); border-radius:8px; border:1px solid #444;">
        <p style="margin-bottom:10px;">「斥候から、２日後にオーガの群れが到達するという連絡がありました。これから冒険者たちが撃退に備えてくれる」</p>
        <div style="display:flex; gap:10px; flex-wrap:wrap; align-items:center;">
          <span class="muted">${isEn ? 'Adventurers will gather at the outpost. Free lodging and food are active.' : '冒険者たちが商館に集結しています。宿・食料は無償提供されています。'}</span>
          <button class="btn btn-warning" data-action="force-start-ogre-battle" style="margin-left:auto; background:#b8860b; color:#fff; border:none; padding:8px 16px; border-radius:4px; font-weight:bold; cursor:pointer;">
            ${isEn ? 'Start Battle Now' : '迎撃戦闘を今すぐ開始（スキップ）'}
          </button>
        </div>
      </div>
    `;
  } else if (raid.phase === 'battle') {
    controlsHtml = `
      <div class="ogre-controls" style="margin:16px 0; padding:14px; background:rgba(0,0,0,0.3); border-radius:8px; border:1px solid #555; display:flex; gap:12px; align-items:center; flex-wrap:wrap;">
        <div style="flex:1;">
          <strong>${isEn ? 'Battle in Progress!' : '迎撃戦が進行中！'}</strong>
          <div class="muted" style="font-size:0.85rem;">${isEn ? 'All parties fight ogres. Victorious parties advance to the next ogre!' : '全PTが最大1日オーガと戦闘します。勝利したPTは次のオーガと連戦します。'}</div>
        </div>
        <button class="btn btn-primary" data-action="advance-ogre-battle" style="background:#4a76a8; color:#fff; border:none; padding:10px 18px; border-radius:4px; font-weight:bold; cursor:pointer;">
          ${isEn ? 'Fight 1 Round' : '1ラウンド戦闘を進める'}
        </button>
        <button class="btn btn-danger" data-action="auto-ogre-battle" style="background:#b22222; color:#fff; border:none; padding:10px 18px; border-radius:4px; font-weight:bold; cursor:pointer;">
          ${isEn ? 'Auto Resolve Battle' : '迎撃戦を一括進行'}
        </button>
      </div>
    `;
  } else if (raid.phase === 'result') {
    const resultAlert = raid.isVictory
      ? `
        <div style="padding:16px; background:rgba(46,139,87,0.25); border:1px solid #2e8b57; border-radius:8px; margin-bottom:14px;">
          <h3 style="color:#2e8b57; margin-bottom:8px;">🎉 ${isEn ? 'Ogre Raid Repelled Successfully!' : 'オーガの群れの撃退に成功！'}</h3>
          <p>${isEn ? 'Thanks to the brave adventurers, the horde was driven off. Surviving parties have received gold rewards and ogre materials. Outpost popularity and Royal trust have significantly increased!' : '冒険者たちの奮闘により、オーガの群れを完全に撃退しました！ 生存した冒険者たちに報奨金2,000Gと貴重なオーガ素材（角・剛皮）が授与されました。商館の評判と国の信用度が大幅に向上しました！'}</p>
          <ul style="margin-top:8px; padding-left:20px; font-size:0.9rem;">
            <li>生存パーティ全員に報奨金 2,000 G ＆ オーガ素材 授与</li>
            <li>商館人気 +30 / 王国信用 +5</li>
            <li>商館倉庫にオーガ素材（角5個・剛皮10個）を寄贈</li>
          </ul>
        </div>
      `
      : `
        <div style="padding:16px; background:rgba(178,34,34,0.25); border:1px solid #b22222; border-radius:8px; margin-bottom:14px;">
          <h3 style="color:#ff6b6b; margin-bottom:8px;">💀 ${isEn ? 'Outpost Breached - Defense Failed' : 'オーガの猛攻を止められず、撃退失敗…'}</h3>
          <p>${isEn ? 'The adventurers could not stop the horde in time. The outpost sustained massive damage and is partially destroyed (Damage +50%). Outpost popularity and trust have declined.' : '防衛ラインを突破され、オーガの猛攻により店舗が半壊（施設損耗度 +50%）してしまいました…。商館の評判が大きく低下しました。施設の修繕が必要です。'}</p>
          <ul style="margin-top:8px; padding-left:20px; font-size:0.9rem;">
            <li>店舗が半壊（損耗度 +50%）</li>
            <li>商館金庫から被害発生</li>
            <li>商館人気 -30 / 王国信用 -3</li>
          </ul>
        </div>
      `;

    controlsHtml = `
      <div class="ogre-controls" style="margin:16px 0;">
        ${resultAlert}
        <button class="btn btn-success" data-action="dismiss-ogre-battle" style="background:#2e8b57; color:#fff; border:none; padding:12px 24px; border-radius:6px; font-weight:bold; cursor:pointer; font-size:1rem; width:100%;">
          ${isEn ? 'Confirm Results and Return to Operations' : '結果を確認して通常業務へ復帰'}
        </button>
      </div>
    `;
  }

  // Parties Status Grid
  const partiesList = state.parties.filter(p => p.location === 'base' || raid.partyProgress[p.id]);
  const displayParties = partiesList.length > 0 ? partiesList : state.parties.slice(0, 5);

  const partiesHtml = displayParties.map(p => {
    const progress = raid.partyProgress[p.id];
    const alive = activeMembers(p);
    const isRetreated = progress?.retreated || alive.length === 0;
    const kills = progress?.defeatedCount ?? 0;

    let statusText = '';
    if (isRetreated) {
      statusText = `<span style="color:#ff6b6b; font-weight:bold;">${isEn ? 'Retreated' : '負傷撤退'}</span>`;
    } else if (kills > 0) {
      statusText = `<span style="color:#2ecc71; font-weight:bold;">${isEn ? `${kills} Ogres Defeated! Advancing` : `${kills}体撃破！次のオーガへ連戦進撃`}</span>`;
    } else {
      statusText = `<span style="color:#f39c12; font-weight:bold;">${isEn ? 'Engaged in Combat' : '交戦中'}</span>`;
    }

    const membersHtml = p.members.map(m => {
      const maxHp = getMemberMaxHp(m);
      const hpPct = Math.min(100, Math.round((m.hp / Math.max(1, maxHp)) * 100));
      const color = m.status === 'dead' ? '#777' : m.status === 'injured' || hpPct < 30 ? '#e74c3c' : '#2ecc71';
      return `
        <div style="font-size:0.75rem; margin-top:2px;">
          <div style="display:flex; justify-content:space-between;">
            <span>${esc(m.name)} (${esc(m.job)})</span>
            <span style="color:${color};">${m.hp}/${maxHp}</span>
          </div>
          <div style="height:4px; background:#333; border-radius:2px; overflow:hidden;">
            <div style="width:${hpPct}%; height:100%; background:${color};"></div>
          </div>
        </div>
      `;
    }).join('');

    const recentLogs = (progress?.log ?? []).slice(0, 2).map(l => `<div style="font-size:0.75rem; color:#aaa; margin-top:2px;">• ${esc(l)}</div>`).join('');

    return `
      <div class="party-card" style="padding:10px; background:rgba(255,255,255,0.04); border:1px solid #444; border-radius:6px;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
          <strong>${esc(p.name)} <span class="badge" style="background:#555; color:#fff; font-size:0.7rem; padding:2px 4px; border-radius:3px;">${p.rank}</span></strong>
          ${statusText}
        </div>
        <div class="party-members" style="margin-bottom:6px;">
          ${membersHtml}
        </div>
        ${recentLogs ? `<div class="party-recent-log" style="border-top:1px dashed #444; padding-top:4px;">${recentLogs}</div>` : ''}
      </div>
    `;
  }).join('');

  // Ogres Unit Grid
  const ogresHtml = raid.ogres.map((o, idx) => {
    const hpPct = Math.min(100, Math.round((o.hp / Math.max(1, o.maxHp)) * 100));
    const isDead = o.defeated || o.hp <= 0;
    return `
      <div class="ogre-unit-card" style="padding:6px 10px; background:${isDead ? 'rgba(0,0,0,0.4)' : 'rgba(178,34,34,0.15)'}; border:1px solid ${isDead ? '#333' : '#b22222'}; border-radius:4px; opacity:${isDead ? 0.6 : 1};">
        <div style="display:flex; justify-content:space-between; font-size:0.8rem; font-weight:bold;">
          <span>${idx + 1}. ${esc(o.name)}</span>
          <span>${isDead ? '💥 討伐済' : `${o.hp}/${o.maxHp}`}</span>
        </div>
        ${!isDead ? `
          <div style="height:4px; background:#333; border-radius:2px; margin-top:4px; overflow:hidden;">
            <div style="width:${hpPct}%; height:100%; background:#e74c3c;"></div>
          </div>
        ` : o.killerPartyName ? `
          <div style="font-size:0.7rem; color:#2ecc71; margin-top:2px;">討伐者: ${esc(o.killerPartyName)}</div>
        ` : ''}
      </div>
    `;
  }).join('');

  // Overall Battle Log
  const logEntriesHtml = raid.battleLog.slice(0, 15).map(entry => `
    <li style="padding:3px 0; border-bottom:1px solid rgba(255,255,255,0.05); font-size:0.85rem;">${esc(entry)}</li>
  `).join('');

  return `
    <section class="panel ogre-battle-panel" style="max-width:1000px; margin:0 auto; padding:16px;">
      <header class="panel-header" style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #444; padding-bottom:12px;">
        <div>
          <h2 style="margin:0; font-size:1.5rem; display:flex; align-items:center; gap:8px;">
            <span style="color:#e74c3c;">👹</span> ${isEn ? 'Ogre Defense Battle' : 'オーガ来襲 迎撃防衛戦'}
          </h2>
          <small class="muted">${isEn ? `Target Outpost: ${esc(base?.name ?? '')}` : `防衛対象拠点: ${esc(base?.name ?? '')} （施設損耗度: ${base?.damage ?? 0}%）`}</small>
        </div>
        <div>${phaseBadge}</div>
      </header>

      <div class="panel-body">
        ${targetStatusHtml}
        ${progressBarHtml}
        ${controlsHtml}

        <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap:16px; margin-top:20px;">
          <div>
            <h3 style="font-size:1.1rem; margin-bottom:10px; display:flex; align-items:center; gap:6px;">
              <span>🛡️</span> ${isEn ? 'Adventurer Parties in Defense' : '迎撃にあたる冒険者部隊'}
            </h3>
            <div style="display:flex; flex-direction:column; gap:8px;">
              ${partiesHtml}
            </div>
          </div>

          <div>
            <h3 style="font-size:1.1rem; margin-bottom:10px; display:flex; align-items:center; gap:6px;">
              <span>👹</span> ${isEn ? 'Ogre Horde' : 'オーガの群れ（部隊一覧）'}
            </h3>
            <div style="display:grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap:6px; max-height:380px; overflow-y:auto; padding-right:4px;">
              ${ogresHtml}
            </div>
          </div>
        </div>

        <div class="battle-log-section" style="margin-top:24px; padding:12px; background:rgba(0,0,0,0.3); border-radius:6px; border:1px solid #333;">
          <h4 style="margin:0 0 8px 0; font-size:0.95rem;">📜 ${isEn ? 'Battle Log' : '迎撃戦闘記録'}</h4>
          <ul style="list-style:none; padding:0; margin:0; max-height:160px; overflow-y:auto;">
            ${logEntriesHtml}
          </ul>
        </div>
      </div>
    </section>
  `;
}
