import type { Job, Member } from './model.ts';
import { getMemberMaxHp } from './equipment.ts';

export interface MemberLevelStats {
  maxHp: number;
  mp: number;
  attack: number;
  defense: number;
  magicAttack: number;
  magicDefense: number;
  speed: number;
}

type GrowthOdds = [plusOne: number, plusTwo: number];

interface JobStatProfile {
  base: MemberLevelStats;
  growth: Record<keyof MemberLevelStats, GrowthOdds>;
}

