const STAT_KEYS: Array<keyof MemberLevelStats> = ['maxHp', 'mp', 'attack', 'defense', 'magicAttack', 'magicDefense', 'speed'];

function mix32(value: number): number {
  let mixed = value >>> 0;
  mixed = Math.imul(mixed ^ (mixed >>> 16), 0x7feb352d) >>> 0;
  mixed = Math.imul(mixed ^ (mixed >>> 15), 0x846ca68b) >>> 0;
  return (mixed ^ (mixed >>> 16)) >>> 0;
}

export function memberGrowthSeed(worldSeed: number, memberId: number): number {
  return mix32((worldSeed ^ Math.imul(memberId, 0x9e3779b1)) >>> 0);
}

function growthRoll(seed: number, level: number, statIndex: number): number {
  const key = (seed ^ Math.imul(level, 0x9e3779b1) ^ Math.imul(statIndex + 1, 0x85ebca6b)) >>> 0;
  return mix32(key) / 0x100000000;
}

function memberGrowthAtLevel(job: Job, level: number, seed: number): MemberLevelStats {
  const profile = JOB_STAT_PROFILES[job];
  const gains = { maxHp: 0, mp: 0, attack: 0, defense: 0, magicAttack: 0, magicDefense: 0, speed: 0 };
  for (const [index, stat] of STAT_KEYS.entries()) {
    const [plusOneChance, plusTwoChance] = profile.growth[stat];
    const roll = growthRoll(seed, level, index);
    gains[stat] = roll < plusTwoChance ? 2 : roll < plusTwoChance + plusOneChance ? 1 : 0;
  }
  return gains;
}

export function memberStatsForLevel(job: Job, level: number, seed: number): MemberLevelStats {
  const profile = JOB_STAT_PROFILES[job];
  const stats = { ...profile.base };
  const safeLevel = Math.max(1, Math.floor(Number.isFinite(level) ? level : 1));
  for (let gainedLevel = 2; gainedLevel <= safeLevel; gainedLevel++) {
    const gains = memberGrowthAtLevel(job, gainedLevel, seed);
    for (const stat of STAT_KEYS) stats[stat] += gains[stat];
  }
  return stats;
}

function applyGrowth(member: Member, gains: MemberLevelStats, direction: 1 | -1): void {
  const hpGain = gains.maxHp * direction;
  member.maxHp = Math.max(1, member.maxHp + hpGain);
  const maxHp = getMemberMaxHp(member);
  member.hp = member.status === 'dead' || member.hp <= 0 ? 0
    : direction > 0 ? Math.min(maxHp, member.hp + hpGain) : Math.min(member.hp, maxHp);
  for (const stat of STAT_KEYS) {
    if (stat === 'maxHp') continue;
    member[stat] = Math.max(0, member[stat] + gains[stat] * direction);
  }
}

export function changeMemberLevel(member: Member, requestedLevel: number): void {
  const nextLevel = Math.max(1, Math.floor(Number.isFinite(requestedLevel) ? requestedLevel : member.level));
  const growthSeed = Number.isFinite(member.growthSeed) ? member.growthSeed : memberGrowthSeed(1, member.id);
  const currentLevel = Math.max(1, Math.floor(member.level));
  if (nextLevel > currentLevel) {
    member.justLeveledUp = true;
    for (let level = currentLevel + 1; level <= nextLevel; level++) {
      applyGrowth(member, memberGrowthAtLevel(member.job, level, growthSeed), 1);
    }
  } else {
    for (let level = currentLevel; level > nextLevel; level--) {
      applyGrowth(member, memberGrowthAtLevel(member.job, level, growthSeed), -1);
    }
  }
  member.level = nextLevel;
}
