import { adventurerDisplayName, esc, partyDisplayName } from './helpers.ts';
import { turnLabel } from '../game/selectors.ts';
import { localizedBaseName, localizedDungeonName, t } from '../game/i18n.ts';
import type { GameState } from '../game/model.ts';
import type { Language, NewsCategory, NewsFilterSettings, UIState, ViewId } from './model.ts';
import { DEFAULT_NEWS_FILTERS } from './model.ts';
import { gameIcon } from './icons.ts';

export interface KingdomNewsItem {
  id: string;
  category: NewsCategory | 'bulletin';
  badge: string;
  badgeClass: string;
  headline: string;
  text: string;
  remaining?: string;
  view: ViewId;
  targetId?: string;
  urgent?: boolean;
  broadcastIds?: string[];
  turn?: number;
  repeatCount?: number;
}

export function getKingdomNews(
  s: GameState,
  lang: Language,
  filters: NewsFilterSettings = DEFAULT_NEWS_FILTERS,
  broadcastedIds: Set<string> = new Set()
): KingdomNewsItem[] {
  const items: KingdomNewsItem[] = [];
  const coveredDeathLogIds = new Set<string>();
  const summarizedDeathLogIds = new Set<string>();
  const summarizedEventLogIds = new Set<string>();

  // 1. Adventurer death news
  // Casualty news stays queued until its ticker finishes or the user dismisses it.
  if (filters.casualty) {
    type CasualtyRecord = {
      id: string;
      headline: string;
      text: string;
      view: ViewId;
      targetId?: string;
      turn?: number;
      dungeonId?: string;
      count?: number;
      broadcastIds: string[];
    };
    const casualties: CasualtyRecord[] = [];

    for (const p of s.parties) {
      for (const m of p.members) {
        if (m.status !== 'dead') continue;

        const id = `casualty-${m.id}`;
        const d = s.dungeons.find(d => d.id === m.deathDungeonId)
          || s.dungeons.find(d => d.id === p.currentDungeonId);
        const relatedDeathLogs = s.logs.filter(l => {
          const isDeathLog = /戦死|全滅|命を落と|死亡/.test(l.text);
          const matchesTurn = m.deathTurn === undefined || l.turn === m.deathTurn;
          const matchesParty = l.target?.id === p.id;
          const matchesEquipmentLoss = !l.target?.id && Boolean(d && l.text.includes(d.name));
          return isDeathLog && matchesTurn && l.text.includes(m.name) && (matchesParty || matchesEquipmentLoss);
        });
        const relatedLogIds = relatedDeathLogs.map(l => `log-${l.id}`);
        relatedLogIds.forEach(logId => coveredDeathLogIds.add(logId));
        if (broadcastedIds.has(id) || relatedLogIds.some(logId => broadcastedIds.has(logId))) continue;

        casualties.push({
          id,
          turn: m.deathTurn,
          dungeonId: d?.id,
          headline: lang === 'en' ? 'Adventurer Fallen' : '冒険者戦死',
          text: lang === 'en'
            ? `${adventurerDisplayName(m.name, lang)} (${m.rank}-Rank ${m.job}) of ${partyDisplayName(p.name, lang)} has fallen in battle${d ? ` at ${localizedDungeonName(d.name, lang)}` : ''}.`
            : `${p.name}の${m.name}（${m.rank}ランク・${m.job}）が${d ? `${d.name}にて` : ''}戦死しました。`,
          view: 'parties',
          targetId: p.id,
          broadcastIds: [id, ...relatedLogIds],
        });
      }
    }

    // Parties that were completely wiped are removed from the active list.
    // Their individual death logs still identify the dungeon and turn.
    const orphanDeathLogs = s.logs.filter(l => {
      const id = `log-${l.id}`;
      return /戦死|命を落と|死亡/.test(l.text)
        && !coveredDeathLogIds.has(id)
        && !broadcastedIds.has(id)
        && l.target?.view === 'parties'
        && Boolean(l.target?.id)
        && s.dungeons.some(d => l.text.includes(d.name));
    });
    for (const l of orphanDeathLogs) {
      const dungeon = s.dungeons.find(d => l.text.includes(d.name));
      if (!dungeon) continue;
      const id = `log-${l.id}`;
      coveredDeathLogIds.add(id);
      casualties.push({
        id,
        turn: l.turn,
        dungeonId: dungeon.id,
        headline: turnLabel(l.turn),
        text: l.text,
        view: l.target?.view || 'parties',
        targetId: l.target?.id,
        broadcastIds: [id],
      });
    }

    // A death can also produce an equipment-loss log. Attach it to the same
    // casualty alert without counting it as another death.
    for (const l of s.logs) {
      const id = `log-${l.id}`;
      if (!l.text.includes('死亡した') || !l.text.includes('装備品') || coveredDeathLogIds.has(id) || broadcastedIds.has(id)) continue;
      const dungeon = s.dungeons.find(d => l.text.includes(d.name));
      const casualty = casualties.find(record => record.dungeonId === dungeon?.id && record.turn === l.turn);
      if (!casualty) continue;
      casualty.broadcastIds.push(id);
      coveredDeathLogIds.add(id);
    }

    // A party can be wiped by a kingdom event that does not emit one log per
    // member. Use the wipe log's recorded death count when no member records
    // already cover that party in this dungeon and turn.
    for (const l of s.logs) {
      if (!l.text.includes('全滅')) continue;
      const id = `log-${l.id}`;
      if (broadcastedIds.has(id)) continue;
      const dungeon = s.dungeons.find(d => l.text.includes(d.name));
      const partyName = l.text.match(/^(.+?)（/)?.[1];
      const representedCasualty = casualties.find(casualty =>
        casualty.dungeonId === dungeon?.id
        && casualty.turn === l.turn
        && Boolean(partyName && casualty.text.includes(partyName))
      );
      if (representedCasualty) {
        representedCasualty.broadcastIds.push(id);
        coveredDeathLogIds.add(id);
        continue;
      }

      const count = Number(l.text.match(/(\d+)名が死亡/)?.[1]);
      if (!count) continue;
      coveredDeathLogIds.add(id);
      casualties.push({
        id,
        turn: l.turn,
        dungeonId: dungeon?.id,
        count,
        headline: turnLabel(l.turn),
        text: l.text,
        view: l.target?.view || 'parties',
        targetId: l.target?.id,
        broadcastIds: [id],
      });
    }

    const casualtyGroups = new Map<string, CasualtyRecord[]>();
    for (const casualty of casualties) {
      const key = casualty.dungeonId
        ? casualty.dungeonId
        : casualty.id;
      const group = casualtyGroups.get(key) || [];
      group.push(casualty);
      casualtyGroups.set(key, group);
    }

    for (const [key, group] of casualtyGroups) {
      const dungeon = s.dungeons.find(d => d.id === group[0].dungeonId);
      const count = group.reduce((total, casualty) => total + (casualty.count || 1), 0);
      group.flatMap(casualty => casualty.broadcastIds)
        .filter(id => id.startsWith('log-'))
        .forEach(id => summarizedDeathLogIds.add(id));
      if (dungeon && count >= 2) {
        const broadcastIds = [...new Set(group.flatMap(casualty => casualty.broadcastIds))];
        items.push({
          id: `casualty-summary-${key.replace(/[^a-zA-Z0-9_-]/g, '-')}`,
          category: 'casualty',
          badge: lang === 'en' ? 'CASUALTIES' : '訃報',
          badgeClass: 'red',
          headline: lang === 'en' ? `${count} Adventurers Lost` : `${dungeon.name}で${count}名死亡`,
          text: lang === 'en'
            ? `${count} adventurers died at ${localizedDungeonName(dungeon.name, lang)}.`
            : `${dungeon.name}で冒険者${count}名が死亡しました。`,
          view: 'parties',
          urgent: true,
          broadcastIds,
          turn: Math.min(...group.map(casualty => casualty.turn ?? s.turn)),
        });
      } else {
        for (const casualty of group) {
          items.push({
            ...casualty,
            category: 'casualty',
            badge: lang === 'en' ? 'CASUALTY' : '訃報',
            badgeClass: 'red',
            urgent: true,
          });
        }
      }
    }

  }

  // 2. Active kingdom events
  const activeEvents = filters.event ? s.events.filter(e => e.state === 'active' && !broadcastedIds.has(`event-${e.id}`)) : [];
  const activeEventBroadcastIds = new Map<string, string[]>();
  const assignedEventLogIds = new Set<string>();
  for (const event of activeEvents) {
    const matchingLog = s.logs.find(l => {
      const logId = `log-${l.id}`;
      const matchesTarget = !event.targetId || !l.target?.id || l.target.id === event.targetId;
      return !assignedEventLogIds.has(logId) && l.turn === event.start && (
        (matchesTarget && l.text.startsWith(event.title))
        || (event.type === 'raid' && l.type === 'warning' && l.target?.id === event.targetId && l.text.includes('魔物襲撃'))
      );
    });
    const ids = [`event-${event.id}`];
    if (matchingLog) {
      const logId = `log-${matchingLog.id}`;
      ids.push(logId);
      assignedEventLogIds.add(logId);
      summarizedEventLogIds.add(logId);
    }
    activeEventBroadcastIds.set(event.id, ids);
  }

  const groupedActiveEvents = new Map<string, typeof activeEvents>();
  for (const event of activeEvents) {
    const duplicateKey = `${event.type}:${event.outcome || ''}:${event.title.replace(/\s+/g, ' ').trim()}:${event.text.replace(/\s+/g, ' ').trim()}`;
    const group = groupedActiveEvents.get(duplicateKey) || [];
    group.push(event);
    groupedActiveEvents.set(duplicateKey, group);
  }
  for (const group of groupedActiveEvents.values()) {
    const e = group[0];
    const rem = Math.max(...group.map(event => Math.max(0, event.start + event.duration - s.turn)));
    let badge = lang === 'en' ? 'EVENT' : '出来事';
    let badgeClass = 'gold';
    let urgent = false;

    if (e.type === 'dragon' || e.type === 'raid' || (e.type === 'wagon-ambush' && e.outcome === 'looted')) {
      badge = lang === 'en' ? 'ALERT' : (e.type === 'raid' || e.type === 'wagon-ambush' ? '襲撃' : '緊急');
      badgeClass = 'red';
      urgent = true;
    } else if (e.type === 'wagon-ambush') {
      badge = lang === 'en' ? 'REPORT' : '朗報';
      badgeClass = 'green';
    } else if (e.type === 'bandits') {
      badge = lang === 'en' ? 'ALERT' : '警告';
      badgeClass = 'red';
      urgent = true;
    } else if (e.type === 'guild') {
      badge = lang === 'en' ? 'GUILD' : 'ギルド';
      badgeClass = 'gold';
    } else if (e.type === 'trend') {
      badge = lang === 'en' ? 'TREND' : '流行';
      badgeClass = 'green';
    } else if (e.type === 'sword-arrival') {
      badge = lang === 'en' ? 'HOLY SWORD' : '聖剣';
      badgeClass = 'gold';
    } else if (e.type === 'survey-corps') {
      badge = lang === 'en' ? 'SURVEY' : '調査兵団';
      badgeClass = 'blue';
    } else if (e.type === 'fairy-dream') {
      badge = lang === 'en' ? 'FAIRY' : '妖精の夢';
      badgeClass = 'gold';
    } else if (e.type === 'shortage') {
      badge = lang === 'en' ? 'MARKET' : '品薄';
      badgeClass = 'red';
    }

    const eventIds = group.map(event => event.id);
    items.push({
      id: group.length > 1 ? `event-summary-${eventIds.join('-')}` : e.id,
      category: 'event',
      badge,
      badgeClass,
      headline: e.title,
      text: e.text,
      remaining: lang === 'en' ? `${rem}T left` : `残り${rem}T`,
      repeatCount: group.length > 1 ? group.length : undefined,
      urgent,
      view: 'events',
      targetId: e.targetId,
      turn: Math.min(...group.map(event => event.start)),
      broadcastIds: [...new Set(group.flatMap(event => activeEventBroadcastIds.get(event.id) || [`event-${event.id}`]))],
    });
  }

  // 3. Bearer of the Holy Sword
  if (filters.legend && s.swordHolder) {
    const holder = s.parties.find(p => p.id === s.swordHolder?.partyId);
    const member = holder?.members.find(m => m.id === s.swordHolder?.memberId);
    const holderNewsId = `sword-holder-${s.swordHolder.partyId}-${s.swordHolder.memberId}`;
    if (member && member.status !== 'dead' && !broadcastedIds.has(holderNewsId)) {
      items.push({
        id: holderNewsId,
        category: 'legend',
        badge: lang === 'en' ? 'LEGEND' : '伝承',
        badgeClass: 'gold',
        headline: lang === 'en' ? 'Holy Sword' : '聖剣の担い手',
        text: lang === 'en'
          ? `${adventurerDisplayName(member.name, lang)} (${member.rank}-rank ${member.job}) of ${partyDisplayName(holder?.name || 'Party', lang)} bears the Holy Sword.`
          : `${holder?.name || ''}の${member.name}（${member.rank}ランク・${member.job}）が聖剣を帯同中。`,
        view: 'events',
        broadcastIds: [holderNewsId],
        turn: s.turn,
      });
    }
  }

  // Keep distinct one-time topics queued separately and collapse exact duplicates.
  if (filters.chronicle) {
    const unreadLogs = s.logs.filter(l => {
      const id = `log-${l.id}`;
      return l.broadcastOnce && !l.broadcasted && !broadcastedIds.has(id)
        && !l.text.includes('しばらくダンジョンがクローズするぞ')
        && !summarizedDeathLogIds.has(id) && !summarizedEventLogIds.has(id);
    });
    const groupedUnreadLogs = new Map<string, typeof unreadLogs>();
    for (const log of unreadLogs) {
      const duplicateKey = `${log.type}:${log.text.replace(/\s+/g, ' ').trim()}`;
      const group = groupedUnreadLogs.get(duplicateKey) || [];
      group.push(log);
      groupedUnreadLogs.set(duplicateKey, group);
    }
    for (const group of groupedUnreadLogs.values()) {
      const l = group[0];
      const logIds = group.map(log => `log-${log.id}`);
      items.push({
        id: group.length > 1 ? `news-digest-${group.map(log => log.id).join('-')}` : `log-${l.id}`,
        category: 'bulletin',
        badge: lang === 'en' ? 'MERCHANT' : '商人',
        badgeClass: 'gold',
        headline: lang === 'en' ? 'Merchant Warning' : '商人からの警告',
        text: l.text,
        view: l.target?.view || 'events',
        targetId: l.target?.id,
        urgent: true,
        repeatCount: group.length > 1 ? group.length : undefined,
        turn: Math.min(...group.map(log => log.turn)),
        broadcastIds: logIds,
      });
    }
  }

  // 4. Recent major kingdom chronicle logs (including death / casualty logs)
  const duplicateLogItems = new Map<string, KingdomNewsItem>();
  for (const l of s.logs) {
    if (l.broadcastOnce) continue;
    const logId = `log-${l.id}`;
    if (broadcastedIds.has(logId) || summarizedEventLogIds.has(logId)) continue;
    const isDeathLog = l.text.includes('戦死') || l.text.includes('全滅') || l.text.includes('命を落と') || l.text.includes('死亡');
    if (filters.casualty && isDeathLog && coveredDeathLogIds.has(`log-${l.id}`)) continue;
    const isEventsLog = l.target?.view === 'events';
    const isMajor = l.type === 'major' || l.type === 'rumor';
    const isKingdomHappening = l.text.includes('討伐') || l.text.includes('到着しました') || l.text.includes('納税') || l.text.includes('免除');
    if (!isDeathLog && !isEventsLog && !isMajor && !isKingdomHappening) continue;

    if (isDeathLog) {
      if (!filters.casualty) continue;
      if (broadcastedIds.has(logId)) continue;
    } else {
      if (!filters.chronicle) continue;
    }

    const rumorDungeon = l.type === 'rumor' && l.target?.view === 'events'
      ? s.dungeons.find(dungeon => dungeon.id === l.target?.id)
      : undefined;
    const nobleVisitBase = l.type === 'rumor'
      && l.target?.view === 'base'
      && l.text.includes('一行は')
      && l.text.includes('歓待と贅沢なひとときに大変満足し')
      ? s.bases.find(base => base.id === l.target?.id)
      : undefined;
    const summaryHeadline = rumorDungeon
      ? (lang === 'en' ? 'Rumors Spread' : '噂拡大')
      : nobleVisitBase
        ? (lang === 'en' ? 'Noble Visit' : '貴族来訪')
        : null;
    const summaryText = rumorDungeon
      ? (lang === 'en'
        ? `Rumors about ${localizedDungeonName(rumorDungeon.name, lang)} are spreading.`
        : `${rumorDungeon.name}の噂が広まっています。`)
      : nobleVisitBase
        ? (lang === 'en'
          ? `A noble party returned from ${localizedBaseName(nobleVisitBase.name, lang)} satisfied with its hospitality.`
          : `貴族一行が${nobleVisitBase.name}の歓待に満足し帰還しました。`)
        : l.text;
    const duplicateKey = rumorDungeon
      ? `rumor-dungeon:${rumorDungeon.id}`
      : nobleVisitBase
        ? `noble-visit:${nobleVisitBase.id}`
        : `${isDeathLog ? 'casualty' : 'chronicle'}:${l.text.replace(/\s+/g, ' ').trim()}`;
    const duplicateItem = duplicateLogItems.get(duplicateKey);
    if (duplicateItem) {
      duplicateItem.broadcastIds = [...new Set([...(duplicateItem.broadcastIds || [duplicateItem.id]), logId])];
      duplicateItem.repeatCount = (duplicateItem.repeatCount || 1) + 1;
      const firstTurn = Math.min(duplicateItem.turn ?? l.turn, l.turn);
      duplicateItem.turn = firstTurn;
      duplicateItem.headline = summaryHeadline || turnLabel(firstTurn);
      duplicateItem.text = summaryText;
      continue;
    }

    let badge = lang === 'en' ? 'NEWS' : '王国';
    let badgeClass = '';
    let urgent = false;

    if (isDeathLog) {
      badge = lang === 'en' ? 'CASUALTY' : '訃報';
      badgeClass = 'red';
      urgent = true;
    } else if (l.type === 'major') {
      badge = lang === 'en' ? 'MAJOR' : '重大';
      badgeClass = 'gold';
    } else if (l.type === 'rumor') {
      badge = lang === 'en' ? 'RUMOR' : '噂';
      badgeClass = 'gold';
    } else if (l.type === 'warning') {
      badge = lang === 'en' ? 'ALERT' : '警告';
      badgeClass = 'red';
      urgent = true;
    } else if (l.type === 'success') {
      badge = lang === 'en' ? 'REPORT' : '朗報';
      badgeClass = 'green';
    }

    const item: KingdomNewsItem = {
      id: `log-${l.id}`,
      category: isDeathLog ? 'casualty' : 'chronicle',
      badge,
      badgeClass,
      headline: summaryHeadline || turnLabel(l.turn),
      text: summaryText,
      view: l.target?.view || (isDeathLog ? 'parties' : 'events'),
      targetId: l.target?.id,
      urgent,
      turn: l.turn,
      broadcastIds: [logId, ...(activeEvents.filter(event => activeEventBroadcastIds.get(event.id)?.includes(logId)).map(event => `event-${event.id}`))],
    };
    items.push(item);
    duplicateLogItems.set(duplicateKey, item);
  }

  // 5. Fallback if no items
  if (items.length === 0) {
    const anyFilterOn = Object.values(filters).some(Boolean);
    if (!anyFilterOn) {
      items.push({
        id: 'news-disabled',
        category: 'event',
        badge: lang === 'en' ? 'CONFIG' : '設定',
        badgeClass: 'gold',
        headline: lang === 'en' ? 'News Feed Filtered' : '配信停止中',
        text: lang === 'en'
          ? 'All news categories are deselected. Click [Filters] to select categories.'
          : 'すべてのニュースカテゴリが無効です。「選択」ボタンから流す情報を設定できます。',
        view: 'events',
      });
    } else {
      items.push({
        id: 'peace',
        category: 'chronicle',
        badge: lang === 'en' ? 'STATUS' : '王都',
        badgeClass: 'green',
        headline: lang === 'en' ? 'Kingdom at Peace' : '平穏な王都',
        text: lang === 'en'
          ? 'The kingdom is peaceful. Trade caravans and adventurers travel safely.'
          : '王国全土は平穏です。街道には旅人や冒険者が行き交っています。',
        view: 'events',
      });
    }
  }

  return items.sort((a, b) => (a.turn ?? s.turn) - (b.turn ?? s.turn));
}

export function kingdomNewsTicker(s: GameState, lang: Language, ui?: Partial<UIState>): string {
  const speed = ui?.tickerSpeed || 'slow';
  const isPaused = Boolean(ui?.tickerPaused);
  const filters: NewsFilterSettings = { ...DEFAULT_NEWS_FILTERS, ...(ui?.newsFilters || {}) };
  const broadcastedIds = new Set(ui?.broadcastedCasualties || []);
  const allItems = getKingdomNews(s, lang, filters, broadcastedIds);
  const itemBroadcastIds = (item: KingdomNewsItem) => item.broadcastIds || [item.id];
  const queueItems = allItems.filter(item => item.id !== 'peace' && item.id !== 'news-disabled');
  const currentItem = (queueItems[0] || allItems[0])!;
  const hasQueuedTopic = queueItems.length > 0;
  const hasCasualty = hasQueuedTopic && currentItem.category === 'casualty';
  const hasBulletin = hasQueuedTopic && !hasCasualty;
  const broadcastIds = hasQueuedTopic ? [...new Set(itemBroadcastIds(currentItem))] : [];
  const tickerBroadcastIds = broadcastIds;
  const itemHtml = [currentItem].map(item => {
    const itemIsCasualty = hasQueuedTopic && item.category === 'casualty';
    const itemIds = [...new Set(itemBroadcastIds(item))];
    return `
      <button class="news-ticker-item ${item.urgent ? 'urgent' : ''} ${hasQueuedTopic ? (itemIsCasualty ? 'casualty-ticker-item' : 'bulletin-ticker-item') : 'status-ticker-item'}" data-action="navigate" ${hasQueuedTopic ? `data-broadcast-ids="${esc(itemIds.join(','))}"` : ''} ${itemIsCasualty ? `data-casualty-id="${esc(item.id)}"` : ''} data-view="${item.view}" ${item.targetId ? `data-id="${esc(item.targetId)}"` : ''} title="${esc(item.text)}">
        <span class="news-tag ${item.badgeClass}">${esc(item.badge)}</span>
        <span class="news-headline">${esc(item.headline)}${item.repeatCount && item.repeatCount > 1 ? ` ×${item.repeatCount}` : ''}</span>
        <span class="news-desc">${esc(item.text)}</span>
        ${item.remaining ? `<span class="news-time">${esc(item.remaining)}</span>` : ''}
      </button>
      <span class="news-sep ${itemIsCasualty ? 'casualty-sep' : 'bulletin-sep'}" aria-hidden="true">✦</span>
    `;
  }).join('');
  const labelTitle = t('nav_events', lang);

  const rootClass = [
    'kingdom-news-ticker',
    `speed-${speed}`,
    isPaused ? 'is-paused' : '',
    hasCasualty ? 'has-casualty-alert' : '',
    hasBulletin ? 'has-bulletin-alert' : '',
  ].filter(Boolean).join(' ');

  const labelClass = [
    'news-ticker-label',
    hasCasualty ? 'casualty-active' : hasBulletin ? 'bulletin-active' : '',
  ].filter(Boolean).join(' ');

  const pauseClass = [
    'news-ticker-ctrl-btn',
    isPaused ? 'active' : '',
  ].filter(Boolean).join(' ');

  return `
    <div class="${rootClass}" role="region" aria-label="${lang === 'en' ? 'Kingdom News' : '王国の出来事ニュース'}">
      <button class="${labelClass}" data-action="navigate" data-view="${hasQueuedTopic ? currentItem.view : 'events'}" ${hasQueuedTopic && currentItem.targetId ? `data-id="${esc(currentItem.targetId)}"` : ''} ${hasQueuedTopic ? `data-broadcast-ids="${esc(broadcastIds.join(','))}"` : ''} title="${hasCasualty ? (lang === 'en' ? 'Kingdom Events (Casualty Alert)' : '王国の出来事（訃報あり）') : hasQueuedTopic ? (lang === 'en' ? 'Current news topic' : '表示中のニュース') : `${esc(labelTitle)}を開く`}">
        <span class="news-ticker-icon" aria-hidden="true">${gameIcon('events')}</span>
        <span class="news-ticker-title">${esc(labelTitle)}</span>
        <span class="news-ticker-beacon" aria-hidden="true"></span>
      </button>
      <div class="news-ticker-marquee">
        <div class="news-casualty-lane news-topic-lane" aria-live="${queueItems.some(item => item.urgent) ? 'assertive' : 'polite'}">
          <div class="news-casualty-track news-topic-track news-one-time-track${hasQueuedTopic ? '' : ' is-static'}" data-broadcast-ids="${esc(tickerBroadcastIds.join(','))}">
            ${itemHtml}
          </div>
        </div>
      </div>
      <div class="news-ticker-controls">
        <button class="news-ticker-ctrl-btn" data-action="open-news-filter" title="${lang === 'en' ? 'Select news items to display' : 'ニュースに流れる情報を選択'}">
          <span>${lang === 'en' ? 'Filters' : '選択'}</span>
        </button>
        <button class="news-ticker-ctrl-btn" data-action="toggle-ticker-speed" title="${lang === 'en' ? 'Toggle scroll speed' : 'スクロール速度を切り替え（遅め・標準）'}">
          <span>${speed === 'normal' ? (lang === 'en' ? 'Normal' : '標準') : (lang === 'en' ? '🐢 Slow' : '🐢 遅め')}</span>
        </button>
        <button class="${pauseClass}" data-action="toggle-ticker-pause" title="${lang === 'en' ? (isPaused ? 'Resume scroll' : 'Pause scroll') : (isPaused ? 'ニュースのスクロール再開' : 'ニュースのみ停止')}">
          <span aria-hidden="true">${isPaused ? '▶' : '⏸'}</span>
        </button>
        ${hasQueuedTopic ? `
          <button class="news-ticker-ctrl-btn casualty-dismiss-btn" data-action="dismiss-news" data-ids="${esc(broadcastIds.join(','))}" title="${lang === 'en' ? 'Mark this news topic as read' : 'このニュースを既読にする'}">
            <span>${lang === 'en' ? '✕ Read' : '✕ 既読'}</span>
          </button>
        ` : ''}
        <button class="news-ticker-all" data-action="navigate" data-view="events" title="${lang === 'en' ? `Open ${esc(labelTitle)}` : `${esc(labelTitle)}を開く`}">
          <span>${lang === 'en' ? 'Chronicle ↗' : '出来事一覧 ↗'}</span>
        </button>
      </div>
    </div>
  `;
}

export function newsFilterModal(
  lang: Language,
  filters: NewsFilterSettings,
  speed?: 'slow' | 'normal'
): { title: string; body: string; footer: string } {
  const isJa = lang === 'ja';
  const categories: Array<{ id: NewsCategory; label: string; desc: string; badge: string; badgeClass: string }> = [
    {
      id: 'casualty',
      label: isJa ? '冒険者戦死速報' : 'Adventurer Casualties',
      desc: isJa ? 'パーティメンバーの戦死情報（ループせず一度だけ速報で流れます）' : 'Bulletins when party members fall in battle (broadcast once without looping)',
      badge: isJa ? '訃報' : 'CASUALTY',
      badgeClass: 'red',
    },
    {
      id: 'event',
      label: isJa ? '王国の出来事・事件' : 'Kingdom Incidents & Events',
      desc: isJa ? 'ドラゴン襲来、山賊、ギルドの指令、流行、品薄などの進行中事象' : 'Dragons, bandits, guild hunts, trends, and market shortages',
      badge: isJa ? '出来事' : 'EVENT',
      badgeClass: 'gold',
    },
    {
      id: 'legend',
      label: isJa ? '伝承・聖剣' : 'Legend & Holy Sword',
      desc: isJa ? '聖剣の担い手などの王国伝承情報' : 'Bearer of the Holy Sword and legendary relics',
      badge: isJa ? '伝承' : 'LEGEND',
      badgeClass: 'gold',
    },
    {
      id: 'chronicle',
      label: isJa ? '王国記録・年代記' : 'Chronicle Logs',
      desc: isJa ? '討伐報告、キャラバン到着、噂、重大ニュースなどの年代記記録' : 'Conquest reports, caravan arrivals, rumors, and major kingdom notices',
      badge: isJa ? '王国' : 'CHRONICLE',
      badgeClass: 'green',
    },
  ];

  const itemsHtml = categories.map(cat => {
    const checked = filters[cat.id];
    return `
      <div class="news-filter-row ${checked ? 'is-active' : ''}">
        <label class="news-filter-label" style="display: flex; align-items: flex-start; gap: 0.75rem; width: 100%; cursor: pointer;">
          <input type="checkbox" data-action="toggle-news-filter" data-category="${cat.id}" ${checked ? 'checked' : ''} style="margin-top: 0.25rem;">
          <span class="news-tag ${cat.badgeClass}">${esc(cat.badge)}</span>
          <div class="news-filter-info" style="display: flex; flex-direction: column; gap: 0.2rem;">
            <strong class="news-filter-title">${esc(cat.label)}</strong>
            <span class="news-filter-desc subtle" style="font-size: 0.85rem;">${esc(cat.desc)}</span>
          </div>
        </label>
      </div>
    `;
  }).join('');

  const body = `
    <div class="news-filter-modal-content">
      <p class="subtle" style="margin-bottom: 1rem;">
        ${isJa
          ? '画面上部のニュースティッカーに流れる情報を選択できます。好みに合わせて表示を切り替えてください。'
          : 'Select which categories of information appear in the top news ticker. Changes apply immediately.'}
      </p>
      
      <div class="news-filter-list" style="display: flex; flex-direction: column; gap: 0.75rem;">
        ${itemsHtml}
      </div>

      <div class="news-filter-bulk-actions actions" style="margin-top: 1.25rem; display: flex; gap: 0.5rem;">
        <button class="btn secondary" data-action="news-filter-all" data-enable="true">
          ${isJa ? 'すべて選択' : 'Select All'}
        </button>
        <button class="btn secondary" data-action="news-filter-all" data-enable="false">
          ${isJa ? 'すべて解除' : 'Deselect All'}
        </button>
      </div>

      <hr style="margin: 1.25rem 0; border: none; border-top: 1px solid var(--border, #444);">

      <h4>${isJa ? 'スクロール速度' : 'Scroll Speed'}</h4>
      <div class="actions" style="margin-top: 0.5rem; display: flex; gap: 0.5rem;">
        <button class="btn chip ${speed !== 'normal' ? 'active' : ''}" data-action="set-ticker-speed" data-speed="slow">
          ${isJa ? '遅め（読みやすい）' : 'Slow (Readable)'}
        </button>
        <button class="btn chip ${speed === 'normal' ? 'active' : ''}" data-action="set-ticker-speed" data-speed="normal">
          ${isJa ? '標準（テンポよく）' : 'Normal'}
        </button>
      </div>
    </div>
  `;

  return {
    title: isJa ? 'ニュース配信設定' : 'News Feed Settings',
    body,
    footer: `<button class="btn primary" data-action="close-modal">${isJa ? '完了' : 'Done'}</button>`,
  };
}
