import { parseSave } from '../game/persistence.ts';
import type { GameState } from '../game/model.ts';

const SAVE_KEY = 'frontier-ledger-save-v1';
const UI_SAVE_KEY = 'frontier-ledger-ui-v1';
const COMPACT_SAVE_TAG = '__frontierLedgerCompactSave';

function compactValue(value: unknown, keyIds: Map<string, string>, keys: string[]): unknown {
  if (Array.isArray(value)) return value.map(item => compactValue(item, keyIds, keys));
  if (!value || typeof value !== 'object') return value;

  const compacted: Record<string, unknown> = Object.create(null);
  for (const [key, item] of Object.entries(value)) {
    let id = keyIds.get(key);
    if (id === undefined) {
      id = keys.length.toString(36);
      keyIds.set(key, id);
      keys.push(key);
    }
    compacted[id] = compactValue(item, keyIds, keys);
  }
  return compacted;
}

function expandValue(value: unknown, keys: string[]): unknown {
  if (Array.isArray(value)) return value.map(item => expandValue(item, keys));
  if (!value || typeof value !== 'object') return value;

  const expanded: Record<string, unknown> = Object.create(null);
  for (const [id, item] of Object.entries(value)) {
    const key = keys[Number.parseInt(id, 36)];
    if (key === undefined) throw new Error('保存データのキー情報が壊れています。');
    expanded[key] = expandValue(item, keys);
  }
  return expanded;
}

export function compactSave(state: GameState): string {
  const keys: string[] = [];
  const data = compactValue(state, new Map(), keys);
  return JSON.stringify({ [COMPACT_SAVE_TAG]: 1, keys, data });
}

function parseStoredSave(raw: string): GameState {
  let stored: unknown;
  try {
    stored = JSON.parse(raw);
  } catch {
    return parseSave(raw);
  }

  if (stored && typeof stored === 'object' && !Array.isArray(stored)
    && (stored as Record<string, unknown>)[COMPACT_SAVE_TAG] === 1) {
    const envelope = stored as Record<string, unknown>;
    if (!Array.isArray(envelope.keys) || envelope.keys.some(key => typeof key !== 'string')
      || !envelope.data || typeof envelope.data !== 'object') {
      throw new Error('保存データのキー情報が壊れています。');
    }
    const expanded = JSON.stringify(expandValue(envelope.data, envelope.keys as string[]));
    if (expanded === undefined) throw new Error('保存データを読み取れませんでした。');
    return parseSave(expanded);
  }

  return parseSave(raw);
}

export interface PersistentUIState {
  view?: string;
  base?: string;
  intelAdBase?: string;
  intelAdDungeon?: string;
  dungeon?: string;
  region?: string;
  selectedDungeon?: string;
  baseTab?: string;
  disclosures?: Record<string, boolean>;
  newsExpanded?: boolean;
  myPageWidgets?: string[];
}

export function loadLocal(storage: Storage = globalThis.localStorage): GameState | null {
  const raw = storage.getItem(SAVE_KEY);
  return raw ? parseStoredSave(raw) : null;
}

export function saveLocal(state: GameState, storage: Storage = globalThis.localStorage): void {
  storage.setItem(SAVE_KEY, compactSave(state));
}

export function clearLocal(storage: Storage = globalThis.localStorage): void {
  storage.removeItem(SAVE_KEY);
  storage.removeItem(UI_SAVE_KEY);
}

export function loadLocalUI(storage: Storage = globalThis.localStorage): PersistentUIState | null {
  try {
    const raw = storage.getItem(UI_SAVE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

export function saveLocalUI(ui: PersistentUIState, storage: Storage = globalThis.localStorage): void {
  try {
    storage.setItem(UI_SAVE_KEY, JSON.stringify(ui));
  } catch {}
}

export function clearLocalUI(storage: Storage = globalThis.localStorage): void {
  try {
    storage.removeItem(UI_SAVE_KEY);
  } catch {}
}
