import { JOBS } from './config.ts';
import { createDefaultEquipment } from './equipment.ts';
import { makePartyAware, refreshAllDungeonMetrics } from './awareness.ts';
import { memberStatsForLevel } from './member-stats.ts';
import { syncPartySkills } from './skills.ts';
import { log, makeParty } from './state.ts';
import type { ActionResult, AdventurerLogEntry, AdventurerWatchSnapshot, GameState, Job, SponsoredAdventurer } from './model.ts';

const ok = (message: string): ActionResult => ({ ok: true, message });
const fail = (message: string): ActionResult => ({ ok: false, message });

function addWatchLog(s: GameState, adventurer: SponsoredAdventurer, kind: AdventurerLogEntry['kind'], text: string): void {
  adventurer.logs.push({ turn: s.turn, kind, text });
  if (adventurer.logs.length > 80) adventurer.logs.splice(0, adventurer.logs.length - 80);
}

function snapshotOf(s: GameState, partyId: string, memberId: number): AdventurerWatchSnapshot | undefined {
  const party = s.parties.find(candidate => candidate.id === partyId);
  const member = party?.members.find(candidate => candidate.id === memberId);
  if (!party || !member) return undefined;
  return {
    action: party.action,
    location: party.location,
    dungeonId: party.currentDungeonId,
    floor: party.floor,
    memberCount: party.members.filter(candidate => candidate.status !== 'dead').length,
    memberStatus: member.status,
  };
}

export function createSponsoredAdventurer(s: GameState, baseId: string, rawName: string, job: Job): ActionResult {
  const base = s.bases.find(candidate => candidate.id === baseId && !candidate.abandoned);
  const name = rawName.trim();
  if (!base || base.facilities.shop < 3 || !s.adventurerCreationPending.includes(baseId)) return fail('冒険者の支援を始められる商店が見つかりません。');
  if (!name || name.length > 24) return fail('名前は1〜24文字で入力してください。');
  if (!(JOBS as readonly string[]).includes(job)) return fail('職業を選択してください。');
  if (s.sponsoredAdventurers.some(adventurer => adventurer.baseId === baseId)) return fail('この商店から支援する冒険者は作成済みです。');

  const party = makeParty(s, 'E', 4);
  const member = party.members[0];
  if (!member) return fail('冒険者の初期データを作成できませんでした。');
  member.name = name;
  member.job = job;
  member.rank = 'E';
  member.level = 3;
  member.experience = 0;
  member.status = 'healthy';
  const stats = memberStatsForLevel(job, member.level, member.growthSeed);
  Object.assign(member, stats);
  member.hp = stats.maxHp;
  member.equipment = 1;
  member.gear = createDefaultEquipment(job, 3, 1, member.id);
  party.name = `${name}の冒険団`;
  party.action = 'resting';
  party.timer = 1;

  const dungeon = s.dungeons.find(d => d.id === base.dungeonId);
  if (dungeon) {
    makePartyAware(s, party, dungeon);
  }

  syncPartySkills(party);
  s.parties.push(party);
  refreshAllDungeonMetrics(s);

  const adventurer: SponsoredAdventurer = {
    id: `a${s.nextId++}`,
    name,
    job,
    level: 3,
    baseId,
    partyId: party.id,
    memberId: member.id,
    createdTurn: s.turn,
    status: 'active',
    logs: [
      { turn: s.turn, kind: 'activity', text: `${name}は仲間3人と共に${party.name}を結成し、${base.name}の専属PTとして登録した。` },
      { turn: s.turn, kind: 'decision', text: '仲間と共に初遠征に向けて準備を整える。' },
    ],
    lastObserved: snapshotOf(s, party.id, member.id),
  };
  s.sponsoredAdventurers.push(adventurer);
  s.adventurerCreationPending = s.adventurerCreationPending.filter(id => id !== baseId);
  log(s, `${name}が仲間と共に専属PT「${party.name}」（4名）を結成し、${base.name}での活動を開始しました。`, 'success', { view: 'adventurer-watch', id: adventurer.id });
  return ok('冒険者を作成しました。');
}

function transitionLog(s: GameState, adventurer: SponsoredAdventurer, party: GameState['parties'][number], previous: AdventurerWatchSnapshot, current: AdventurerWatchSnapshot): void {
  const dungeonName = s.dungeons.find(dungeon => dungeon.id === current.dungeonId)?.name || '迷宮';
  if (current.memberCount > previous.memberCount) {
    addWatchLog(s, adventurer, 'activity', `仲間が加わり、PTは${current.memberCount}人になった。`);
  }
  if (party.action !== previous.action) {
    switch (party.action) {
      case 'reforming':
        addWatchLog(s, adventurer, 'activity', '仲間を集めるため、PTの募集を続ける。');
        break;
      case 'resting':
        addWatchLog(s, adventurer, 'decision', '体力と装備を整えてから、次の遠征に出ることにした。');
        break;
      case 'traveling':
        addWatchLog(s, adventurer, 'decision', `${dungeonName}へ向かうことを決め、商館を出発した。`);
        break;
      case 'visiting':
        addWatchLog(s, adventurer, 'activity', `${dungeonName}の商館に到着し、補給を始めた。`);
        break;
      case 'exploring':
        addWatchLog(s, adventurer, 'decision', `${dungeonName}の探索を開始した。`);
        break;
      case 'returning':
        addWatchLog(s, adventurer, 'decision', 'これ以上の探索は避け、迷宮から戻る判断をした。');
        break;
      case 'homeward':
        addWatchLog(s, adventurer, 'activity', '遠征を終え、王国への帰路についた。');
        break;
      case 'hunting':
        addWatchLog(s, adventurer, 'decision', '次の遠征に備えて、近場で資金を稼ぐことにした。');
        break;
      case 'healing':
        addWatchLog(s, adventurer, 'activity', '負傷を治すため、治療を受けることにした。');
        break;
    }
  } else if (party.action === 'exploring' && current.floor !== previous.floor) {
    if (current.floor > previous.floor) {
      addWatchLog(s, adventurer, 'activity', `${dungeonName}の第${current.floor}階へ進んだ。`);
      addWatchLog(s, adventurer, 'decision', '進路を確かめながら、探索を続けることにした。');
    } else {
      addWatchLog(s, adventurer, 'decision', '危険を避けるため、探索中の階層から後退した。');
    }
  } else if (current.dungeonId !== previous.dungeonId && current.dungeonId && party.action !== 'traveling') {
    addWatchLog(s, adventurer, 'activity', `次の目的地を${dungeonName}に定めた。`);
  }
}

export function tickSponsoredAdventurers(s: GameState): void {
  for (const adventurer of s.sponsoredAdventurers) {
    const party = s.parties.find(candidate => candidate.id === adventurer.partyId);
    const member = party?.members.find(candidate => candidate.id === adventurer.memberId);
    if (!party || !member) {
      if (adventurer.status !== 'dead' && adventurer.status !== 'lost') {
        adventurer.status = 'lost';
        addWatchLog(s, adventurer, 'activity', 'PTの記録が途絶えた。');
      }
      continue;
    }

    if (member.level > adventurer.level) {
      addWatchLog(s, adventurer, 'activity', `${adventurer.name}はLV${member.level}に成長した。`);
    }
    adventurer.level = member.level;
    if (member.status === 'dead' && adventurer.status !== 'dead') {
      addWatchLog(s, adventurer, 'activity', `${adventurer.name}は遠征中に倒れた。`);
      adventurer.status = 'dead';
    } else if (member.status !== 'dead') {
      adventurer.status = 'active';
    }

    const current = snapshotOf(s, party.id, member.id);
    if (current && adventurer.lastObserved) transitionLog(s, adventurer, party, adventurer.lastObserved, current);
    if (current) adventurer.lastObserved = current;
  }
}
